DROP TABLE IF EXISTS `historical_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `historical_events` (
  `id` varchar(160) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `slug` varchar(180) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `title` varchar(500) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `short_title` varchar(255) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `event_level` enum('collection','atomic') COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `event_type` enum('military','political','economic','cultural') COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `event_subtype` varchar(120) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `start_year` int DEFAULT NULL,
  `end_year` int DEFAULT NULL,
  `effective_end_year` int DEFAULT NULL,
  `display_date` varchar(120) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `date_precision` varchar(40) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `geo_type` enum('single_point','multi_region','nationwide','no_location','point','multi_point','multi_polygon','mixed') COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `lat` decimal(10,7) DEFAULT NULL,
  `lng` decimal(10,7) DEFAULT NULL,
  `province_names` json DEFAULT NULL,
  `historical_locations` json DEFAULT NULL,
  `parent_id` varchar(160) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `root_id` varchar(160) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `level` int NOT NULL DEFAULT '0',
  `order_in_parent` int NOT NULL DEFAULT '0',
  `card_summary` varchar(1000) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `canonical_summary` text COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `detailed_narrative` mediumtext COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `significance` text COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `show_on_homepage` tinyint(1) NOT NULL DEFAULT '1',
  `show_on_timeline` tinyint(1) NOT NULL DEFAULT '1',
  `featured` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('draft','published','archived') COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'published',
  `content_hash` char(64) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `raw_json` json NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `published_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  UNIQUE KEY `uk_events_slug` (`slug`),
  KEY `idx_events_timeline` (`status`,`show_on_timeline`,`start_year`,`effective_end_year`),
  KEY `idx_events_type_timeline` (`event_type`,`status`,`show_on_timeline`,`start_year`,`effective_end_year`),
  KEY `idx_events_geo_status` (`geo_type`,`status`),
  KEY `idx_events_featured` (`status`,`featured`),
  KEY `idx_events_parent_order` (`parent_id`,`order_in_parent`,`id`),
  KEY `idx_events_root_level_order` (`root_id`,`level`,`order_in_parent`),
  KEY `idx_events_search_year` (`status`,`start_year`,`effective_end_year`),
  CONSTRAINT `fk_events_parent` FOREIGN KEY (`parent_id`) REFERENCES `historical_events` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `fk_events_root` FOREIGN KEY (`root_id`) REFERENCES `historical_events` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `historical_events` WRITE;
