INSERT INTO `historical_events` VALUES ('bac-thanh-duoc-lap','bac-thanh-duoc-lap','Bắc Thành được lập','Bắc Thành được lập','atomic','political','administrative_division',1802,1831,1831,'1802 - 1831','year','mixed',22.6667000,106.2500000,'[\"Cao Bằng\", \"Hải Dương\", \"Hà Nội\", \"Quảng Ninh\", \"Phú Thọ\", \"Lạng Sơn\", \"Bắc Giang\", \"Thái Nguyên\", \"Hà Nam\", \"Tuyên Quang\"]','[]','viet-nam-tu-the-ki-xvi-den-xix','viet-nam-tu-the-ki-xvi-den-xix',1,5,'Bắc Thành được lập từ 1802 đến 1831, cai quản 11 trấn.','Bắc Thành là đơn vị hành chính cao hơn trấn. Bắc Thành được lập từ năm 1802 đến 1831, cai quản 11 trấn là Sơn Nam Thượng, Sơn Nam Hạ, Sơn Tây, Kinh Bắc, Hải Dương, Tuyên Quang, Hưng Hoá, Cao Bằng, Lạng Sơn, Thái Nguyên, Quảng Yên.','Bắc Thành là đơn vị hành chính cao hơn trấn. Bắc Thành được lập từ năm 1802 đến 1831, cai quản 11 trấn là Sơn Nam Thượng, Sơn Nam Hạ, Sơn Tây, Kinh Bắc, Hải Dương, Tuyên Quang, Hưng Hoá, Cao Bằng, Lạng Sơn, Thái Nguyên, Quảng Yên.','Là một trong hai khu vực hành chính phân quyền dưới thời Gia Long, sau bị bãi bỏ trong cải cách Minh Mạng.',1,1,0,'published','5486ac835fad6be9b21fa09c5d3a6953f72e43a5d3c0857f426f295067f64017','{\"_stage4bParentReason\": \"Không tìm thấy collection parent cụ thể; gán theo root period dựa trên năm.\", \"_stage4bParentSource\": \"fallback_root_by_year\", \"associations\": {\"predecessorEventIds\": [], \"relatedEventIds\": [], \"relatedFigureIds\": [], \"successorEventIds\": []}, \"chronology\": {\"datePrecision\": \"year\", \"displayDate\": \"1802 - 1831\", \"end\": {\"day\": null, \"month\": null, \"year\": 1831}, \"isApproximate\": false, \"start\": {\"day\": null, \"month\": null, \"year\": 1802}}, \"classification\": {\"eventSubtype\": \"administrative_division\", \"eventType\": \"political\", \"region\": \"vietnam\", \"tags\": [\"Bắc Thành\", \"đơn vị hành chính\", \"triều Nguyễn\"]}, \"coverage\": {\"books\": [\"KNTT\"], \"grades\": [11], \"lessons\": [{\"grade\": 11, \"lessonId\": \"12393\", \"l