INSERT INTO `historical_events` VALUES ('khang-chien-toan-quoc-chong-thuc-dan-phap-bung-no','khang-chien-toan-quoc-chong-thuc-dan-phap-bung-no','Kháng chiến toàn quốc chống thực dân Pháp bùng nổ','Kháng chiến toàn quốc chống thực dân Pháp bùng nổ','atomic','military','uprising',1946,NULL,1946,'Tháng 12 năm 1946','month','no_location',NULL,NULL,'[]','[]','viet-nam-1945-1954','viet-nam-1945-1954',1,8,'Kháng chiến toàn quốc chống thực dân Pháp bùng nổ vào tháng 12 năm 1946.','Cuộc kháng chiến toàn quốc chống thực dân Pháp bùng nổ (12 – 1946).','Từ khi cuộc kháng chiến toàn quốc chống thực dân Pháp bùng nổ (12 – 1946), Việt Nam vẫn thể hiện thiện chí hoà bình, để nghị Chính phủ Pháp tiếp tục mở các cuộc thương lượng, kêu gọi nhân dân Pháp chống chiến tranh.',NULL,0,1,0,'published','8424670f97e184c5f78d4a1af259a9085aa87db79e90b438f1e868ff7944c2f3','{\"_stage4bParentReason\": \"Không tìm thấy collection parent cụ thể; gán theo root period dựa trên năm.\", \"_stage4bParentSource\": \"fallback_root_by_year\", \"associations\": {\"predecessorEventIds\": [], \"relatedEventIds\": [], \"relatedFigureIds\": [], \"successorEventIds\": []}, \"chronology\": {\"datePrecision\": \"month\", \"displayDate\": \"Tháng 12 năm 1946\", \"end\": null, \"isApproximate\": false, \"start\": {\"day\": null, \"month\": 12, \"year\": 1946}}, \"classification\": {\"eventSubtype\": \"uprising\", \"eventType\": \"military\", \"region\": \"vietnam\", \"tags\": [\"kháng chiến\", \"toàn quốc\", \"chống Pháp\"]}, \"coverage\": {\"books\": [\"KNTT\"], \"grades\": [12], \"lessons\": [{\"grade\": 12, \"lessonId\": \"12964\", \"lessonTitle\": \"BÀI 13: HOẠT ĐỘNG ĐỐI NGOẠI CỦA VIỆT NAM TRONG KHÁNG CHIẾN CHỐNG PHÁP (1945 – 1954) VÀ KHÁNG CHIẾN CHỐNG MỸ (1954 - 1975)\"}]}, \"display\": {\"featured\": false, \"priority\": 0, \"showOnMap\": false, \"showOnOverviewTimeline\": false, \"showOnTimeline\": true}, \"entityType\": \"event\", \"eventLevel\": \"atomic\", \"externalContent\": {\"otherSources\": [], \"wikidata\": {\"id\": \"\", \"url\": \"\"}, \"wikipedia\": {\"content\": \"\", \"summary\": \"\", \"title\": \"\", \"url\": \"\"}}, \"hierarchy\": {\"childIds\": [], \"level\": 1, \"orderInParent\": 8, \"parentId\": \"viet-nam-1945-1954\", \"rootId\": \"viet-nam-1945-1954\"}, \"id\": \"khang-chien-toan-quoc-chong-thuc-dan-phap-bung-no\", \"mapData\": {\"focusGeometry\": {\"center\": null, \"mode\": \"auto\", \"zoom\": null}, \"gadmRefs\": [], \"geoType\": \"no_location\", \"historicalLocations\": [], \"marker\": null, \"markers\": [], \"provinceNames\": []}, \"media\": {\"items\": [], \"thumbnail\": \"\"}, \"slug\": \"khang-chien-toan-quoc-chong-thuc-dan-phap-bung-no\", \"sourcePolicy\": {\"lastUpdated\": \"\", \"primarySource\": \"textbook\", \"supplementalSources\": [\"wikipedia\", \"wikidata\"]}, \"summary\": {\"cardSummary\": \"Kháng chiến toàn quốc chống thực dân Pháp bùng nổ vào tháng 12 năm 1946.\", \"homepageSummary\": \"Cuộc kháng chiến toàn quốc chống thực dân Pháp bùng nổ vào tháng 12 năm 1946.\", \"homepageTitle\": \"Kháng chiến toàn quốc chống Pháp bùng nổ\"}, \"textbookContent\": {\"canonicalSummary\": \"Cuộc kháng chiến toàn quốc chống thực dân Pháp bùng nổ (12 – 1946).\", \"detailedNarrative\": \"Từ khi cuộc kháng chiến toàn quốc chống thực dân Pháp bùng nổ (12 – 1946), Việt Nam vẫn thể hiện thiện chí hoà bình, để nghị Chính phủ Pháp tiếp tục mở các cuộc thương lượng, kêu gọi nhân dân Pháp chống chiến tranh.\", \"keyFacts\": [\"Bùng nổ vào tháng 12-1946\"], \"significance\": null, \"textbookRefs\": [{\"book\": \"KNTT\", \"chapter\": \"Chu de 4\", \"excerpt\": \"Cuộc kháng chiến toàn quốc chống thực dân Pháp bùng nổ (12 – 1946).\", \"grade\": 12, \"lesson\": \"Bai 13\", \"lessonId\": \"12964\", \"lessonTitle\": \"BÀI 13: HOẠT ĐỘNG ĐỐI NGOẠI CỦA VIỆT NAM TRONG KHÁNG CHIẾN CHỐNG PHÁP (1945 – 1954) VÀ KHÁNG CHIẾN CHỐNG MỸ (1954 - 1975)\", \"pageRange\": {\"end\": 81, \"start\": 77}, \"url\": \"https://sgkvn.com/lop-12-15/ket-noi-tri-thuc-voi-cuoc-song-3/chu-de-4-cong-cuoc-doi-moi-o-viet-nam-tu-nam-1986-den-nay-3540/bai-13-hoat-dong-doi-ngoai-cua-viet-nam-trong-khang-chien-chong-phap-1945-1954-va-khang-chien-chong-my-1954-1975-12964.html\"}]}, \"titles\": {\"alternatives\": [], \"primary\": \"Kháng chiến toàn quốc chống thực dân Pháp bùng nổ\", \"short\": \"Kháng chiến toàn quốc chống thực dân Pháp bùng nổ\"}}','2026-06-29 00:11:30','2026-06-29 00:11:43','2026-06-29 00:11:30'),('khoi-nghia-ba-trieu','khoi-nghia-ba-trieu','Khởi nghĩa Bà Triệu','Khởi nghĩa Bà Triệu','atomic','military','uprising',248,NULL,248,'248','year','mixed',21.0285000,105.8542000,'[\"Thanh Hóa\"]','[]','bac-thuoc-va-dau-tranh-gianh-doc-lap','bac-thuoc-va-dau-tranh-gianh-doc-lap',1,2,'Khởi nghĩa Bà Triệu (248) chống nhà Ngô, lan rộng ra Giao Chỉ nhưng bị đàn áp.','Năm 248, Bà Triệu lãnh đạo nhân dân vùng Cửu Chân nổi dậy ở căn cứ núi Nưa (Triệu Sơn, Thanh Hoá). Khởi nghĩa nhanh chóng lan rộng ra Giao Chỉ, làm rung chuyển chính quyền đô hộ. Quân Ngô do Lục Dận chỉ huy kéo sang đàn áp, khởi nghĩa thất bại.','Bà Triệu lãnh đạo nhân dân vùng Cửu Chân nổi dậy ở căn cứ núi Nưa (Triệu Sơn, Thanh Hoá). Khởi nghĩa nhanh chóng lan rộng ra Giao Chỉ, làm rung chuyển chính quyền đô hộ. Quân Ngô do Lục Dận chỉ huy kéo sang đàn áp. Khởi nghĩa thất bại.',NULL,1,1,0,'published','86cfe31be96bd78f9b1bc185f3cf42062ffb1b5045e8932f958cadc14e1f8349','{\"_stage4bParentReason\": \"Không tìm thấy collection parent cụ thể; gán theo root period dựa trên năm.\", \"_stage4bParentSource\": \"fallback_root_by_year\", \"associations\": {\"predecessorEventIds\": [], \"relatedEventIds\": [], \"relatedFigureIds\": [], \"successorEventIds\": []}, \"chronology\": {\"datePrecision\": \"year\", \"displayDate\": \"248\", \"end\": null, \"isApproximate\": false, \"start\": {\"day\": null, \"month\": null, \"year\": 248}}, \"classification\": {\"eventSubtype\": \"uprising\", \"eventType\": \"military\", \"region\": \"vietnam\", \"tags\": [\"Nhà Ngô\", \"Cửu Chân\", \"Bắc thuộc\", \"Bà Triệu\"]}