INSERT INTO `historical_events` VALUES ('xay-dung-cau-long-bien','xay-dung-cau-long-bien','Xây dựng cầu Long Biên','Xây cầu Long Biên','atomic','economic','construction',1898,1902,1902,'1898 – 1902','year','mixed',21.0285000,105.8542000,'[\"Hà Nội\"]','[\"sông Hồng\"]','viet-nam-1858-1918','viet-nam-1858-1918',1,11,'Cầu Long Biên được xây dựng tại Hà Nội từ năm 1898 đến 1902.','Cầu Long Biên bắc qua sông Hồng ở Hà Nội được xây dựng trong thời gian từ năm 1898 đến năm 1902. Trong suốt hơn một thế kỉ qua, cây cầu này đã “chứng kiến” nhiều sự kiện, quá trình lịch sử quan trọng của Thủ đô và đất nước.','Cầu Long Biên bắc qua sông Hồng ở Hà Nội được xây dựng trong thời gian từ năm 1898 đến năm 1902. Cây cầu này là một hiện vật lịch sử đã “chứng kiến” nhiều sự kiện, quá trình lịch sử quan trọng của Thủ đô và đất nước.','Là một hiện vật lịch sử quan trọng, chứng kiến nhiều sự kiện lịch sử của Thủ đô và đất nước.',1,1,0,'published','efa7f48624fbe21a4594d45e5474a7b40e7cafffaa0c0c3aa080843a15ad472b','{\"_stage4bParentReason\": \"Không tìm thấy collection parent cụ thể; gán theo root period dựa trên năm.\", \"_stage4bParentSource\": \"fallback_root_by_year\", \"associations\": {\"predecessorEventIds\": [], \"relatedEventIds\": [], \"relatedFigureIds\": [], \"successorEventIds\": []}, \"chronology\": {\"datePrecision\": \"year\", \"displayDate\": \"1898 – 1902\", \"end\": {\"day\": null, \"month\": null, \"year\": 1902}, \"isApproximate\": false, \"start\": {\"day\": null, \"month\": null, \"year\": 1898}}, \"classification\": {\"eventSubtype\": \"construction\", \"eventType\": \"economic\", \"region\": \"vietnam\", \"tags\": [\"Hà Nội\", \"cầu\", \"kiến trúc\"]}, \"coverage\": {\"books\": [\"KNTT\"], \"grades\": [10], \"lessons\": [{\"grade\": 10, \"lessonId\": \"12122\", \"lessonTitle\": \"Bài 1: Hiện Thực Lịch Sử Và Nhận Thức Lịch Sử\"}]}, \"display\": {\"featured\": false, \"priority\": 0, \"showOnMap\": true, \"showOnOverviewTimeline\": false, \"showOnTimeline\": true}, \"