UNLOCK TABLES;
DROP TABLE IF EXISTS `event_textbook_refs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `event_textbook_refs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `event_id` varchar(160) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `grade` tinyint NOT NULL,
  `book` varchar(255) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `theme` varchar(500) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `lesson` varchar(500) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `page_start` int DEFAULT NULL,
  `page_end` int DEFAULT NULL,
  `excerpt` text COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `source_key` varchar(180) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `idx_refs_event` (`event_id`),
  KEY `idx_refs_grade_lesson` (`grade`,`lesson`),
  KEY `idx_refs_source_key` (`source_key`),
  CONSTRAINT `fk_event_textbook_refs_event` FOREIGN KEY (`event_id`) REFERENCES `historical_events` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci AUTO_INCREMENT=120252;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `event_textbook_refs` WRITE;
/*!40000 ALTER TABLE `event_textbook_refs` DISABLE KEYS */;
INSERT INTO `event_textbook_refs` VALUES (60647,'su-ra-doi-nha-nuoc-au-lac',10,'KNTT',NULL,'Bai 11',NULL,NULL,'Tiếp nối Nhà nước Văn Lang là Nhà nước Âu Lạc (208 – 179 TCN); kinh đô ở Cổ Loa (Đông Anh, Hà Nội ngày nay); đứng đầu nhà nước là Thục Phán – An Dương Vương; giúp việc cho vua cũng là Lạc hầu; dưới địa phương vẫn do các Lạc tướng cai quản.','SGK10:su-ra-doi-nha-nuoc-au-lac','2026-06-30 00:27:07'),(60648,'khang-chien-chong-quan-trieu-an-duong-vuong',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Cuộc kháng chiến chống quân Triệu của An Dương Vương diễn ra vào năm 179 TCN. Sau nhiều lần tấn công Âu Lạc thất bại, Triệu Đà vờ giảng hoà, cho con trai là Trọng Thuỷ cầu hôn Công chúa Mỵ Châu và ở rể tại thành Cổ Loa để tìm hiểu vũ khí quân sự của Âu Lạc. Năm 179 TCN, Triệu Đà đem quân tấn công Âu Lạc. Cuộc kháng chiến của An Dương Vương nhanh chóng thất bại.','SGK11:khang-chien-chong-quan-trieu-an-duong-vuong','2026-06-30 00:27:07'),(60649,'khoi-nghia-hai-ba-trung',10,'KNTT',NULL,'Bai 14',NULL,NULL,'Khởi nghĩa Hai Bà Trưng diễn ra từ năm 40 đến năm 43. Hai Bà Trưng dựng cờ khởi nghĩa ở Hát Môn, đánh chiếm Mê Linh, Cổ Loa và Luy Lâu, khiến Thái thú Tô Định phải bỏ chạy. Trưng Trắc lên làm vua. Năm 43, Mã Viện đem quân tấn công, khởi nghĩa thất bại.','SGK10:khoi-nghia-hai-ba-trung','2026-06-30 00:27:07'),(60650,'khoi-nghia-hai-ba-trung',11,'KNTT',NULL,'Bai 8',NULL,NULL,'Khởi nghĩa Hai Bà Trưng diễn ra từ năm 40 đến năm 43. Hai Bà Trưng dựng cờ khởi nghĩa ở Hát Môn, đánh chiếm Mê Linh, Cổ Loa và Luy Lâu, khiến Thái thú Tô Định phải bỏ chạy. Trưng Trắc lên làm vua. Năm 43, Mã Viện đem quân tấn công, khởi nghĩa thất bại.','SGK11:khoi-nghia-hai-ba-trung','2026-06-30 00:27:07'),(60651,'khoi-nghia-khu-lien-lap-nuoc-lam-ap',10,'KNTT',NULL,'Bai 11',NULL,NULL,'Trong hai thế kỉ đầu Công nguyên, người Chăm ở quận Nhật Nam liên tục đấu tranh chống lại ách cai trị của nhà Hán. Đến năm 192, dưới sự lãnh đạo của Khu Liên (thủ lĩnh của một bộ lạc ở phía Nam quận Nhật Nam) đã nổi dậy lật đổ ách thống trị của ngoại bang, lập ra nước Lâm Ấp (sau này gọi là Chăm pa), kinh đô là Sin-ha-pu-ra (Trà Kiệu, Quảng Nam).','SGK10:khoi-nghia-khu-lien-lap-nuoc-lam-ap','2026-06-30 00:27:07'),(60652,'khoi-nghia-ba-trieu',11,'KNTT',NULL,'Bai 8',NULL,NULL,'Năm 248, Bà Triệu lãnh đạo nhân dân vùng Cửu Chân nổi dậy ở căn cứ núi Nưa (Triệu Sơn, Thanh Hoá). Khởi nghĩa nhanh chóng lan rộng ra Giao Chỉ, làm rung chuyển chính quyền đô hộ. Quân Ngô do Lục Dận chỉ huy kéo sang đàn áp, khởi nghĩa thất bại.','SGK11:khoi-nghia-ba-trieu','2026-06-30 00:27:07'),(60653,'khoi-nghia-ly-bi-trieu-quang-phuc',11,'KNTT',NULL,'Bai 8',NULL,NULL,'Năm 542, khởi nghĩa Lý Bí bùng nổ, lật đổ chính quyền đô hộ. Sau đó, Lý Bí lập ra Nhà nước Vạn Xuân. Năm 545, quân Lương tiếp tục sang xâm lược, Triệu Quang Phục lãnh đạo cuộc khởi nghĩa và giành thắng lợi. Đến năm 602, nhà Lương đem quân sang đàn áp, cuộc khởi nghĩa thất bại.','SGK11:khoi-nghia-ly-bi-trieu-quang-phuc','2026-06-30 00:27:07'),(60654,'khoi-nghia-mai-thuc-loan',11,'KNTT',NULL,'Bai 8',NULL,NULL,'Mai Thúc Loan kêu gọi nhân dân vùng Nam Đàn (Nghệ An) nổi dậy khởi nghĩa và nhanh chóng làm chủ vùng đất Hoan Châu. Sau đó, nghĩa quân tiến ra Bắc, đánh đuổi chính quyền đô hộ, làm chủ thành Tổng Bình. Cuối cùng, cuộc khởi nghĩa bị nhà Đường đàn áp.','SGK11:khoi-nghia-mai-thuc-loan','2026-06-30 00:27:07'),(60655,'khoi-nghia-khuc-thua-du',11,'KNTT',NULL,'Bai 8',NULL,NULL,'Năm 905, Khúc Thừa Dụ lãnh đạo nhân dân tấn công thành Đại La, lật đổ chính quyền đô hộ, tự xưng là Tiết độ sứ, xây dựng chính quyền tự chủ.','SGK11:khoi-nghia-khuc-thua-du','2026-06-30 00:27:07'),(60656,'chien-thang-bach-dang-938',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Chiến thắng Bạch Đằng do Ngô Quyền lãnh đạo vào năm 938 đã kết thúc ách đô hộ của phong kiến phương Bắc, mở ra thời kì độc lập tự chủ lâu dài của dân tộc.','SGK10:chien-thang-bach-dang-938','2026-06-30 00:27:07'),(60657,'chien-thang-bach-dang-938',11,'KNTT',NULL,'Bai 8',NULL,NULL,'Chiến thắng Bạch Đằng do Ngô Quyền lãnh đạo vào năm 938 đã kết thúc ách đô hộ của phong kiến phương Bắc, mở ra thời kì độc lập tự chủ lâu dài của dân tộc.','SGK11:chien-thang-bach-dang-938','2026-06-30 00:27:07'),(60658,'chien-thang-bach-dang-938',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Chiến thắng Bạch Đằng do Ngô Quyền lãnh đạo vào năm 938 đã kết thúc ách đô hộ của phong kiến phương Bắc, mở ra thời kì độc lập tự chủ lâu dài của dân tộc.','SGK11:chien-thang-bach-dang-938','2026-06-30 00:27:07'),(60659,'ngo-quyen-xung-vuong-co-loa',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Sau chiến thắng Bạch Đằng (năm 938), Ngô Quyền xưng vương, đóng đô ở Cổ Loa (Hà Nội), nền độc lập dân tộc được khôi phục hoàn toàn.','SGK10:ngo-quyen-xung-vuong-co-loa','2026-06-30 00:27:07'),(60660,'khang-chien-chong-quan-tong-981',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Cuộc kháng chiến chống quân Tống lần thứ nhất diễn ra vào năm 981, dưới sự chỉ huy của Lê Hoàn, với trận quyết chiến tại Bạch Đằng (Quảng Ninh).','SGK11:khang-chien-chong-quan-tong-981','2026-06-30 00:27:07'),(60661,'ly-thai-to-doi-do-thang-long',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1010, Lý Thái Tổ dời đô ra Thăng Long (Hà Nội), mở ra thời kì phát triển rực rỡ của văn minh Đại Việt.','SGK10:ly-thai-to-doi-do-thang-long','2026-06-30 00:27:07'),(60662,'ly-thanh-tong-dung-van-mieu',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1070, vua Lý Thánh Tông cho dựng Văn Miếu thờ Khổng Tử.','SGK10:ly-thanh-tong-dung-van-mieu','2026-06-30 00:27:07'),(60663,'khang-chien-chong-quan-tong-1075-1077',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Cuộc kháng chiến chống quân Tống lần thứ hai diễn ra từ 1075 đến 1077, dưới sự chỉ huy của Lý Thường Kiệt, với trận quyết chiến tại Phòng tuyến Như Nguyệt (Bắc Ninh).','SGK11:khang-chien-chong-quan-tong-1075-1077','2026-06-30 00:27:07'),(60664,'ly-thuong-kiet-tap-kich-kham-chau-liem-chau-ung-chau',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Trong cuộc kháng chiến chống Tống giai đoạn thứ nhất (1075), triều Lý đã thực hiện kế sách \"tiên phát chế nhân\" bằng cách chủ động tập kích Khâm Châu, Liêm Châu, Ung Châu (Trung Quốc) nhằm ngăn chặn âm mưu xâm lược của quân Tống.','SGK11:ly-thuong-kiet-tap-kich-kham-chau-liem-chau-ung-chau','2026-06-30 00:27:07'),(60665,'ly-nhan-tong-lap-quoc-tu-giam',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1076, vua Lý Nhân Tông cho lập Quốc Tử Giám (Hà Nội) làm trường học Nho giáo cao cấp của triều đình.','SGK10:ly-nhan-tong-lap-quoc-tu-giam','2026-06-30 00:27:07'),(60666,'ga-cong-chua-thieu-dung-duong-tu-minh-1144',10,'KNTT',NULL,'Bai 14',NULL,NULL,'Giáp Tý [1144], gả Công chúa Thiều Dung cho Dương Tự Minh (một thủ lĩnh người dân tộc Tày ở Thái Nguyên], phong Tự Minh làm Phò mã lang.... Tháng 5, cho Mậu Du Đô làm Thái sư, xa lĩnh việc các khê động dọc biên giới về đường bộ.','SGK10:ga-cong-chua-thieu-dung-duong-tu-minh-1144','2026-06-30 00:27:07'),(60667,'nha-ly-thanh-lap-trang-van-don',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1149, nhà Lý thành lập trang Vân Đồn (Quảng Ninh), tạo điều kiện cho thuyền buôn từ các nước như Trung Quốc, Ấn Độ, Đông Nam Á,.. đến trao đổi hàng hoá.','SGK10:nha-ly-thanh-lap-trang-van-don','2026-06-30 00:27:07'),(60668,'khang-chien-chong-quan-mong-co-1258',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Cuộc kháng chiến chống quân Mông Cổ lần thứ nhất diễn ra vào năm 1258, dưới sự chỉ huy của Trần Thái Tông và Trần Thủ Độ, với các trận quyết chiến tại Bình Lệ Nguyên (Vĩnh Phúc) và Đông Bộ Đầu (Hà Nội).','SGK11:khang-chien-chong-quan-mong-co-1258','2026-06-30 00:27:07'),(60669,'hoi-nghi-binh-than',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Để chuẩn bị cho cuộc kháng chiến chống Nguyên năm 1285, nhà Trần đã tổ chức Hội nghị Bình Than vào năm 1282, triệu tập vương hầu, quý tộc, tướng lĩnh để bàn kế sách đánh giặc.','SGK11:hoi-nghi-binh-than','2026-06-30 00:27:07'),(60670,'hoi-nghi-dien-hong',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Năm 1285, tại điện Diên Hồng ở kinh thành Thăng Long, khi Thượng hoàng Trần Thánh Tông hỏi về kế sách đánh giặc, các vị bô lão đều đồng thanh hô lớn: \"Đánh!\".','SGK11:hoi-nghi-dien-hong','2026-06-30 00:27:07'),(60671,'khang-chien-chong-quan-nguyen-1285',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Cuộc kháng chiến chống quân Nguyên lần thứ hai diễn ra vào năm 1285, dưới sự chỉ huy của Trần Thánh Tông và Trần Quốc Tuấn, với các trận quyết chiến tại Tây Kết, Hàm Tử (Hưng Yên), Chương Dương, Thăng Long (Hà Nội).','SGK11:khang-chien-chong-quan-nguyen-1285','2026-06-30 00:27:07'),(60672,'khang-chien-chong-quan-nguyen-1287-1288',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Cuộc kháng chiến chống quân Nguyên lần thứ ba diễn ra từ 1287 đến 1288, dưới sự chỉ huy của Trần Nhân Tông và Trần Quốc Tuấn, với các trận quyết chiến tại Vân Đồn – Cửa Lục và Bạch Đằng (Quảng Ninh).','SGK11:khang-chien-chong-quan-nguyen-1287-1288','2026-06-30 00:27:07'),(60673,'cai-cach-ho-quy-ly-trieu-ho',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Cải cách của Hồ Quý Ly và nhà Hồ diễn ra vào cuối thế kỉ XIV - đầu thế kỉ XV chủ yếu trên các lĩnh vực: chính trị, kinh tế, xã hội, nhằm củng cố chế độ quân chủ tập quyền và giải quyết các mâu thuẫn về kinh tế, xã hội xuất hiện cuối thời Trần.','SGK10:cai-cach-ho-quy-ly-trieu-ho','2026-06-30 00:27:07'),(60674,'cai-cach-ho-quy-ly-trieu-ho',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Cải cách của Hồ Quý Ly và nhà Hồ diễn ra vào cuối thế kỉ XIV - đầu thế kỉ XV chủ yếu trên các lĩnh vực: chính trị, kinh tế, xã hội, nhằm củng cố chế độ quân chủ tập quyền và giải quyết các mâu thuẫn về kinh tế, xã hội xuất hiện cuối thời Trần.','SGK11:cai-cach-ho-quy-ly-trieu-ho','2026-06-30 00:27:07'),(60675,'phat-hanh-tien-giay-thong-bao-hoi-sao',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Hồ Quý Ly cho phát hành tiền giấy Thông bảo hội sao. Vua hạ lệnh cho người đem tiền đến đổi, mỗi quan tiền đồng đổi lấy 1 quan 2 tiền giấy. Ai làm tiền giấy giả thì bị tội chém. Ai giấu tiền đồng, không nộp thì phải tội như làm tiền giấy giả.','SGK11:phat-hanh-tien-giay-thong-bao-hoi-sao','2026-06-30 00:27:07'),(60676,'ban-hanh-chinh-sach-han-dien',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Nhằm hạn chế quyền lực của quý tộc Trần, nhà Hồ thực hiện chính sách hạn điển. “Các đại vương và trưởng công chúa thì ruộng không hạn chế, cho đến thứ dân thì ruộng chỉ 10 mẫu thôi.\"','SGK11:ban-hanh-chinh-sach-han-dien','2026-06-30 00:27:08'),(60677,'ho-quy-ly-doi-do-thanh-hoa',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1397, Hồ Quý Ly ép vua Trần dời đô vào Thanh Hoá.','SGK11:ho-quy-ly-doi-do-thanh-hoa','2026-06-30 00:27:08'),(60678,'ho-quy-ly-lap-trieu-ho',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1400, ông buộc vua Trấn nhường ngôi, lập ra triều Hồ.','SGK11:ho-quy-ly-lap-trieu-ho','2026-06-30 00:27:08'),(60679,'ban-hanh-chinh-sach-han-no',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Nhà Hồ thực hiện chính sách hạn nô. “Phép hạn gia nó, chiếu theo phẩm cấp mà có số khác nhau, thừa ra thì sung vào Nhà nước. Mỗi người phải trả 5 quan tiến. Người nào đáng được có gia nô phải xuất trình chúc thư ba đời. Gia nô người ngoại quốc thì không có hạn lệ. Các gia nô đếu thích vào trán để đánh dấu...\"','SGK11:ban-hanh-chinh-sach-han-no','2026-06-30 00:27:08'),(60680,'khang-chien-chong-quan-minh-nha-ho',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Cuộc kháng chiến chống quân Minh của nhà Hồ diễn ra từ cuối năm 1406 đến tháng 6 năm 1407. Nhà Minh huy động một lực lượng quân đội lớn do Trương Phụ và Mộc Thạnh chỉ huy sang xâm lược Đại Ngu. Cuối tháng 1 năm 1407, quân Minh chiếm được thành Đa Bang và Đông Đô (Hà Nội). Nhà Hồ phải rút quân về cố thủ ở thành Tây Đô (Thanh Hoá). Đến tháng 6 năm 1407, cuộc kháng chiến của nhà Hồ bị thất bại.','SGK11:khang-chien-chong-quan-minh-nha-ho','2026-06-30 00:27:08'),(60681,'khang-chien-chong-quan-minh-nha-ho',11,'KNTT',NULL,'Bai 8',NULL,NULL,'Cuộc kháng chiến chống quân Minh của nhà Hồ diễn ra từ cuối năm 1406 đến tháng 6 năm 1407. Nhà Minh huy động một lực lượng quân đội lớn do Trương Phụ và Mộc Thạnh chỉ huy sang xâm lược Đại Ngu. Cuối tháng 1 năm 1407, quân Minh chiếm được thành Đa Bang và Đông Đô (Hà Nội). Nhà Hồ phải rút quân về cố thủ ở thành Tây Đô (Thanh Hoá). Đến tháng 6 năm 1407, cuộc kháng chiến của nhà Hồ bị thất bại.','SGK11:khang-chien-chong-quan-minh-nha-ho','2026-06-30 00:27:08'),(60682,'nha-minh-thong-tri-huy-diet-van-minh-dai-viet',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Từ năm 1407 đến năm 1427, nhà Minh thống trị và thực hiện chính sách huỷ diệt văn minh Đại Việt.','SGK10:nha-minh-thong-tri-huy-diet-van-minh-dai-viet','2026-06-30 00:27:08'),(60683,'hoi-the-lung-nhai',11,'KNTT',NULL,'Bai 8',NULL,NULL,'Hội thề Lũng Nhai diễn ra vào năm 1416, Lê Lợi cùng 18 hào kiệt làm lễ kết nghĩa anh em, nguyện một lòng đánh giặc cứu nước.','SGK11:hoi-the-lung-nhai','2026-06-30 00:27:08'),(60684,'khoi-nghia-lam-son',10,'KNTT',NULL,'Bai 3',NULL,NULL,'Đầu năm 1418, Lê Lợi dựng cờ khởi nghĩa tại vùng núi rừng Lam Sơn (Thanh Hoá). Cuộc khởi nghĩa trải qua bốn giai đoạn chính: hoạt động du kích và bảo vệ căn cứ (1418-1423), hoà hoãn với quân Minh (1423), chuyển hướng chiến lược vào Nghệ An và tiến quân ra Bắc (1424), phân công tiêu diệt địch trên quy mô cả nước và giành thắng lợi (1426-1427) với các chiến thắng Tốt Động - Chúc Động và Chi Lăng - Xương Giang.','SGK10:khoi-nghia-lam-son','2026-06-30 00:27:08'),(60685,'khoi-nghia-lam-son',11,'KNTT',NULL,'Bai 8',NULL,NULL,'Đầu năm 1418, Lê Lợi dựng cờ khởi nghĩa tại vùng núi rừng Lam Sơn (Thanh Hoá). Cuộc khởi nghĩa trải qua bốn giai đoạn chính: hoạt động du kích và bảo vệ căn cứ (1418-1423), hoà hoãn với quân Minh (1423), chuyển hướng chiến lược vào Nghệ An và tiến quân ra Bắc (1424), phân công tiêu diệt địch trên quy mô cả nước và giành thắng lợi (1426-1427) với các chiến thắng Tốt Động - Chúc Động và Chi Lăng - Xương Giang.','SGK11:khoi-nghia-lam-son','2026-06-30 00:27:08'),(60686,'hoi-the-dong-quan',11,'KNTT',NULL,'Bai 8',NULL,NULL,'Hội thề Đông Quan diễn ra vào tháng 12 năm 1427, do Lê Lợi và Vương Thông dẫn đầu hai phái đoàn để chấm dứt chiến tranh, quân Minh rút về nước.','SGK11:hoi-the-dong-quan','2026-06-30 00:27:08'),(60687,'nha-le-so-thanh-lap',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1428, nhà Lê sơ được thành lập, Đại Việt trở thành một cường quốc trong khu vực Đông Nam Á.','SGK10:nha-le-so-thanh-lap','2026-06-30 00:27:08'),(60688,'le-nghi-dan-dat-luc-bo',11,'KNTT',NULL,'Bai 13',NULL,NULL,'Năm 1460, Lê Nghi Dân đặt lục bộ, nhưng đến năm 1465, vua Lê Thánh Tông mới đưa lục bộ trở thành cơ quan có quyền lực thực sự.','SGK11:le-nghi-dan-dat-luc-bo','2026-06-30 00:27:08'),(60689,'le-thanh-tong-dua-luc-bo-thanh-co-quan-quyen-luc',11,'KNTT',NULL,'Bai 13',NULL,NULL,'Năm 1465, vua Lê Thánh Tông mới đưa lục bộ trở thành cơ quan có quyền lực thực sự.','SGK11:le-thanh-tong-dua-luc-bo-thanh-co-quan-quyen-luc','2026-06-30 00:27:08'),(60690,'cai-to-hanh-chinh-dia-phuong-12-thua-tuyen',11,'KNTT',NULL,'Bai 13',NULL,NULL,'Ở địa phương, năm 1466, vua Lê Thánh Tông xoá bỏ 5 đạo, chia đất nước thành 12 thừa tuyên và một phủ Trung Đô.','SGK11:cai-to-hanh-chinh-dia-phuong-12-thua-tuyen','2026-06-30 00:27:08'),(60691,'cai-to-he-thong-quan-doi-le-thanh-tong',11,'KNTT',NULL,'Bai 13',NULL,NULL,'Năm 1466, vua Lê Thánh Tông tiến hành cải tổ hệ thống quân đội. Quân đội được chia làm hai loại: quân thường trực bảo vệ kinh thành gọi là cấm binh hay thân binh và quân các đạo, gọi là ngoại binh. Ở mỗi đạo chia binh làm 5 phủ do đô đốc phủ đứng đầu; mỗi phủ gồm 6 vệ; mỗi vệ có 5 hoặc 6 sở. Nhà nước cũng rất chú ý đến rèn luyện quân đội như duyệt tập binh sĩ hằng năm, quy định cứ 3 năm tổ chức một kì thì khảo võ nghệ của quân sĩ và định lệ thưởng phạt,...','SGK11:cai-to-he-thong-quan-doi-le-thanh-tong','2026-06-30 00:27:08'),(60692,'dat-them-thua-tuyen-quang-nam',11,'KNTT',NULL,'Bai 13',NULL,NULL,'Năm 1471, đặt thêm thừa tuyên thứ 13 là Quảng Nam.','SGK11:dat-them-thua-tuyen-quang-nam','2026-06-30 00:27:08'),(60693,'ban-hanh-chinh-sach-loc-dien-quan-dien',11,'KNTT',NULL,'Bai 13',NULL,NULL,'Năm 1477, ban hành chính sách lộc điền và quân điển. Chính sách lộc điền quy định: tổng diện tích cấp cho thân vương là 2 090 mẫu, trong đó 640 mẫu cấp vĩnh viễn. Chính sách quân điền quy định: mọi người từ quan tam phẩm đến cô nhị, quả phụ đều được chia ruộng công; quan tam phẩm được 11 phần, ngũ phẩm được 9,5 phần,... cô nhị, quả phụ được 3 phần; ruộng xã nào chia cho dân xã ấy; xã nào ruộng quá nhiều, người ít thì cho phép lấy bớt ruộng của xã đó chia cho xã bên cạnh ruộng ít, người nhiều; ruộng công làng xã cứ 6 năm chia lại một lần.','SGK11:ban-hanh-chinh-sach-loc-dien-quan-dien','2026-06-30 00:27:08'),(60694,'ban-hanh-quoc-trieu-hinh-luat',11,'KNTT',NULL,'Bai 13',NULL,NULL,'Năm 1483, Nhà nước ban hành bộ Quốc triều hình luật (Luật Hồng Đức) gồm 722 điều, chia làm 6 quyển, gồm những quy định về hình sự, dân sự, đất đai, hôn nhân, gia đình,... Nhiều truyền thống, phong tục tập quán tốt đẹp của dân tộc cũng được tôn trọng và thể chế hoá thành luật. Trong Luật Hồng Đức có 5 điều luật bảo vệ quyền lợi của người phụ nữ mà trong các bộ luật phương Đông đương thời không có. Người goá vợ, goá chồng, mồ côi, tàn tật không nơi nương tựa thì quan sở tại phải thu nuôi,... Những tội phản quốc, tiết lộ bí mật quốc gia, quan ăn hối lộ đều bị trừng phạt rất nặng.','SGK11:ban-hanh-quoc-trieu-hinh-luat','2026-06-30 00:27:08'),(60695,'le-thanh-tong-dung-bia-tien-si-van-mieu',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1484, vua Lê Thánh Tông bắt đầu cho dựng bia đá ở Văn Miếu, khắc tên những người đỗ tiến sĩ.','SGK10:le-thanh-tong-dung-bia-tien-si-van-mieu','2026-06-30 00:27:08'),(60696,'nha-mac-thanh-lap',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1527, nhà Mạc thành lập, khuyến khích phát triển kinh tế công thương nghiệp và văn hoá.','SGK10:nha-mac-thanh-lap','2026-06-30 00:27:08'),(60697,'giao-si-phuong-tay-truyen-dao-cong-giao',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Từ năm 1533, một giáo sĩ người phương Tây đã đến vùng ven biển Nam Định truyền đạo.','SGK10:giao-si-phuong-tay-truyen-dao-cong-giao','2026-06-30 00:27:08'),(60698,'phuc-nghia-hau-gui-thu-nhat-ban',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Bức thư Phúc Nghĩa hầu gửi Quốc vương Nhật Bản đặt quan hệ bang giao năm 1591','SGK10:phuc-nghia-hau-gui-thu-nhat-ban','2026-06-30 00:27:08'),(60699,'giang-van-minh-di-su-nha-minh',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Năm 1637, Giang Văn Minh được vua Lê cử đi sứ sang triều Minh. Trong buổi triều kiến, vua Minh ra vế đối: \"Đồng trụ chỉ kim đài đĩ lục\" (Đồng trụ đến giờ đã mọc rêu xanh) nhắc đến sự tích cột đồng Mã Viện và thất bại của cuộc khởi nghĩa Hai Bà Trưng. Giang Văn Minh đã đối lại: \"Đằng Giang tự cổ huyết do hồng\" (Sông Bạch Đằng từ trước máu còn loang đỏ) gợi lại việc ba lần đánh bại quân xâm lược phương Bắc trên sông Bạch Đằng của dân tộc ta.','SGK11:giang-van-minh-di-su-nha-minh','2026-06-30 00:27:08'),(60700,'phong-trao-tay-son',11,'KNTT',NULL,'Bai 8',NULL,NULL,'Mùa xuân năm 1771, ba anh em Nguyễn Nhạc, Nguyễn Huệ, Nguyễn Lữ dựng cờ khởi nghĩa ở Tây Sơn thượng đạo. Phong trào nhanh chóng phát triển, chiếm được Quy Nhơn (9-1773), kiểm soát vùng đất từ Quảng Nam đến Bình Thuận (giữa 1774), lật đổ chính quyền chúa Nguyễn (1777), Nguyễn Nhạc lên ngôi hoàng đế (1778). Sau đó, đánh tan quân Xiêm (1-1785), giải phóng Đàng Trong (6-1786), lật đổ chính quyền họ Trịnh (7-1786). Tháng 12-1788, Nguyễn Huệ lên ngôi hoàng đế Quang Trung, tiến quân ra Bắc và đại phá quân Thanh (1789).','SGK11:phong-trao-tay-son','2026-06-30 00:27:08'),(60701,'khang-chien-chong-quan-xiem-1784-1785',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Cuộc kháng chiến chống quân Xiêm diễn ra từ 1784 đến 1785, dưới sự chỉ huy của Nguyễn Huệ, với trận quyết chiến tại Rạch Gầm – Xoài Mút (Tiền Giang).','SGK11:khang-chien-chong-quan-xiem-1784-1785','2026-06-30 00:27:08'),(60702,'khang-chien-chong-quan-xiem-1784-1785',11,'KNTT',NULL,'Bai 8',NULL,NULL,'Cuộc kháng chiến chống quân Xiêm diễn ra từ 1784 đến 1785, dưới sự chỉ huy của Nguyễn Huệ, với trận quyết chiến tại Rạch Gầm – Xoài Mút (Tiền Giang).','SGK11:khang-chien-chong-quan-xiem-1784-1785','2026-06-30 00:27:08'),(60703,'khang-chien-chong-quan-thanh-1789',10,'KNTT',NULL,'Bai 3',NULL,NULL,'Cuộc kháng chiến chống quân Thanh diễn ra vào năm 1789, dưới sự chỉ huy của Quang Trung (Nguyễn Huệ), với trận quyết chiến tại Ngọc Hồi - Đống Đa (Hà Nội).','SGK10:khang-chien-chong-quan-thanh-1789','2026-06-30 00:27:08'),(60704,'khang-chien-chong-quan-thanh-1789',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Cuộc kháng chiến chống quân Thanh diễn ra vào năm 1789, dưới sự chỉ huy của Quang Trung (Nguyễn Huệ), với trận quyết chiến tại Ngọc Hồi - Đống Đa (Hà Nội).','SGK11:khang-chien-chong-quan-thanh-1789','2026-06-30 00:27:08'),(60705,'khang-chien-chong-quan-thanh-1789',11,'KNTT',NULL,'Bai 8',NULL,NULL,'Cuộc kháng chiến chống quân Thanh diễn ra vào năm 1789, dưới sự chỉ huy của Quang Trung (Nguyễn Huệ), với trận quyết chiến tại Ngọc Hồi - Đống Đa (Hà Nội).','SGK11:khang-chien-chong-quan-thanh-1789','2026-06-30 00:27:09'),(60706,'bac-thanh-duoc-lap',11,'KNTT',NULL,'Bai 14',NULL,NULL,'Bắc Thành là đơn vị hành chính cao hơn trấn. Bắc Thành được lập từ năm 1802 đến 1831, cai quản 11 trấn là Sơn Nam Thượng, Sơn Nam Hạ, Sơn Tây, Kinh Bắc, Hải Dương, Tuyên Quang, Hưng Hoá, Cao Bằng, Lạng Sơn, Thái Nguyên, Quảng Yên.','SGK11:bac-thanh-duoc-lap','2026-06-30 00:27:09'),(60707,'thoi-gia-long-tri-vi',11,'KNTT',NULL,'Bai 14',NULL,NULL,'Thời Gia Long (1802 - 1820), bộ máy hành chính nhà nước yếu kém về nhiều mặt. Tính chất phân quyền còn đậm nét với sự tồn tại của hai khu vực hành chính là Bắc Thành và Gia Định Thành. Tổ chức hành chính giữa Bắc Thành và Gia Định Thành, giữa đồng bằng và miền núi còn thiếu thống nhất. Quan lại trong bộ máy chủ yếu do các quan võ nắm giữ.','SGK11:thoi-gia-long-tri-vi','2026-06-30 00:27:09'),(60708,'trieu-nguyen-thanh-lap',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1802, triều Nguyễn được thành lập, trị vì đất nước với lãnh thổ rộng lớn nhất, kéo dài từ Bắc vào Nam, lại trải qua một thời gian dài chiến tranh, khủng hoảng về nhiều mặt.','SGK10:trieu-nguyen-thanh-lap','2026-06-30 00:27:09'),(60709,'trieu-nguyen-thanh-lap',11,'KNTT',NULL,'Bai 14',NULL,NULL,'Năm 1802, triều Nguyễn được thành lập, trị vì đất nước với lãnh thổ rộng lớn nhất, kéo dài từ Bắc vào Nam, lại trải qua một thời gian dài chiến tranh, khủng hoảng về nhiều mặt.','SGK11:trieu-nguyen-thanh-lap','2026-06-30 00:27:09'),(60710,'gia-dinh-thanh-duoc-lap',11,'KNTT',NULL,'Bai 14',NULL,NULL,'Gia Định Thành được lập từ năm 1808 đến năm 1832, cai quản 5 trấn là Phiên An, Biên Hoà, Vĩnh Thanh, Định Tường và An Giang.','SGK11:gia-dinh-thanh-duoc-lap','2026-06-30 00:27:09'),(60711,'cuoc-cai-cach-cua-minh-mang',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Trong thời gian trị vì của mình, vua Minh Mạng đã thực hiện nhiều biện pháp cải cách nhằm tăng cường tính thống nhất và tiềm lực của đất nước. Các cải cách tập trung vào bộ máy hành chính (trung ương và địa phương) và thí điểm chia lại ruộng đất.','SGK10:cuoc-cai-cach-cua-minh-mang','2026-06-30 00:27:09'),(60712,'cuoc-cai-cach-cua-minh-mang',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Trong thời gian trị vì của mình, vua Minh Mạng đã thực hiện nhiều biện pháp cải cách nhằm tăng cường tính thống nhất và tiềm lực của đất nước. Các cải cách tập trung vào bộ máy hành chính (trung ương và địa phương) và thí điểm chia lại ruộng đất.','SGK11:cuoc-cai-cach-cua-minh-mang','2026-06-30 00:27:09'),(60713,'cuoc-cai-cach-cua-minh-mang',11,'KNTT',NULL,'Bai 14',NULL,NULL,'Trong thời gian trị vì của mình, vua Minh Mạng đã thực hiện nhiều biện pháp cải cách nhằm tăng cường tính thống nhất và tiềm lực của đất nước. Các cải cách tập trung vào bộ máy hành chính (trung ương và địa phương) và thí điểm chia lại ruộng đất.','SGK11:cuoc-cai-cach-cua-minh-mang','2026-06-30 00:27:09'),(60714,'doi-thi-thu-vien-thanh-van-thu-phong',11,'KNTT',NULL,'Bai 14',NULL,NULL,'Năm 1820, vua Minh Mạng đổi Thị thư viện thành Văn thư phòng như một bước cải tổ các cơ quan trực tiếp giúp việc cho nhà vua.','SGK11:doi-thi-thu-vien-thanh-van-thu-phong','2026-06-30 00:27:09'),(60715,'minh-mang-len-ngoi-vua',11,'KNTT',NULL,'Bai 14',NULL,NULL,'Minh Mạng là con trai thứ tư của vua Gia Long, lên ngôi vua năm 1820, trị vì đến năm 1840. Minh Mạng được đánh giá là một vị vua siêng năng, luôn thức khuya dậy sớm để xem xét công việc và là vị vua có nhiều thành tích nhất của triều Nguyễn.','SGK11:minh-mang-len-ngoi-vua','2026-06-30 00:27:09'),(60716,'doi-dinh-quang-duc-thanh-phu-thua-thien',11,'KNTT',NULL,'Bai 14',NULL,NULL,'Năm 1822, dinh Quảng Đức được đổi thành phủ Thừa Thiên do Đề đốc kinh thành đứng đầu.','SGK11:doi-dinh-quang-duc-thanh-phu-thua-thien','2026-06-30 00:27:09'),(60717,'doi-cac-doanh-quang-binh-quang-tri-quang-nam-thanh-tran',11,'KNTT',NULL,'Bai 14',NULL,NULL,'Năm 1827, vua Minh Mạng đổi các doanh Quảng Bình, Quảng Trị, Quảng Nam thành trấn, thống nhất trên toàn quốc tên gọi các đơn vị hành chính địa phương.','SGK11:doi-cac-doanh-quang-binh-quang-tri-quang-nam-thanh-tran','2026-06-30 00:27:09'),(60718,'lap-noi-cac-thay-the-van-thu-phong',11,'KNTT',NULL,'Bai 14',NULL,NULL,'Năm 1829, vua Minh Mạng lập Nội các thay thế cho Văn thư phòng với chức năng như một cơ quan hành chính trung ương, chuyển và tiếp nhận công văn từ triều đình đến các địa phương và ngược lại, khởi thảo các chế cáo, lưu giữ công văn.','SGK11:lap-noi-cac-thay-the-van-thu-phong','2026-06-30 00:27:09'),(60719,'xoa-bo-bac-thanh-chia-thanh-18-tinh',11,'KNTT',NULL,'Bai 14',NULL,NULL,'Năm 1831, vua Minh Mạng xoá bỏ Bắc Thành, chia vùng lãnh thổ từ phủ Phụng Thiên ra Bắc thành 18 tỉnh.','SGK11:xoa-bo-bac-thanh-chia-thanh-18-tinh','2026-06-30 00:27:09'),(60720,'xoa-bo-gia-dinh-thanh-chia-thanh-12-tinh',11,'KNTT',NULL,'Bai 14',NULL,NULL,'Năm 1832, vua Minh Mạng xoá bỏ Gia Định Thành, chia vùng lãnh thổ từ phủ Phụng Thiên vào Nam thành 12 tỉnh.','SGK11:xoa-bo-gia-dinh-thanh-chia-thanh-12-tinh','2026-06-30 00:27:09'),(60721,'lap-co-mat-vien',11,'KNTT',NULL,'Bai 14',NULL,NULL,'Năm 1834, vua Minh Mạng lập Cơ mật viện làm cơ quan tư vấn tối cao cho nhà vua về những vấn đề trọng đại, đứng đầu là 4 quan văn, võ, hàm từ tam phẩm trở lên do đích thân nhà vua lựa chọn.','SGK11:lap-co-mat-vien','2026-06-30 00:27:09'),(60722,'do-dac-cam-moc-chu-quyen-hoang-sa-pham-huu-nhat',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Năm Bính Thân, niên hiệu Minh Mạng thứ 17 (1836), mùa Xuân tháng Giêng ngày mồng 1, Bộ Công tâu về việc cương giới mặt biển nước ta có xứ Hoàng Sa rất là hiểm yếu. Vua y lời tâu, phái Suất đội thuỷ quân Phạm Hữu Nhật đem binh thuyến đi, chuẩn cho mang theo 10 cái bài gỗ, đến nơi đó dựng dấu ghi... mặt bài khắc những chữ: “Minh Mạng thứ 17, năm Bính Thân, thuỷ quân Chánh đội trưởng suất đội Phạm Hữu Nhật, vâng mệnh đi Hoàng Sa trông nom đo đạc đến đây lưu dấu để ghi nhớ.','SGK11:do-dac-cam-moc-chu-quyen-hoang-sa-pham-huu-nhat','2026-06-30 00:27:09'),(60723,'thi-diem-chia-lai-ruong-dat-minh-mang',11,'KNTT',NULL,'Bai 14',NULL,NULL,'Trước thực trạng ruộng đất công làng xã bị thu hẹp nghiêm trọng, vua Minh Mạng tiến hành cải cách ruộng đất ở Bình Định và Nam Kì. Năm 1837, chia ruộng tư thành bản, chiều cấp cho các xã dân. Năm 1839, yêu cầu chủ sở hữu bỏ ra 50% ruộng đất tư sung công quỹ. Năm 1840, quyết định trích một nửa hoặc 3-4 phần mười ruộng tư sung công. Tuy nhiên, kết quả đạt được rất hạn chế, chỉ có 6-7% số người tự nguyện đem ruộng tư nhượng làm ruộng công.','SGK11:thi-diem-chia-lai-ruong-dat-minh-mang','2026-06-30 00:27:09'),(60724,'thuc-dan-phap-no-sung-tan-cong-da-nang',11,'KNTT',NULL,'Bai 5',NULL,NULL,'Năm 1858, thực dân Pháp nổ súng tấn công Đà Nẵng, mở đầu cuộc xâm lược Việt Nam và làm thất bại kế hoạch “đánh nhanh, thắng nhanh” của chúng.','SGK11:thuc-dan-phap-no-sung-tan-cong-da-nang','2026-06-30 00:27:09'),(60725,'thuc-dan-phap-no-sung-tan-cong-da-nang',11,'KNTT',NULL,'Bai 6',NULL,NULL,'Năm 1858, thực dân Pháp nổ súng tấn công Đà Nẵng, mở đầu cuộc xâm lược Việt Nam và làm thất bại kế hoạch “đánh nhanh, thắng nhanh” của chúng.','SGK11:thuc-dan-phap-no-sung-tan-cong-da-nang','2026-06-30 00:27:09'),(60726,'khang-chien-chong-thuc-dan-phap-trieu-nguyen',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Cuộc kháng chiến chống thực dân Pháp của triều Nguyễn diễn ra từ 1858 đến 1884. Năm 1858, thực dân Pháp tấn công Đà Nẵng, mở đầu cuộc xâm lược nước ta. Sau đó, Pháp chuyển quân vào đánh chiếm Gia Định, rồi chiếm gọn sáu tỉnh Nam Kì vào năm 1867. Năm 1873, chúng đem quân đánh chiếm Bắc Kì lần thứ nhất, triều đình nhà Nguyễn tiếp tục lún sâu vào con đường thoả hiệp. Năm 1882, Pháp lại đưa quân đánh chiếm Bắc Kì lần thứ hai, sau đó quyết định đánh thẳng vào Huế. Triều đình nhà Nguyễn lần lượt kí với Pháp bản Hiệp ước Hác-măng (1883) và Hiệp ước Pa-tơ-nốt (1884), đánh dấu sự đầu hàng hoàn toàn của triều đình phong kiến Việt Nam và sự xác lập nền bảo hộ của Pháp trên toàn bộ đất nước ta.','SGK11:khang-chien-chong-thuc-dan-phap-trieu-nguyen','2026-06-30 00:27:09'),(60727,'phap-tan-cong-da-nang-1858',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Năm 1858, thực dân Pháp tấn công Đà Nẵng, mở đầu cuộc xâm lược nước ta.','SGK11:phap-tan-cong-da-nang-1858','2026-06-30 00:27:09'),(60728,'phap-xam-chiem-dong-duong',11,'KNTT',NULL,'Bai 5',NULL,NULL,'Thực dân Pháp phải trải qua cuộc chiến tranh xâm lược kéo dài gần nửa thế kỉ (1858-1893) mới hoàn thành việc xâm chiếm ba nước Đông Dương.','SGK11:phap-xam-chiem-dong-duong','2026-06-30 00:27:09'),(60729,'phong-trao-chong-thuc-dan-phap-xam-luoc-o-viet-nam',11,'KNTT',NULL,'Bai 6',NULL,NULL,'Từ năm 1858, khi thực dân Pháp nổ súng tấn công Đà Nẵng, cuộc chiến đấu chống xâm lược của nhân dân Việt Nam đã làm thất bại kế hoạch “đánh nhanh, thắng nhanh” của chúng. Cuộc chiến đấu lan rộng ra các tỉnh Nam Kì và Bắc Kì, thu hút sự tham gia của đông đảo các tầng lớp nhân dân. Thực dân Pháp phải mất 26 năm mới áp đặt được ách đô hộ trên toàn bộ đất nước Việt Nam.','SGK11:phong-trao-chong-thuc-dan-phap-xam-luoc-o-viet-nam','2026-06-30 00:27:09'),(60730,'khoi-nghia-cua-pu-com-bo',11,'KNTT',NULL,'Bai 6',NULL,NULL,'Cuộc khởi nghĩa của Pu-côm-bô (1866-1867) có quy mô lớn, gây nhiều tổn thất cho thực dân Pháp. Ông lập căn cứ ở Tây Ninh (Việt Nam) và liên kết với Trương Quyền, trở thành biểu tượng của sự liên minh chiến đấu giữa nhân dân Cam-pu-chia với nhân dân Việt Nam.','SGK11:khoi-nghia-cua-pu-com-bo','2026-06-30 00:27:09'),(60731,'phap-chiem-sau-tinh-nam-ki',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Sau khi tấn công Đà Nẵng, Pháp chuyển quân vào đánh chiếm Gia Định, rồi chiếm gọn sáu tỉnh Nam Kì vào năm 1867.','SGK11:phap-chiem-sau-tinh-nam-ki','2026-06-30 00:27:09'),(60732,'phap-chiem-bac-ki-lan-1',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Năm 1873, thực dân Pháp đem quân đánh chiếm Bắc Kì lần thứ nhất, triều đình nhà Nguyễn tiếp tục lún sâu vào con đường thoả hiệp.','SGK11:phap-chiem-bac-ki-lan-1','2026-06-30 00:27:09'),(60733,'phap-chiem-bac-ki-lan-2',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Năm 1882, Pháp lại đưa quân đánh chiếm Bắc Kì lần thứ hai, sau đó quyết định đánh thẳng vào Huế.','SGK11:phap-chiem-bac-ki-lan-2','2026-06-30 00:27:10'),(60734,'hiep-uoc-hac-mang',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Triều đình nhà Nguyễn kí với Pháp bản Hiệp ước Hác-măng (1883).','SGK11:hiep-uoc-hac-mang','2026-06-30 00:27:10'),(60735,'hiep-uoc-pa-to-not',11,'KNTT',NULL,'Bai 7',NULL,NULL,'Triều đình nhà Nguyễn kí với Pháp bản Hiệp ước Pa-tơ-nốt (1884), đánh dấu sự đầu hàng hoàn toàn của triều đình phong kiến Việt Nam và sự xác lập nền bảo hộ của Pháp trên toàn bộ đất nước ta.','SGK11:hiep-uoc-pa-to-not','2026-06-30 00:27:10'),(60736,'trung-quoc-tu-choi-boi-thuong-vu-tau-dam-hoang-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Năm 1898, khi Công ti Bảo hiểm Anh đòi Trung Quốc phải bồi thường việc người dân Hải Nam \"hôi của\" tàu Bê-lô-na của Đức bị đắm vào năm 1894 ở ngoài khơi bãi đá Bắc và tàu U-nô-phi Ma-ru của Nhật Bản đắm năm 1896 cũng ở quần đảo Hoàng Sa. Trung Quốc đã nêu lí do quần đảo Hoàng Sa không thuộc chủ quyền Trung Quốc để dứt khoát từ chối bồi thường.','SGK11:trung-quoc-tu-choi-boi-thuong-vu-tau-dam-hoang-sa','2026-06-30 00:27:10'),(60737,'xay-dung-cau-long-bien',10,'KNTT',NULL,'Bai 1',NULL,NULL,'Cầu Long Biên bắc qua sông Hồng ở Hà Nội được xây dựng trong thời gian từ năm 1898 đến năm 1902. Trong suốt hơn một thế kỉ qua, cây cầu này đã “chứng kiến” nhiều sự kiện, quá trình lịch sử quan trọng của Thủ đô và đất nước.','SGK10:xay-dung-cau-long-bien','2026-06-30 00:27:10'),(60738,'hoat-dong-doi-ngoai-phan-boi-chau',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Hoạt động đối ngoại của Phan Bội Châu diễn ra chủ yếu ở Nhật Bản, Trung Quốc với mục đích tìm kiếm sự giúp đỡ từ bên ngoài để chống thực dân Pháp, giành độc lập dân tộc.','SGK12:hoat-dong-doi-ngoai-phan-boi-chau','2026-06-30 00:27:10'),(60739,'phan-boi-chau-sang-nhat-ban-1905',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Đầu năm 1905, Phan Bội Châu sang Nhật Bản nhờ giúp đỡ về khí giới, đào tạo nhân lực cho công cuộc cứu nước,... Ông đưa 200 thanh niên Việt Nam sang học tập ở các trường tư thục khác nhau.','SGK12:phan-boi-chau-sang-nhat-ban-1905','2026-06-30 00:27:10'),(60740,'nguyen-tat-thanh-tham-gia-chong-thue-hue',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Sớm có tinh thần yêu nước, năm 1908, Nguyễn Tất Thành tham gia phong trào chống thuế ở Huế.','SGK12:nguyen-tat-thanh-tham-gia-chong-thue-hue','2026-06-30 00:27:10'),(60741,'thanh-lap-lien-minh-dong-a-1908',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1908, Phan Bội Châu tham gia thành lập các tổ chức có mục tiêu đoàn kết quốc tế như: Điền – Quế -Việt liên minh (liên minh giữa Vân Nam, Quảng Tây với Việt Nam) và Đông Á đồng minh (gồm một số người Nhật Bản, Trung Quốc, Triều Tiên, Ấn Độ,...) để hợp sức chống đế quốc.','SGK12:thanh-lap-lien-minh-dong-a-1908','2026-06-30 00:27:10'),(60742,'nguyen-tat-thanh-roi-phan-thiet-vao-sai-gon',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Tháng 2-1911, Nguyễn Tất Thành rời Phan Thiết vào Sài Gòn, mang theo hoài bão ra nước ngoài, xem thế giới làm như thế nào rồi trở về giúp đồng bào.','SGK12:nguyen-tat-thanh-roi-phan-thiet-vao-sai-gon','2026-06-30 00:27:10'),(60743,'nguyen-tat-thanh-ra-di-tim-duong-cuu-nuoc',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Sau một thời gian tìm hiểu, ngày 5-6-1911, Nguyễn Tất Thành (với tên gọi mới là Văn Ba) đã rời Bến Nhà Rồng trên con tàu La-tu-sơ Tơ-rê-vin, bắt đầu hành trình tìm đường cứu nước.','SGK12:nguyen-tat-thanh-ra-di-tim-duong-cuu-nuoc','2026-06-30 00:27:10'),(60744,'hoat-dong-doi-ngoai-nguyen-ai-quoc-1911-1930',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Trong những năm 1911 – 1930, Nguyễn Ái Quốc đã đi qua nhiều quốc gia khác nhau và có những hoạt động đối ngoại nổi bật tại Pháp, Liên Xô và Trung Quốc. Ông gặp gỡ các nhà hoạt động chính trị, tham gia sáng lập Đảng Cộng sản Pháp (1920), thành lập Hội Liên hiệp thuộc địa (1921), tham gia các hội nghị của Quốc tế Cộng sản (1923-1930), liên lạc với lực lượng cách mạng ở Đông Nam Á và Trung Quốc, mở lớp huấn luyện chính trị, và thành lập Hội Liên hiệp các dân tộc bị áp bức ở Á Đông (1925).','SGK12:hoat-dong-doi-ngoai-nguyen-ai-quoc-1911-1930','2026-06-30 00:27:10'),(60745,'hoat-dong-doi-ngoai-phan-chau-trinh',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Hoạt động đối ngoại của Phan Châu Trinh diễn ra chủ yếu ở Pháp với mục đích vận động cải cách cho Việt Nam. Năm 1911, Phan Châu Trinh sang Pháp, tiếp xúc với một số nhóm Việt kiều, tổ chức, đảng phái tiến bộ, nhiều lần gửi kiến nghị đến các thành viên của Chính phủ Pháp..., phê phán chính quyền thực dân, thức tỉnh dư luận Pháp về tình hình Việt Nam. Phan Châu Trinh đóng vai trò quan trọng trong việc thành lập và hoạt động của một số tổ chức yêu nước Việt Nam tại Pháp.','SGK12:hoat-dong-doi-ngoai-phan-chau-trinh','2026-06-30 00:27:10'),(60746,'phan-boi-chau-ve-trung-quoc-1911',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1911, Phan Bội Châu quyết định về hoạt động ở Trung Quốc. Đầu năm 1912, Phan Bội Châu thành lập Việt Nam Quang phục hội và tham gia thành lập Chấn Hoa Hưng Á, nhằm đánh đuổi thực dân Pháp, giành độc lập. Tại đây, Phan Bội Châu cử người liên lạc với một số tổ chức, đại diện nước ngoài như Công sứ Đức, Đại sứ quán Nga,... để tìm kiếm sự giúp đỡ cho phong trào đấu tranh chống Pháp ở Việt Nam.','SGK12:phan-boi-chau-ve-trung-quoc-1911','2026-06-30 00:27:10'),(60747,'phan-chau-trinh-sang-phap-1911',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1911, Phan Châu Trinh sang Pháp, tiếp xúc với một số nhóm Việt kiều, tổ chức, đảng phái tiến bộ, nhiều lần gửi kiến nghị đến các thành viên của Chính phủ Pháp..., phê phán chính quyền thực dân, thức tỉnh dư luận Pháp về tình hình Việt Nam.','SGK12:phan-chau-trinh-sang-phap-1911','2026-06-30 00:27:10'),(60748,'thanh-lap-viet-nam-quang-phuc-hoi-1912',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Đầu năm 1912, Phan Bội Châu thành lập Việt Nam Quang phục hội và tham gia thành lập Chấn Hoa Hưng Á, nhằm đánh đuổi thực dân Pháp, giành độc lập.','SGK12:thanh-lap-viet-nam-quang-phuc-hoi-1912','2026-06-30 00:27:10'),(60749,'nguyen-ai-quoc-gui-yeu-sach-vec-xai',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Năm 1919, Nguyễn Tất Thành thay mặt những người Việt Nam yêu nước tại Pháp gửi tới Hội nghị Véc-xai bản Yêu sách của nhân dân An Nam, trong đó kí tên là Nguyễn Ái Quốc.','SGK12:nguyen-ai-quoc-gui-yeu-sach-vec-xai','2026-06-30 00:27:10'),(60750,'nguyen-ai-quoc-doc-luan-cuong-le-nin',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Tháng 7 – 1920, Nguyễn Ái Quốc đọc Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lê-nin đăng trên báo Nhân đạo. Luận cương đã giúp Nguyễn Ái Quốc khẳng định con đường giành độc lập và tự do cho dân tộc Việt Nam là đi theo con đường cách mạng vô sản, gắn giải phóng dân tộc với giải phóng giai cấp, độc lập dân tộc với chủ nghĩa xã hội.','SGK12:nguyen-ai-quoc-doc-luan-cuong-le-nin','2026-06-30 00:27:10'),(60751,'nguyen-ai-quoc-doc-luan-cuong-le-nin',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Tháng 7 – 1920, Nguyễn Ái Quốc đọc Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của V. Lê-nin.','SGK12:nguyen-ai-quoc-doc-luan-cuong-le-nin','2026-06-30 00:27:10'),(60752,'nguyen-ai-quoc-gia-nhap-quoc-te-cong-san-va-sang-lap-dang-cong-san-phap',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Tại Đại hội lần thứ XVIII của Đảng Xã hội Pháp (12 – 1920), Nguyễn Ái Quốc đã bỏ phiếu tán thành việc gia nhập Quốc tế Cộng sản, trở thành người cộng sản Việt Nam đầu tiên và một trong những người sáng lập Đảng Cộng sản Pháp.','SGK12:nguyen-ai-quoc-gia-nhap-quoc-te-cong-san-va-sang-lap-dang-cong-san-phap','2026-06-30 00:27:10'),(60753,'nguyen-ai-quoc-gia-nhap-quoc-te-cong-san-va-sang-lap-dang-cong-san-phap',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Tại Đại hội lần thứ XVIII của Đảng Xã hội Pháp (12 – 1920), Nguyễn Ái Quốc đã bỏ phiếu tán thành việc gia nhập Quốc tế Cộng sản, trở thành người cộng sản Việt Nam đầu tiên và một trong những người sáng lập Đảng Cộng sản Pháp.','SGK12:nguyen-ai-quoc-gia-nhap-quoc-te-cong-san-va-sang-lap-dang-cong-san-phap','2026-06-30 00:27:10'),(60754,'nguyen-ai-quoc-gia-nhap-quoc-te-cong-san-va-sang-lap-dang-cong-san-phap',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1920, Nguyễn Ái Quốc tham gia sáng lập Đảng Cộng sản Pháp.','SGK12:nguyen-ai-quoc-gia-nhap-quoc-te-cong-san-va-sang-lap-dang-cong-san-phap','2026-06-30 00:27:10'),(60755,'giai-doan-xuat-hien-xu-huong-moi-trong-phong-trao-dau-tranh-o-dong-nam-a',11,'KNTT',NULL,'Bai 6',NULL,NULL,'Giai đoạn 1920-1945 đánh dấu sự xuất hiện khuynh hướng mới trong phong trào đấu tranh ở Đông Nam Á. Giai cấp vô sản bắt đầu bước lên vũ đài chính trị, với việc các đảng cộng sản được thành lập ở một số nước như In-đô-nê-xi-a (1920), Việt Nam, Mã Lai, Xiêm và Phi-líp-pin (trong những năm 30 của thế kỉ XX), mở ra khuynh hướng vô sản trong cuộc đấu tranh giành độc lập dân tộc.','SGK11:giai-doan-xuat-hien-xu-huong-moi-trong-phong-trao-dau-tranh-o-dong-nam-a','2026-06-30 00:27:10'),(60756,'nguyen-ai-quoc-hoat-dong-phap-1921-1923',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Từ năm 1921 đến tháng 6 – 1923, Nguyễn Ái Quốc hoạt động ở Pháp: tham gia thành lập Hội Liên hiệp các dân tộc thuộc địa, làm Chủ nhiệm kiêm chủ bút Báo Người cùng khổ,...','SGK12:nguyen-ai-quoc-hoat-dong-phap-1921-1923','2026-06-30 00:27:10'),(60757,'nguyen-ai-quoc-thanh-lap-hoi-lien-hiep-thuoc-dia-1921',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Năm 1921, Nguyễn Ái Quốc tham gia thành lập Hội Liên hiệp thuộc địa – một hình thức liên minh của các dân tộc bị áp bức.','SGK12:nguyen-ai-quoc-thanh-lap-hoi-lien-hiep-thuoc-dia-1921','2026-06-30 00:27:10'),(60758,'nguyen-ai-quoc-thanh-lap-hoi-lien-hiep-thuoc-dia-va-bao-le-paria',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Từ giữa năm 1921, tại Pháp, cùng một số nhà cách mạng của các nước thuộc địa khác, Nguyễn Ái Quốc tham gia thành lập Hội liên hiệp thuộc địa, sau đó sáng lập tờ báo Le Paria (Người cùng khổ). Người viết nhiều bài trên các báo: Nhân đạo, Đời sống công nhân, Tạp chí Cộng sản, Tập san Thư tín quốc tế....','SGK12:nguyen-ai-quoc-thanh-lap-hoi-lien-hiep-thuoc-dia-va-bao-le-paria','2026-06-30 00:27:10'),(60759,'nguyen-ai-quoc-den-lien-xo-1923',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Tháng 6- 1923, Nguyễn Ái Quốc từ Pháp đến Liên Xô, tích cực tham gia các hội nghị, đại hội của Quốc tế Cộng sản. Tại những diễn đàn này, Nguyễn Ái Quốc trình bày quan điểm về vai trò của cách mạng thuộc địa, về lực lượng cách mạng ở thuộc địa, về quan hệ giữa cách mạng ở chính quốc với thuộc địa,...','SGK12:nguyen-ai-quoc-den-lien-xo-1923','2026-06-30 00:27:10'),(60760,'nguyen-ai-quoc-den-lien-xo-1923',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Tháng 6 – 1923, Nguyễn Ái Quốc rời Pháp đến Liên Xô, tích cực hoạt động trong phong trào cộng sản quốc tế,...','SGK12:nguyen-ai-quoc-den-lien-xo-1923','2026-06-30 00:27:10'),(60761,'nguyen-ai-quoc-den-quang-chau-1924',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Từ cuối năm 1924, Nguyễn Ái Quốc đến Quảng Châu (Trung Quốc), liên lạc với lực lượng cách mạng ở Đông Nam Á và Trung Quốc, mở các lớp huấn luyện chính trị cho thanh niên yêu nước Việt Nam. Trong các bài giảng, Nguyễn Ái Quốc nhấn mạnh sự cần thiết phải đoàn kết và tập hợp lực lượng quốc tế.','SGK12:nguyen-ai-quoc-den-quang-chau-1924','2026-06-30 00:27:10'),(60762,'nguyen-ai-quoc-thanh-lap-hoi-viet-nam-cach-mang-thanh-nien',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Tháng 6 – 1925, Nguyễn Ái Quốc thành lập Hội Việt Nam Cách mạng Thanh niên tại Quảng Châu (Trung Quốc) nhằm đào tạo những người yêu nước thành cán bộ truyền bá chủ nghĩa Mác – Lê-nin, lí luận cách mạng giải phóng dân tộc của Nguyễn Ái Quốc vào phong trào yêu nước, phong trào công nhân. Sau khi thành lập, Hội tổ chức các lớp huấn luyện chính trị do Nguyễn Ái Quốc trực tiếp phụ trách.','SGK12:nguyen-ai-quoc-thanh-lap-hoi-viet-nam-cach-mang-thanh-nien','2026-06-30 00:27:11'),(60763,'nguyen-ai-quoc-thanh-lap-hoi-viet-nam-cach-mang-thanh-nien',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Tháng 6 – 1925, Nguyễn Ái Quốc thành lập Hội Việt Nam Cách mạng Thanh niên tại Quảng Châu (Trung Quốc) nhằm đào tạo những người yêu nước thành cán bộ truyền bá chủ nghĩa Mác – Lê-nin, lí luận cách mạng giải phóng dân tộc của Nguyễn Ái Quốc vào phong trào yêu nước, phong trào công nhân. Sau khi thành lập, Hội tổ chức các lớp huấn luyện chính trị do Nguyễn Ái Quốc trực tiếp phụ trách.','SGK12:nguyen-ai-quoc-thanh-lap-hoi-viet-nam-cach-mang-thanh-nien','2026-06-30 00:27:11'),(60764,'thanh-lap-hoi-lien-hiep-cac-dan-toc-bi-ap-buc-a-dong-1925',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Tháng 7 – 1925, Nguyễn Ái Quốc tham gia thành lập Hội Liên hiệp các dân tộc bị áp bức ở Á Đông, một đoàn thể có tính chất quốc tế bao gồm người Việt Nam, Trung Quốc, Ấn Độ, Triều Tiên, In-đô-nê-xi-a, Miến Điện. Tuyên ngôn của Hội khẳng định con đường duy nhất để xoá bỏ sự áp bức chỉ có thể là liên hiệp các dân tộc nhỏ yếu bị áp bức và giai cấp vô sản toàn thế giới, áp dụng những phương pháp cách mạng để lật đổ đế quốc thực dân.','SGK12:thanh-lap-hoi-lien-hiep-cac-dan-toc-bi-ap-buc-a-dong-1925','2026-06-30 00:27:11'),(60765,'ho-chi-minh-mo-lop-dao-tao-can-bo-tai-quang-chau-trung-quoc',12,'KNTT',NULL,'Bai 17',NULL,NULL,'Nhà số 248 và 250 (trước là nhà số 13 và 13/1) đường Văn Minh, thành phố Quảng Châu (Trung Quốc) là nơi Hồ Chí Minh mở các lớp đào tạo cán bộ (1925 – 1927).','SGK12:ho-chi-minh-mo-lop-dao-tao-can-bo-tai-quang-chau-trung-quoc','2026-06-30 00:27:11'),(60766,'nguyen-ai-quoc-hoat-dong-chau-au-siam-1927-1929',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Từ giữa năm 1927 đến cuối năm 1929, Nguyễn Ái Quốc hoạt động cách mạng ở Pháp, Bỉ, Đức, Xiêm,...','SGK12:nguyen-ai-quoc-hoat-dong-chau-au-siam-1927-1929','2026-06-30 00:27:11'),(60767,'su-ra-doi-cua-ba-to-chuc-cong-san-viet-nam',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Hoạt động của Hội Việt Nam Cách mạng Thanh niên có ảnh hưởng và thúc đẩy mạnh mẽ sự chuyển biến của phong trào công nhân, phong trào yêu nước Việt Nam, dẫn đến sự ra đời của ba tổ chức cộng sản trong năm 1929. Đó là sự chuẩn bị trực tiếp cho sự ra đời của Đảng Cộng sản Việt Nam.','SGK12:su-ra-doi-cua-ba-to-chuc-cong-san-viet-nam','2026-06-30 00:27:11'),(60768,'hoi-nghi-thanh-lap-dang-cong-san-viet-nam',10,'KNTT',NULL,'Bai 14',NULL,NULL,'Trước nhu cầu cấp bách của phong trào cách mạng, với tư cách là phái viên của Quốc tế Cộng sản, Nguyễn Ái Quốc đã chủ động triệu tập đại biểu các tổ chức cộng sản đến Cửu Long (Hồng Công – Trung Quốc) để tiến hành hợp nhất. Hội nghị bắt đầu diễn ra từ ngày 6 – 1 – 1930. Trong hội nghị này, Nguyễn Ái Quốc nêu ra những điểm lớn cần thảo luận và thống nhất gồm: bỏ mọi xung đột cũ, thống nhất các nhóm cộng sản ở Đông Dương; định tên Đảng là Đảng Cộng sản Việt Nam; thảo luận Chính cương và Điều lệ sơ lược của Đảng; định kế hoạch việc thống nhất trong nước và cử một Ban Chấp hành Trung ương lâm thời. Hội nghị tán thành ý kiến của Nguyễn Ái Quốc, thông qua các văn kiện do Nguyễn Ái Quốc soạn thảo. Trong đó, Chính cương vắn tắt và Sách lược vắn tắt của Đảng đã phản ánh những vấn đề chiến lược và sách lược của Đảng. Hai văn kiện trên được xem là Cương lĩnh chính trị đầu tiên của Đảng Cộng sản Việt Nam.','SGK10:hoi-nghi-thanh-lap-dang-cong-san-viet-nam','2026-06-30 00:27:11'),(60769,'hoi-nghi-thanh-lap-dang-cong-san-viet-nam',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Trước nhu cầu cấp bách của phong trào cách mạng, với tư cách là phái viên của Quốc tế Cộng sản, Nguyễn Ái Quốc đã chủ động triệu tập đại biểu các tổ chức cộng sản đến Cửu Long (Hồng Công – Trung Quốc) để tiến hành hợp nhất. Hội nghị bắt đầu diễn ra từ ngày 6 – 1 – 1930. Trong hội nghị này, Nguyễn Ái Quốc nêu ra những điểm lớn cần thảo luận và thống nhất gồm: bỏ mọi xung đột cũ, thống nhất các nhóm cộng sản ở Đông Dương; định tên Đảng là Đảng Cộng sản Việt Nam; thảo luận Chính cương và Điều lệ sơ lược của Đảng; định kế hoạch việc thống nhất trong nước và cử một Ban Chấp hành Trung ương lâm thời. Hội nghị tán thành ý kiến của Nguyễn Ái Quốc, thông qua các văn kiện do Nguyễn Ái Quốc soạn thảo. Trong đó, Chính cương vắn tắt và Sách lược vắn tắt của Đảng đã phản ánh những vấn đề chiến lược và sách lược của Đảng. Hai văn kiện trên được xem là Cương lĩnh chính trị đầu tiên của Đảng Cộng sản Việt Nam.','SGK12:hoi-nghi-thanh-lap-dang-cong-san-viet-nam','2026-06-30 00:27:11'),(60770,'hoi-nghi-thanh-lap-dang-cong-san-viet-nam',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Trước nhu cầu cấp bách của phong trào cách mạng, với tư cách là phái viên của Quốc tế Cộng sản, Nguyễn Ái Quốc đã chủ động triệu tập đại biểu các tổ chức cộng sản đến Cửu Long (Hồng Công – Trung Quốc) để tiến hành hợp nhất. Hội nghị bắt đầu diễn ra từ ngày 6 – 1 – 1930. Trong hội nghị này, Nguyễn Ái Quốc nêu ra những điểm lớn cần thảo luận và thống nhất gồm: bỏ mọi xung đột cũ, thống nhất các nhóm cộng sản ở Đông Dương; định tên Đảng là Đảng Cộng sản Việt Nam; thảo luận Chính cương và Điều lệ sơ lược của Đảng; định kế hoạch việc thống nhất trong nước và cử một Ban Chấp hành Trung ương lâm thời. Hội nghị tán thành ý kiến của Nguyễn Ái Quốc, thông qua các văn kiện do Nguyễn Ái Quốc soạn thảo. Trong đó, Chính cương vắn tắt và Sách lược vắn tắt của Đảng đã phản ánh những vấn đề chiến lược và sách lược của Đảng. Hai văn kiện trên được xem là Cương lĩnh chính trị đầu tiên của Đảng Cộng sản Việt Nam.','SGK12:hoi-nghi-thanh-lap-dang-cong-san-viet-nam','2026-06-30 00:27:11'),(60771,'thanh-lap-mat-tran-dan-toc-thong-nhat-viet-nam-1930',10,'KNTT',NULL,'Bai 14',NULL,NULL,'Khối đại đoàn kết các dân tộc Việt Nam được thể hiện tập trung trong Mặt trận dân tộc thống nhất Việt Nam, được thành lập ngày 18 – 11 – 1930 với tên gọi Hội Phản đế Đồng minh, nay là Mặt trận Tổ quốc Việt Nam.','SGK10:thanh-lap-mat-tran-dan-toc-thong-nhat-viet-nam-1930','2026-06-30 00:27:11'),(60772,'hoat-dong-doi-ngoai-dang-cong-san-dong-duong-1930-1945',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Trong những năm 1930 – 1945, hoạt động đối ngoại của Đảng Cộng sản Đông Dương chủ yếu phục vụ cho cuộc đấu tranh chống thực dân, phát xít, tiến tới giành độc lập, tự do, góp phần bảo vệ hoà bình. Đảng ủng hộ Liên Xô, phối hợp với các tổ chức người Pháp, người Hoa giúp đỡ nạn nhân chiến tranh ở Trung Quốc, củng cố quan hệ với Đảng Cộng sản Trung Quốc, liên lạc với phong trào dân tộc chống quân phiệt Nhật Bản ở Đông Nam Á. Thông qua Mặt trận Việt Minh, Đảng đứng về phía lực lượng Đồng minh, tiếp xúc với Trung Hoa Dân quốc và hợp tác với Cơ quan Tình báo chiến lược Mỹ (OSS).','SGK12:hoat-dong-doi-ngoai-dang-cong-san-dong-duong-1930-1945','2026-06-30 00:27:11'),(60773,'nguyen-ai-quoc-hoat-dong-lien-xo-1933',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Năm 1933, Nguyễn Ái Quốc hoạt động tại Liên Xô.','SGK12:nguyen-ai-quoc-hoat-dong-lien-xo-1933','2026-06-30 00:27:11'),(60774,'phap-xay-dung-cot-hai-dang-hoang-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Từ những năm 30 của thế kỉ XX, người Pháp đã tiến hành xây dựng cột mốc chủ quyền, đèn biển, trạm khí tượng, trạm vô tuyến điện và thực hiện nhiều khảo sát khoa học,... Cột hải đăng trên quần đảo Hoàng Sa được xây dựng năm 1937.','SGK11:phap-xay-dung-cot-hai-dang-hoang-sa','2026-06-30 00:27:11'),(60775,'nguyen-ai-quoc-roi-lien-xo-tro-lai-trung-quoc',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Năm 1938, Nguyễn Ái Quốc rời Liên Xô trở lại Trung Quốc và hoạt động cách mạng ở đây.','SGK12:nguyen-ai-quoc-roi-lien-xo-tro-lai-trung-quoc','2026-06-30 00:27:11'),(60776,'phap-xay-dung-bia-chu-quyen-hoang-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Từ những năm 30 của thế kỉ XX, người Pháp đã tiến hành xây dựng cột mốc chủ quyền, đèn biển, trạm khí tượng, trạm vô tuyến điện và thực hiện nhiều khảo sát khoa học,... Bia chủ quyền trên quần đảo Hoàng Sa do người Pháp xây dựng vào năm 1938.','SGK11:phap-xay-dung-bia-chu-quyen-hoang-sa','2026-06-30 00:27:11'),(60777,'phap-gui-cong-ham-phan-doi-nhat-ban-kiem-soat-truong-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Năm 1939, chính quyền thực dân Pháp gửi công hàm phản đối việc Nhật Bản kiểm soát một số đảo thuộc quần đảo Trường Sa.','SGK11:phap-gui-cong-ham-phan-doi-nhat-ban-kiem-soat-truong-sa','2026-06-30 00:27:11'),(60778,'nguyen-ai-quoc-tro-ve-nuoc',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Ngày 28-1-1941, sau hơn 30 năm xa Tổ quốc, Nguyễn Ái Quốc trở về nước, trực tiếp lãnh đạo cách mạng Việt Nam.','SGK12:nguyen-ai-quoc-tro-ve-nuoc','2026-06-30 00:27:11'),(60779,'nguyen-ai-quoc-tro-ve-nuoc',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Ngày 28-1-1941, sau hơn 30 năm xa Tổ quốc, Nguyễn Ái Quốc trở về nước, trực tiếp lãnh đạo cách mạng Việt Nam.','SGK12:nguyen-ai-quoc-tro-ve-nuoc','2026-06-30 00:27:11'),(60780,'hoi-nghi-lan-thu-8-ban-chap-hanh-trung-uong-dang-cong-san-dong-duong',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Sau một thời gian chuẩn bị, Nguyễn Ái Quốc triệu tập Hội nghị lần thứ 8 Ban Chấp hành Trung ương Đảng Cộng sản Đông Dương tại Pác Bó (Hà Quảng, Cao Bằng) từ ngày 10 đến ngày 19-5-1941. Dưới sự chủ trì của Nguyễn Ái Quốc, Hội nghị xác định cách mạng Việt Nam hiện tại là cuộc cách mạng giải phóng dân tộc. Hội nghị chủ trương thành lập Mặt trận Việt Nam Độc lập Đồng minh (gọi tắt là Mặt trận Việt Minh) và giúp đỡ nhân dân Lào, Cam-pu-chia thành lập mặt trận riêng. Về vấn đề chính quyền, Hội nghị chủ trương thành lập Chính phủ Dân chủ Cộng hoà. Hội nghị nhấn mạnh chuẩn bị khởi nghĩa là nhiệm vụ trung tâm của toàn Đảng, toàn dân và xác định tiến trình cách mạng Việt Nam là đi từ khởi nghĩa từng phần tiến lên tổng khởi nghĩa.','SGK12:hoi-nghi-lan-thu-8-ban-chap-hanh-trung-uong-dang-cong-san-dong-duong','2026-06-30 00:27:11'),(60781,'hoi-nghi-lan-thu-8-ban-chap-hanh-trung-uong-dang-cong-san-dong-duong',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Sau một thời gian chuẩn bị, Nguyễn Ái Quốc triệu tập Hội nghị lần thứ 8 Ban Chấp hành Trung ương Đảng Cộng sản Đông Dương tại Pác Bó (Hà Quảng, Cao Bằng) từ ngày 10 đến ngày 19-5-1941. Dưới sự chủ trì của Nguyễn Ái Quốc, Hội nghị xác định cách mạng Việt Nam hiện tại là cuộc cách mạng giải phóng dân tộc. Hội nghị chủ trương thành lập Mặt trận Việt Nam Độc lập Đồng minh (gọi tắt là Mặt trận Việt Minh) và giúp đỡ nhân dân Lào, Cam-pu-chia thành lập mặt trận riêng. Về vấn đề chính quyền, Hội nghị chủ trương thành lập Chính phủ Dân chủ Cộng hoà. Hội nghị nhấn mạnh chuẩn bị khởi nghĩa là nhiệm vụ trung tâm của toàn Đảng, toàn dân và xác định tiến trình cách mạng Việt Nam là đi từ khởi nghĩa từng phần tiến lên tổng khởi nghĩa.','SGK12:hoi-nghi-lan-thu-8-ban-chap-hanh-trung-uong-dang-cong-san-dong-duong','2026-06-30 00:27:11'),(60782,'thanh-lap-mat-tran-viet-nam-doc-lap-dong-minh-viet-minh',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Hội nghị chủ trương thành lập Mặt trận Việt Nam Độc lập Đồng minh (gọi tắt là Mặt trận Việt Minh). Tôn chỉ mục đích thành lập của Mặt trận Việt Minh là: “liên hiệp hết thảy các giới đồng bào yêu nước, không phân biệt giàu nghèo, già trẻ, trai gái, không phân biệt tôn giáo, xu hướng chính trị, đặng cùng nhau mưu cuộc dân tộc giải phóng và sinh tồn”. Từ khi Mặt trận Việt Minh ra đời, “toàn bộ phong trào chống phát xít Pháp – Nhật của nhân dân ta mang tên là phong trào Việt Minh, cái tên tiêu biểu cho lòng yêu nước, ý chí quật cường của dân tộc ta.','SGK12:thanh-lap-mat-tran-viet-nam-doc-lap-dong-minh-viet-minh','2026-06-30 00:27:11'),(60783,'thanh-lap-mat-tran-viet-nam-doc-lap-dong-minh-viet-minh',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Hội nghị chủ trương thành lập Mặt trận Việt Nam Độc lập Đồng minh (gọi tắt là Mặt trận Việt Minh). Tôn chỉ mục đích thành lập của Mặt trận Việt Minh là: “liên hiệp hết thảy các giới đồng bào yêu nước, không phân biệt giàu nghèo, già trẻ, trai gái, không phân biệt tôn giáo, xu hướng chính trị, đặng cùng nhau mưu cuộc dân tộc giải phóng và sinh tồn”. Từ khi Mặt trận Việt Minh ra đời, “toàn bộ phong trào chống phát xít Pháp – Nhật của nhân dân ta mang tên là phong trào Việt Minh, cái tên tiêu biểu cho lòng yêu nước, ý chí quật cường của dân tộc ta.','SGK12:thanh-lap-mat-tran-viet-nam-doc-lap-dong-minh-viet-minh','2026-06-30 00:27:11'),(60784,'thanh-lap-tieu-doi-du-kich-thoat-li-dau-tien-o-cao-bang',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Thành lập Tiểu đội du kích thoát li đầu tiên ở Cao Bằng (11 – 1941), biên soạn các tài liệu huấn luyện quân sự.','SGK12:thanh-lap-tieu-doi-du-kich-thoat-li-dau-tien-o-cao-bang','2026-06-30 00:27:11'),(60785,'ho-chi-minh-di-trung-quoc-phoi-hop-chong-nhat',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Tháng 8 – 1942, lấy tên Hồ Chí Minh, lên đường đi Trung Quốc để tìm cách phối hợp hành động với phong trào chống Nhật của nhân dân Trung Quốc và các lực lượng Đồng minh chống phát xít trên chiến trường châu Á – Thái Bình Dương.','SGK12:ho-chi-minh-di-trung-quoc-phoi-hop-chong-nhat','2026-06-30 00:27:11'),(60786,'ho-chi-minh-sang-trung-quoc-1942',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Tháng 8 – 1942, Nguyễn Ái Quốc lấy tên là Hồ Chí Minh, sang Trung Quốc tìm sự liên minh quốc tế.','SGK12:ho-chi-minh-sang-trung-quoc-1942','2026-06-30 00:27:11'),(60787,'ho-chi-minh-tro-ve-nuoc-1944',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Tháng 9 – 1944, Hồ Chí Minh trở về nước tiếp tục lãnh đạo cách mạng.','SGK12:ho-chi-minh-tro-ve-nuoc-1944','2026-06-30 00:27:11'),(60788,'chi-thi-thanh-lap-doi-viet-nam-tuyen-truyen-giai-phong-quan',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân (22 – 12 – 1944).','SGK12:chi-thi-thanh-lap-doi-viet-nam-tuyen-truyen-giai-phong-quan','2026-06-30 00:27:11'),(60789,'ho-chi-minh-sang-con-minh-tim-su-ung-ho-quoc-te',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Tháng 2-1945, sang Côn Minh (Trung Quốc) nhằm tìm kiếm sự ủng hộ của quốc tế.','SGK12:ho-chi-minh-sang-con-minh-tim-su-ung-ho-quoc-te','2026-06-30 00:27:11'),(60790,'cao-trao-khang-nhat-cuu-nuoc',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Trước đó, từ tháng 3 đến tháng 8 – 1945, cao trào kháng Nhật, cứu nước đã diễn ra trong cả nước, góp phần chuẩn bị lực lượng, tập dượt cho quần chúng đấu tranh, sẵn sàng tổng khởi nghĩa giành chính quyền khi thời cơ đến.','SGK12:cao-trao-khang-nhat-cuu-nuoc','2026-06-30 00:27:11'),(60791,'viet-minh-hop-tac-oss-1945',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Đối với phái bộ Mỹ ở phía nam Trung Quốc, đại diện của Mặt trận Việt Minh chủ động bắt liên lạc để thiết lập quan hệ và hợp tác chống quân phiệt Nhật Bản. Cuối tháng 4 – 1945, sự hợp tác giữa Việt Minh và Cơ quan Tình báo chiến lược Mỹ (OSS) tại châu Á được xác lập.','SGK12:viet-minh-hop-tac-oss-1945','2026-06-30 00:27:12'),(60792,'hoi-nghi-pot-xdam',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Từ ngày 17-7 – 1945 đến ngày 2 – 8 – 1945, Hội nghị Pốt-xđam quyết định giao việc giải giáp vũ khí của quân phiệt Nhật Bản ở Đông Dương cho quân Trung Hoa Dân quốc ở khu vực phía Bắc vĩ tuyến 16, cho quân Anh ở khu vực phía Nam vĩ tuyến 16.','SGK12:hoi-nghi-pot-xdam','2026-06-30 00:27:12'),(60793,'uy-ban-khoi-nghia-ban-bo-quan-lenh-so-1',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Ngày 13-8-1945, Trung ương Đảng và Tổng bộ Việt Minh thành lập Uỷ ban Khởi nghĩa toàn quốc, ban bố Quân lệnh số 1, chính thức phát động Tổng khởi nghĩa trong cả nước.','SGK12:uy-ban-khoi-nghia-ban-bo-quan-lenh-so-1','2026-06-30 00:27:12'),(60794,'cach-mang-thang-tam-nam-1945',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Cách mạng tháng Tám năm 1945 là sự kiện lịch sử vĩ đại, đã lật đổ ách cai trị của thực dân Pháp trong hơn 80 năm, của quân phiệt Nhật Bản gần 5 năm; chấm dứt thời kì quân chủ hơn 1000 năm; lập nên nước Việt Nam Dân chủ Cộng hòa.','SGK12:cach-mang-thang-tam-nam-1945','2026-06-30 00:27:12'),(60795,'hoi-nghi-toan-quoc-cua-dang-cong-san-dong-duong-1945',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Cùng Ban Thường vụ Ban Chấp hành Trung ương Đảng triệu tập Hội nghị toàn quốc của Đảng Cộng sản Đông Dương (từ ngày 14 đến ngày 15-8-1945) thông qua kế hoạch lãnh đạo toàn dân tổng khởi nghĩa.','SGK12:hoi-nghi-toan-quoc-cua-dang-cong-san-dong-duong-1945','2026-06-30 00:27:12'),(60796,'hoi-nghi-toan-quoc-cua-dang-tan-trao',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Ngày 14, 15-8 – 1945, Hội nghị toàn quốc của Đảng họp ở Tân Trào (Sơn Dương, Tuyên Quang), thông qua kế hoạch lãnh đạo toàn dân Tổng khởi nghĩa và quyết định những vấn để quan trọng về chính sách đối nội, đối ngoại sau khi giành được chính quyền.','SGK12:hoi-nghi-toan-quoc-cua-dang-tan-trao','2026-06-30 00:27:12'),(60797,'nhat-ban-tuyen-bo-dau-hang-dong-minh',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Đến ngày 15 – 8 – 1945, Nhật Bản tuyên bố đầu hàng Đồng minh không điều kiện.','SGK12:nhat-ban-tuyen-bo-dau-hang-dong-minh','2026-06-30 00:27:12'),(60798,'dai-hoi-quoc-dan-tan-trao',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Ngày 16, 17-8 – 1945, Đại hội Quốc dân được triệu tập tại Tân Trào. Đại hội tán thành chủ trương Tổng khởi nghĩa của Đảng, thông qua 10 chính sách của Việt Minh, cử ra Uỷ ban Dân tộc giải phóng Việt Nam do Hồ Chí Minh làm Chủ tịch.','SGK12:dai-hoi-quoc-dan-tan-trao','2026-06-30 00:27:12'),(60799,'dai-hoi-quoc-dan-tan-trao',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Ngày 16, 17-8 – 1945, Đại hội Quốc dân được triệu tập tại Tân Trào. Đại hội tán thành chủ trương Tổng khởi nghĩa của Đảng, thông qua 10 chính sách của Việt Minh, cử ra Uỷ ban Dân tộc giải phóng Việt Nam do Hồ Chí Minh làm Chủ tịch.','SGK12:dai-hoi-quoc-dan-tan-trao','2026-06-30 00:27:12'),(60800,'giai-phong-thi-xa-thai-nguyen',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Chiều ngày 16 – 8 – 1945, một đơn vị Giải phóng quân do Võ Nguyên Giáp chỉ huy, xuất phát từ Tân Trào tiến về giải phóng thị xã Thái Nguyên, mở đường tiến về Hà Nội.','SGK12:giai-phong-thi-xa-thai-nguyen','2026-06-30 00:27:12'),(60801,'cac-tinh-gianh-chinh-quyen-som-nhat',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Ngày 18-8-1945, nhân dân Bắc Giang, Hải Dương, Hà Tĩnh và Quảng Nam giành được chính quyền ở tỉnh lị sớm nhất trong cả nước.','SGK12:cac-tinh-gianh-chinh-quyen-som-nhat','2026-06-30 00:27:12'),(60802,'khoi-nghia-gianh-chinh-quyen-ha-noi',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Tại Hà Nội, ngày 19-8-1945, quần chúng cách mạng có sự hỗ trợ của các đội tự vệ chiến đấu lần lượt chiếm Phủ Khâm sai, Sở Cảnh sát Trung ương, Sở Bưu điện,... Đến tối, cuộc khởi nghĩa giành chính quyển thắng lợi.','SGK12:khoi-nghia-gianh-chinh-quyen-ha-noi','2026-06-30 00:27:12'),(60803,'khoi-nghia-gianh-chinh-quyen-hue',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Tại Huế, ngày 23 – 8, hàng vạn nhân dân biểu tình thị uy, chiếm các công sở giành chính quyền về tay nhân dân.','SGK12:khoi-nghia-gianh-chinh-quyen-hue','2026-06-30 00:27:12'),(60804,'khoi-nghia-gianh-chinh-quyen-sai-gon',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Ngày 25 – 8, sau khi chiếm được các cơ quan đầu não của chính quyền cũ như: Sở Mật thám, Sở Cảnh sát,... nhân dân Sài Gòn và các vùng phụ cận đã tham gia cuộc mít tinh lớn do Mặt trận Việt Minh tổ chức, chính quyền cách mạng ra mắt nhân dân. Khởi nghĩa ở Sài Gòn giành thắng lợi.','SGK12:khoi-nghia-gianh-chinh-quyen-sai-gon','2026-06-30 00:27:12'),(60805,'cac-dia-phuong-cuoi-cung-gianh-chinh-quyen',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Đến ngày 28 - 8, Đồng Nai Thượng và Hà Tiên là những địa phương cuối cùng giành chính quyền.','SGK12:cac-dia-phuong-cuoi-cung-gianh-chinh-quyen','2026-06-30 00:27:12'),(60806,'tong-khoi-nghia-gianh-chinh-quyen',10,'KNTT',NULL,'Bai 14',NULL,NULL,'Tháng 8 – 1945, Hồ Chí Minh cùng Trung ương Đảng, Mặt trận Việt Minh lãnh đạo nhân dân Tổng khởi nghĩa giành chính quyền thắng lợi, và được cử làm Chủ tịch của Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hoà.','SGK10:tong-khoi-nghia-gianh-chinh-quyen','2026-06-30 00:27:12'),(60807,'tong-khoi-nghia-gianh-chinh-quyen',11,'KNTT',NULL,'Bai 6',NULL,NULL,'Tháng 8 – 1945, Hồ Chí Minh cùng Trung ương Đảng, Mặt trận Việt Minh lãnh đạo nhân dân Tổng khởi nghĩa giành chính quyền thắng lợi, và được cử làm Chủ tịch của Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hoà.','SGK11:tong-khoi-nghia-gianh-chinh-quyen','2026-06-30 00:27:12'),(60808,'tong-khoi-nghia-gianh-chinh-quyen',11,'KNTT',NULL,'Bai 11',NULL,NULL,'Tháng 8 – 1945, Hồ Chí Minh cùng Trung ương Đảng, Mặt trận Việt Minh lãnh đạo nhân dân Tổng khởi nghĩa giành chính quyền thắng lợi, và được cử làm Chủ tịch của Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hoà.','SGK11:tong-khoi-nghia-gianh-chinh-quyen','2026-06-30 00:27:12'),(60809,'tong-khoi-nghia-gianh-chinh-quyen',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Tháng 8 – 1945, Hồ Chí Minh cùng Trung ương Đảng, Mặt trận Việt Minh lãnh đạo nhân dân Tổng khởi nghĩa giành chính quyền thắng lợi, và được cử làm Chủ tịch của Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hoà.','SGK12:tong-khoi-nghia-gianh-chinh-quyen','2026-06-30 00:27:12'),(60810,'tong-khoi-nghia-gianh-chinh-quyen',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Tháng 8 – 1945, Hồ Chí Minh cùng Trung ương Đảng, Mặt trận Việt Minh lãnh đạo nhân dân Tổng khởi nghĩa giành chính quyền thắng lợi, và được cử làm Chủ tịch của Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hoà.','SGK12:tong-khoi-nghia-gianh-chinh-quyen','2026-06-30 00:27:12'),(60811,'ho-chi-minh-cong-bo-tuyen-ngon-doc-lap',10,'KNTT',NULL,'Bai 1',NULL,NULL,'Trang đầu bản Tuyên ngôn Độc lập do Chủ tịch Hồ Chí Minh soạn thảo và công bố ngày 2 – 9 – 1945 được dùng làm ví dụ về sử liệu chữ viết.','SGK10:ho-chi-minh-cong-bo-tuyen-ngon-doc-lap','2026-06-30 00:27:12'),(60812,'ho-chi-minh-cong-bo-tuyen-ngon-doc-lap',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Ngày 2-9-1945, tại Quảng trường Ba Đình (Hà Nội), Hồ Chí Minh đọc Tuyên ngôn Độc lập, tuyên bố thành lập nước Việt Nam Dân chủ Cộng hoà.','SGK12:ho-chi-minh-cong-bo-tuyen-ngon-doc-lap','2026-06-30 00:27:12'),(60813,'ho-chi-minh-cong-bo-tuyen-ngon-doc-lap',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Ngày 2-9-1945, tại Quảng trường Ba Đình (Hà Nội), Hồ Chí Minh đọc Tuyên ngôn Độc lập, tuyên bố thành lập nước Việt Nam Dân chủ Cộng hoà.','SGK12:ho-chi-minh-cong-bo-tuyen-ngon-doc-lap','2026-06-30 00:27:12'),(60814,'ho-chi-minh-cong-bo-tuyen-ngon-doc-lap',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Ngày 2-9-1945, tại Quảng trường Ba Đình (Hà Nội), Hồ Chí Minh đọc Tuyên ngôn Độc lập, tuyên bố thành lập nước Việt Nam Dân chủ Cộng hoà.','SGK12:ho-chi-minh-cong-bo-tuyen-ngon-doc-lap','2026-06-30 00:27:12'),(60815,'phap-xa-sung-sai-gon-cho-lon-1945',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Ngày 2-9-1945, trong khi nhân dân Sài Gòn – Chợ Lớn tổ chức mít tinh chào mừng ngày độc lập, quân Pháp đã bất ngờ xả súng vào đồng bào ta.','SGK12:phap-xa-sung-sai-gon-cho-lon-1945','2026-06-30 00:27:12'),(60816,'phap-danh-up-uy-ban-hanh-chinh-nam-bo-1945',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Đêm 22, rạng sáng 23 – 9 – 1945, thực dân Pháp đánh úp trụ sở Uỷ ban hành chính Nam Bộ và cơ quan tự vệ thành phố Sài Gòn, mở đầu cuộc chiến tranh xâm lược Việt Nam lần thứ hai.','SGK12:phap-danh-up-uy-ban-hanh-chinh-nam-bo-1945','2026-06-30 00:27:12'),(60817,'thanh-lap-uy-ban-khang-chien-nam-bo-1945',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Trước tình hình thực dân Pháp đánh úp Sài Gòn, ngày 23 - 9 - 1945, Uỷ ban kháng chiến Nam Bộ được thành lập. Quân dân Nam Bộ ra sức củng cố, xây dựng lực lượng vũ trang và tổ chức chiến đấu nhằm kìm chân quân Pháp trong các thành phố, thị xã ở phía Nam vĩ tuyến 16.','SGK12:thanh-lap-uy-ban-khang-chien-nam-bo-1945','2026-06-30 00:27:12'),(60818,'giai-doan-hoan-thanh-cuoc-dau-tranh-gianh-doc-lap-dan-toc-o-dong-nam-a',11,'KNTT',NULL,'Bai 6',NULL,NULL,'Giai đoạn 1945-1975 là thời kì các nước Đông Nam Á hoàn thành cuộc đấu tranh giành độc lập dân tộc. Thắng lợi của lực lượng Đồng minh trong Chiến tranh thế giới thứ hai đã tạo thời cơ thuận lợi. Trong 10 năm đầu (1945-1954), In-đô-nê-xi-a, Việt Nam, Lào tuyên bố độc lập, Phi-líp-pin (1946) và Miến Điện (1947) được trao trả độc lập. Trong hơn 20 năm sau (1954-1975), các nước còn lại lần lượt hoàn thành độc lập (trừ Bru-nây năm 1984).','SGK11:giai-doan-hoan-thanh-cuoc-dau-tranh-gianh-doc-lap-dan-toc-o-dong-nam-a','2026-06-30 00:27:12'),(60819,'ho-chi-minh-gui-thu-toi-chu-tich-hoi-dong-lien-hop-quoc',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Về đối ngoại, ngay sau Cách mạng tháng Tám thành công, Chủ tịch Hồ Chí Minh đã gửi thư tới Chủ tịch Hội đồng Liên hợp quốc và nguyên thủ các nước lớn, khẳng định nền độc lập của Việt Nam.','SGK12:ho-chi-minh-gui-thu-toi-chu-tich-hoi-dong-lien-hop-quoc','2026-06-30 00:27:12'),(60820,'hoat-dong-doi-ngoai-cua-vndcch-voi-trung-hoa-dan-quoc',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Với Trung Hoa Dân quốc, Chính phủ Việt Nam Dân chủ Cộng hoà chủ động vừa đấu tranh chính trị, vừa vận động ngoại giao; thực hiện các hoạt động hữu nghị, thân thiện với nhân dân Trung Quốc và hoà hoãn với quân Trung Hoa Dân quốc ở Việt Nam để tranh thủ thời gian củng cố chính quyền cách mạng.','SGK12:hoat-dong-doi-ngoai-cua-vndcch-voi-trung-hoa-dan-quoc','2026-06-30 00:27:13'),(60821,'khang-chien-chong-thuc-dan-phap-1945-1954',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Cuộc kháng chiến chống thực dân Pháp diễn ra từ năm 1945 đến năm 1954, trong bối cảnh quốc tế và trong nước phức tạp. Cuộc kháng chiến trải qua nhiều giai đoạn, từ kháng chiến ở Nam Bộ, kháng chiến toàn quốc giai đoạn đầu, đến bước phát triển mới và kết thúc bằng chiến thắng Điện Biên Phủ.','SGK12:khang-chien-chong-thuc-dan-phap-1945-1954','2026-06-30 00:27:13'),(60822,'khang-chien-chong-thuc-dan-phap-1945-1954',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Cuộc kháng chiến chống thực dân Pháp diễn ra từ năm 1945 đến năm 1954, trong bối cảnh quốc tế và trong nước phức tạp. Cuộc kháng chiến trải qua nhiều giai đoạn, từ kháng chiến ở Nam Bộ, kháng chiến toàn quốc giai đoạn đầu, đến bước phát triển mới và kết thúc bằng chiến thắng Điện Biên Phủ.','SGK12:khang-chien-chong-thuc-dan-phap-1945-1954','2026-06-30 00:27:13'),(60823,'khang-chien-chong-thuc-dan-phap-1945-1954',12,'KNTT',NULL,'Bai 2',NULL,NULL,'Chiến tranh xâm lược Việt Nam của thực dân Pháp (1945 - 1954) là một trong những cuộc chiến tranh cục bộ tiêu biểu.','SGK12:khang-chien-chong-thuc-dan-phap-1945-1954','2026-06-30 00:27:13'),(60824,'khang-chien-chong-thuc-dan-phap-o-viet-nam-lao-cam-pu-chia',11,'KNTT',NULL,'Bai 6',NULL,NULL,'Mặc dù Việt Nam và Lào tuyên bố độc lập ngay từ năm 1945, nhưng ba nước Đông Dương (Việt Nam, Lào, Cam-pu-chia) lại phải trải qua cuộc kháng chiến chống thực dân Pháp từ 1945 đến 1954. Đây là cuộc chiến đấu quyết liệt nhất trong lịch sử đấu tranh giành độc lập dân tộc ở Đông Nam Á.','SGK11:khang-chien-chong-thuc-dan-phap-o-viet-nam-lao-cam-pu-chia','2026-06-30 00:27:13'),(60825,'lang-xa-viet-nam-bien-doi-sau-1945',11,'KNTT',NULL,'Bai 9',NULL,NULL,'Từ sau năm 1945: Làng xã Việt Nam trải qua nhiều biến đổi quan trọng về kinh tế, văn hoá, xã hội. Xu hướng quản lí hành chính đối với làng xã ngày càng chặt chẽ.','SGK11:lang-xa-viet-nam-bien-doi-sau-1945','2026-06-30 00:27:13'),(60826,'viet-nam-de-nghi-lien-hop-quoc-cong-nhan-vndcch',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Chính phủ Việt Nam đã gửi thư, công hàm đề nghị Đại hội đồng Liên hợp quốc và các nước lớn công nhận Nhà nước Việt Nam Dân chủ Cộng hoà.','SGK12:viet-nam-de-nghi-lien-hop-quoc-cong-nhan-vndcch','2026-06-30 00:27:13'),(60827,'ho-chi-minh-gui-loi-keu-goi-quoc-dan-di-bo-phieu',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Để tạo cơ sở pháp lí cho chính quyền cách mạng và thực hiện quyền làm chủ của nhân dân, ngày 5 – 1 – 1946, Chủ tịch Hồ Chí Minh gửi Lời kêu gọi quốc dân đi bỏ phiếu.','SGK12:ho-chi-minh-gui-loi-keu-goi-quoc-dan-di-bo-phieu','2026-06-30 00:27:13'),(60828,'ho-chi-minh-duoc-bau-chu-tich-nuoc-1946',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Tháng 1 – 1946, Hồ Chí Minh được Quốc hội khoá I đã bầu làm Chủ tịch nước Việt Nam Dân chủ Cộng hoà.','SGK12:ho-chi-minh-duoc-bau-chu-tich-nuoc-1946','2026-06-30 00:27:13'),(60829,'hiep-uoc-hoa-phap-1946',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Ngày 28-2-1946, thực dân Pháp và Chính phủ Trung Hoa Dân quốc kí Hiệp ước Hoa - Pháp.','SGK12:hiep-uoc-hoa-phap-1946','2026-06-30 00:27:13'),(60830,'ho-chi-minh-ki-hiep-dinh-so-bo-voi-g-xanh-to-ni',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Sau khi thực dân Pháp và Trung Hoa Dân quốc kí Hiệp ước Hoa - Pháp, Chủ tịch Hồ Chí Minh thay mặt Chính phủ Việt Nam Dân chủ Cộng hoà, kí với G. Xanh-tơ-ni đại diện Chính phủ Pháp Hiệp định Sơ bộ. Hiệp định Sơ bộ đã làm thất bại âm mưu câu kết giữa Pháp và Trung Hoa Dân quốc, tạo thêm thời gian hoà bình để củng cố và xây dựng lực lượng.','SGK12:ho-chi-minh-ki-hiep-dinh-so-bo-voi-g-xanh-to-ni','2026-06-30 00:27:13'),(60831,'ho-chi-minh-ki-hiep-dinh-so-bo-voi-g-xanh-to-ni',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Sau khi thực dân Pháp và Trung Hoa Dân quốc kí Hiệp ước Hoa - Pháp, Chủ tịch Hồ Chí Minh thay mặt Chính phủ Việt Nam Dân chủ Cộng hoà, kí với G. Xanh-tơ-ni đại diện Chính phủ Pháp Hiệp định Sơ bộ. Hiệp định Sơ bộ đã làm thất bại âm mưu câu kết giữa Pháp và Trung Hoa Dân quốc, tạo thêm thời gian hoà bình để củng cố và xây dựng lực lượng.','SGK12:ho-chi-minh-ki-hiep-dinh-so-bo-voi-g-xanh-to-ni','2026-06-30 00:27:13'),(60832,'ho-chi-minh-ki-hiep-dinh-so-bo-voi-g-xanh-to-ni',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Sau khi thực dân Pháp và Trung Hoa Dân quốc kí Hiệp ước Hoa - Pháp, Chủ tịch Hồ Chí Minh thay mặt Chính phủ Việt Nam Dân chủ Cộng hoà, kí với G. Xanh-tơ-ni đại diện Chính phủ Pháp Hiệp định Sơ bộ. Hiệp định Sơ bộ đã làm thất bại âm mưu câu kết giữa Pháp và Trung Hoa Dân quốc, tạo thêm thời gian hoà bình để củng cố và xây dựng lực lượng.','SGK12:ho-chi-minh-ki-hiep-dinh-so-bo-voi-g-xanh-to-ni','2026-06-30 00:27:13'),(60833,'ho-chi-minh-sang-phap-van-dong-ngoai-giao-va-ki-tam-uoc',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Mặc dù Hiệp định Sơ bộ được kí kết nhưng thực dân Pháp vẫn ra sức phá hoại hiệp định. Chủ tịch Hồ Chí Minh phải trực tiếp sang Pháp vận động ngoại giao. Cuộc đàm phán chính thức giữa Việt Nam và Pháp đã thất bại do dã tâm xâm lược của Pháp. Để cứu vãn tình hình, Chủ tịch Hồ Chí Minh đã chủ động gặp đại diện Chính phủ Pháp và kí bản Tạm ước (14 – 9 – 1946) nhằm tiếp tục kéo dài thời gian hoà bình, tạo điều kiện chuẩn bị cho cuộc kháng chiến lâu dài.','SGK12:ho-chi-minh-sang-phap-van-dong-ngoai-giao-va-ki-tam-uoc','2026-06-30 00:27:13'),(60834,'ki-tam-uoc-viet-phap',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Chủ tịch Hồ Chí Minh tiếp tục kí với đại diện Chính phủ Pháp bản Tạm ước Việt - Pháp (14 – 9 – 1946) để kéo dài thời gian hoà bình, chuẩn bị kháng chiến.','SGK12:ki-tam-uoc-viet-phap','2026-06-30 00:27:13'),(60835,'chien-dau-cac-do-thi-phia-bac-vi-tuyen-16-1946-1947',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Cuộc chiến đấu ở các đô thị phía Bắc vĩ tuyến 16 diễn ra từ ngày 19 – 12 – 1946 đến 17 – 2 – 1947 ở các đô thị như Nam Định, Vinh, đặc biệt là Hà Nội. Các trận đánh ác liệt đã diễn ra tại khu vực Bắc Bộ Phủ, Bưu điện Bờ Hồ, ga Hàng Cỏ, phố Khâm Thiên. Kết quả là đã giam chân quân Pháp ở Hà Nội và các thành phố, thị xã, giúp lực lượng quân chủ lực của ta chủ động rút lui an toàn ra căn cứ kháng chiến.','SGK12:chien-dau-cac-do-thi-phia-bac-vi-tuyen-16-1946-1947','2026-06-30 00:27:13'),(60836,'ho-chi-minh-ra-loi-keu-goi-toan-quoc-khang-chien',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Khi mọi nhân nhượng của Việt Nam đã đến giới hạn cuối cùng, tối ngày 19-12-1946, Chủ tịch Hồ Chí Minh thay mặt Trung ương Đảng và Chính phủ ra Lời kêu gọi toàn quốc kháng chiến.','SGK12:ho-chi-minh-ra-loi-keu-goi-toan-quoc-khang-chien','2026-06-30 00:27:13'),(60837,'ho-chi-minh-ra-loi-keu-goi-toan-quoc-khang-chien',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Trước tình hình thực dân Pháp luôn tìm cách phá hoại những điều đã kí kết và đẩy mạnh xâm lược cả nước ta, ngày 19 – 12 – 1946, Chủ tịch Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến.','SGK12:ho-chi-minh-ra-loi-keu-goi-toan-quoc-khang-chien','2026-06-30 00:27:13'),(60838,'khang-chien-toan-quoc-chong-thuc-dan-phap-bung-no',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Cuộc kháng chiến toàn quốc chống thực dân Pháp bùng nổ (12 – 1946).','SGK12:khang-chien-toan-quoc-chong-thuc-dan-phap-bung-no','2026-06-30 00:27:13'),(60839,'viet-nam-the-hien-thien-chi-hoa-binh-sau-12-1946',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Từ khi cuộc kháng chiến toàn quốc chống thực dân Pháp bùng nổ (12 – 1946), Việt Nam vẫn thể hiện thiện chí hoà bình, để nghị Chính phủ Pháp tiếp tục mở các cuộc thương lượng, kêu gọi nhân dân Pháp chống chiến tranh.','SGK12:viet-nam-the-hien-thien-chi-hoa-binh-sau-12-1946','2026-06-30 00:27:13'),(60840,'hien-phap-viet-nam-dan-chu-cong-hoa-1946',10,'KNTT',NULL,'Bai 14',NULL,NULL,'Hiến pháp nước Việt Nam Dân chủ Cộng hoà năm 1946 khẳng định: “Đoàn kết toàn dân không phân biệt giống nòi, gái, trai, giai cấp, tôn giáo”.','SGK10:hien-phap-viet-nam-dan-chu-cong-hoa-1946','2026-06-30 00:27:13'),(60841,'phap-cho-hai-quan-tru-dong-truong-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Năm 1946, chính quyền thực dân Pháp cho hải quân trú đóng ở các đảo chính thuộc quần đảo Trường Sa và yêu cầu quân đội Trung Hoa Dân quốc rút khỏi các đảo đã chiếm đóng trái phép.','SGK11:phap-cho-hai-quan-tru-dong-truong-sa','2026-06-30 00:27:13'),(60842,'chien-dich-viet-bac-thu-dong-1947',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Chiến dịch Việt Bắc thu – đông năm 1947 diễn ra từ tháng 10 đến tháng 12 – 1947 khi thực dân Pháp mở cuộc tấn công lên Việt Bắc. Quân đội Việt Nam chủ động bao vây, tiến công đẩy lùi quân Pháp khỏi một số vị trí quan trọng như Chợ Đồn, Chợ Rã, Đoan Hùng. Sau hai tháng, đại bộ phận quân Pháp phải rút chạy khỏi Việt Bắc; cơ quan đầu não của cuộc kháng chiến được bảo vệ an toàn; bộ đội ta thu được nhiều vũ khí và ngày càng trưởng thành.','SGK12:chien-dich-viet-bac-thu-dong-1947','2026-06-30 00:27:13'),(60843,'chien-dich-bien-gioi-thu-dong-1950',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Chiến dịch Biên giới thu – đông năm 1950 diễn ra từ tháng 9 đến tháng 10 – 1950 ở khu vực biên giới Việt – Trung. Quân đội Việt Nam tấn công cứ điểm Đông Khê, mai phục, chặn đánh quân Pháp ở nhiều nơi trên Đường số 4, buộc chúng phải rút chạy. Sau gần một tháng, quân ta đã giải phóng được khu vực biên giới rộng lớn, mở đường liên lạc quốc tế, bảo vệ được căn cứ địa Việt Bắc, chọc thủng Hành lang Đông - Tây, làm phá sản Kế hoạch Rơ-ve của Pháp.','SGK12:chien-dich-bien-gioi-thu-dong-1950','2026-06-30 00:27:13'),(60844,'vndcch-thiet-lap-quan-he-ngoai-giao-voi-cac-nuoc-xhcn',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Năm 1950, Việt Nam Dân chủ Cộng hoà thiết lập quan hệ ngoại giao với Cộng hoà Nhân dân Trung Hoa, Liên Xô và các nước xã hội chủ nghĩa khác. Đây là một thắng lợi chính trị to lớn, tạo tiền đề cho những thắng lợi quân sự sau này.','SGK12:vndcch-thiet-lap-quan-he-ngoai-giao-voi-cac-nuoc-xhcn','2026-06-30 00:27:13'),(60845,'dai-hoi-dai-bieu-lan-thu-ii-cua-dang-lao-dong-viet-nam',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Chủ trì Đại hội đại biểu lần thứ II của Đảng Lao động Việt Nam (2 – 1951) – Đại hội kháng chiến thắng lợi.','SGK12:dai-hoi-dai-bieu-lan-thu-ii-cua-dang-lao-dong-viet-nam','2026-06-30 00:27:13'),(60846,'dai-hoi-dai-bieu-lan-thu-ii-dang-cong-san-dong-duong-1951',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Tháng 2 – 1951, Đại hội đại biểu lần thứ II của Đảng Cộng sản Đông Dương đã quyết định đổi tên Đảng là Đảng Lao động Việt Nam và khẳng định, bổ sung, hoàn chỉnh đường lối kháng chiến.','SGK12:dai-hoi-dai-bieu-lan-thu-ii-dang-cong-san-dong-duong-1951','2026-06-30 00:27:13'),(60847,'ho-chi-minh-duoc-bau-chu-tich-ban-chap-hanh-trung-uong-dang-1951',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Tại Đại hội lần thứ II của Đảng Cộng sản Đông Dương (2 – 1951), Hồ Chí Minh được bầu làm Chủ tịch Ban Chấp hành Trung ương Đảng.','SGK12:ho-chi-minh-duoc-bau-chu-tich-ban-chap-hanh-trung-uong-dang-1951','2026-06-30 00:27:13'),(60848,'mat-tran-lien-viet-ra-doi-1951',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Ngày 3-3-1951, Mặt trận Liên hiệp quốc dân Việt Nam (gọi tắt là Mặt trận Liên Việt) ra đời trên cơ sở hợp nhất Mặt trận Việt Minh và Hội Liên Việt.','SGK12:mat-tran-lien-viet-ra-doi-1951','2026-06-30 00:27:14'),(60849,'chu-quyen-viet-nam-duoc-tuyen-bo-cong-nhan-hoi-nghi-xan-phran-xi-xo',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Đến tháng 9 – 1951, chủ quyền của Việt Nam đối với quần đảo Hoàng Sa và quần đảo Trường Sa tiếp tục được tuyên bố và công nhận tại Hội nghị Hoà bình Xan Phran-xi-xcô với sự tham dự của 51 quốc gia thành viên Liên hợp quốc.','SGK11:chu-quyen-viet-nam-duoc-tuyen-bo-cong-nhan-hoi-nghi-xan-phran-xi-xo','2026-06-30 00:27:14'),(60850,'thanh-lap-lien-minh-nhan-dan-viet-mien-lao',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Năm 1951, Liên minh nhân dân Việt – Miên - Lào được thành lập trên cơ sở tự nguyện, bình đẳng và tôn trọng chủ quyền của nhau.','SGK12:thanh-lap-lien-minh-nhan-dan-viet-mien-lao','2026-06-30 00:27:14'),(60851,'cuoc-van-dong-san-xuat-va-tiet-kiem-1952',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Năm 1952, cuộc vận động sản xuất và tiết kiệm được phát động, đã trở thành một phong trào quần chúng sôi nổi, lôi cuốn mọi ngành, mọi giới tham gia. Các ngành kinh tế cơ bản đáp ứng được yêu cầu của cuộc kháng chiến và đời sống nhân dân.','SGK12:cuoc-van-dong-san-xuat-va-tiet-kiem-1952','2026-06-30 00:27:14'),(60852,'dai-hoi-chien-si-thi-dua-can-bo-guong-mau-toan-quoc-lan-thu-nhat-1952',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Giữa lúc cuộc kháng chiến đang diễn ra quyết liệt, Đại hội Chiến sĩ thi đua và Cán bộ gương mẫu toàn quốc lần thứ nhất được tổ chức tại chiến khu Việt Bắc (1952), đã tuyên dương những anh hùng đầu tiên tiêu biểu cho phong trào thi đua yêu nước của cả nước. Tại Đại hội, Chủ tịch Hồ Chí Minh khẳng định: “Thi đua là yêu nước, yêu nước thì phải thi đua\".','SGK12:dai-hoi-chien-si-thi-dua-can-bo-guong-mau-toan-quoc-lan-thu-nhat-1952','2026-06-30 00:27:14'),(60853,'ke-hoach-na-va-1953',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Được sự thoả thuận của Mỹ, tháng 7 – 1953, thực dân Pháp để ra Kế hoạch Na-va với hi vọng trong vòng 18 tháng giành một thắng lợi quân sự quyết định để kết thúc chiến tranh trong danh dự.','SGK12:ke-hoach-na-va-1953','2026-06-30 00:27:14'),(60854,'quoc-hoi-thong-qua-luat-cai-cach-ruong-dat-1953',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Tháng 12 – 1953, Quốc hội thông qua Luật Cải cách ruộng đất và quyết định tiến hành cải cách ruộng đất ở vùng tự do.','SGK12:quoc-hoi-thong-qua-luat-cai-cach-ruong-dat-1953','2026-06-30 00:27:14'),(60855,'chien-dich-dien-bien-phu-1954',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Đầu tháng 12 – 1953, Bộ Chính trị Trung ương Đảng thông qua quyết định mở chiến dịch Điện Biên Phủ. Chiến dịch trải qua 56 ngày đêm (từ 13 – 3 – 1954 đến 7-5-1954) với ba đợt. Đợt 1 (13-3 đến 17-3-1954) tấn công Him Lam và đồi Độc Lập, bức hàng Bản Kéo. Đợt 2 (30-3 đến 26-4-1954) tấn công các cứ điểm phía đông phân khu Trung tâm, kiểm soát sân bay Mường Thanh. Đợt 3 (1-5 đến 7-5-1954) đồng loạt tấn công phân khu Trung tâm và phân khu Nam, buộc tướng Đờ Ca-xtơ-ri cùng toàn bộ Bộ Tham mưu của Pháp đầu hàng vào 17 giờ 30 ngày 7 - 5.','SGK12:chien-dich-dien-bien-phu-1954','2026-06-30 00:27:14'),(60856,'hoi-nghi-gio-ne-vo-ve-dong-duong',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Tháng 5 1954, Hội nghị quốc tế về Đông Dương được tổ chức ở Giơ-ne-vơ (Thuỵ Sĩ). Chính phủ Việt Nam Dân chủ Cộng hoà đã kiên trì đấu tranh bảo vệ các quyền dân tộc cơ bản của ba nước Đông Dương.','SGK12:hoi-nghi-gio-ne-vo-ve-dong-duong','2026-06-30 00:27:14'),(60857,'ky-ket-hiep-dinh-go-ne-vo-1954',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Thắng lợi ở Điện Biên Phủ đã tạo cơ sở cho việc đàm phán và kí kết Hiệp định Giơ-ne-vơ về chấm dứt chiến tranh, lập lại hoà bình ở Đông Dương (21-7-1954).','SGK12:ky-ket-hiep-dinh-go-ne-vo-1954','2026-06-30 00:27:14'),(60858,'ky-ket-hiep-dinh-go-ne-vo-1954',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Thắng lợi ở Điện Biên Phủ đã tạo cơ sở cho việc đàm phán và kí kết Hiệp định Giơ-ne-vơ về chấm dứt chiến tranh, lập lại hoà bình ở Đông Dương (21-7-1954).','SGK12:ky-ket-hiep-dinh-go-ne-vo-1954','2026-06-30 00:27:14'),(60859,'chien-tranh-bao-ve-doc-lap-dan-toc-va-chu-quyen-quoc-gia-o-dong-duong',11,'KNTT',NULL,'Bai 6',NULL,NULL,'Từ năm 1954, sau khi Mỹ can thiệp vào Đông Dương, nhân dân ba nước Đông Dương (Việt Nam, Lào, Cam-pu-chia) phải tiếp tục tiến hành cuộc chiến tranh bảo vệ nền độc lập dân tộc và chủ quyền quốc gia.','SGK11:chien-tranh-bao-ve-doc-lap-dan-toc-va-chu-quyen-quoc-gia-o-dong-duong','2026-06-30 00:27:14'),(60860,'khang-chien-chong-my-cuu-nuoc',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Cuộc kháng chiến chống Mỹ, cứu nước diễn ra từ năm 1954 đến năm 1975, trải qua nhiều giai đoạn với sự tham gia của nhân dân hai miền Nam - Bắc, nhằm hoàn thành cách mạng dân tộc dân chủ nhân dân và thống nhất đất nước.','SGK12:khang-chien-chong-my-cuu-nuoc','2026-06-30 00:27:14'),(60861,'khang-chien-chong-my-cuu-nuoc',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Cuộc kháng chiến chống Mỹ, cứu nước diễn ra từ năm 1954 đến năm 1975, trải qua nhiều giai đoạn với sự tham gia của nhân dân hai miền Nam - Bắc, nhằm hoàn thành cách mạng dân tộc dân chủ nhân dân và thống nhất đất nước.','SGK12:khang-chien-chong-my-cuu-nuoc','2026-06-30 00:27:14'),(60862,'khang-chien-chong-my-cuu-nuoc',12,'KNTT',NULL,'Bai 2',NULL,NULL,'Chiến tranh xâm lược Việt Nam của đế quốc Mỹ (1954 - 1975) là một trong những cuộc chiến tranh cục bộ tiêu biểu.','SGK12:khang-chien-chong-my-cuu-nuoc','2026-06-30 00:27:14'),(60863,'my-can-thiep-vao-dong-duong',11,'KNTT',NULL,'Bai 6',NULL,NULL,'Từ năm 1954, Mỹ can thiệp vào Đông Dương, khiến nhân dân ba nước Đông Dương phải tiếp tục tiến hành cuộc chiến tranh bảo vệ nền độc lập dân tộc và chủ quyền quốc gia.','SGK11:my-can-thiep-vao-dong-duong','2026-06-30 00:27:14'),(60864,'my-thay-chan-phap-dung-chinh-quyen-ngo-dinh-diem',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Ngay sau Hiệp định Giơ-ne-vơ, Mỹ thay chân Pháp, dựng lên chính quyền tay sai đứng đầu là Ngô Đình Diệm (chính quyền Sài Gòn) ở miền Nam Việt Nam.','SGK12:my-thay-chan-phap-dung-chinh-quyen-ngo-dinh-diem','2026-06-30 00:27:14'),(60865,'quan-li-hanh-chinh-chinh-quyen-sai-gon-hoang-sa-truong-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Từ năm 1954 đến năm 1975, hai quần đảo được đặt dưới sự quản lí hành chính của chính quyền Sài Gòn. Chính quyền Sài Gòn đã liên tục thực thi chủ quyền của Việt Nam ở quần đảo Hoàng Sa và quần đảo Trường Sa thông qua việc ban hành các văn bản hành chính nhà nước, cử quân đồn trú, dựng bia chủ quyền, treo cờ trên các đảo chính. Về mặt hành chính, quần đảo Hoàng Sa thuộc tỉnh Quảng Nam và quần đảo Trường Sa thuộc tỉnh Phước Tuy (tỉnh Bà Rịa - Vũng Tàu ngày nay).','SGK11:quan-li-hanh-chinh-chinh-quyen-sai-gon-hoang-sa-truong-sa','2026-06-30 00:27:14'),(60866,'viet-nam-tam-thoi-bi-chia-cat-hai-mien',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Việt Nam tạm thời bị chia cắt làm hai miền: miền Bắc được hoàn toàn giải phóng, tiến lên xây dựng chủ nghĩa xã hội, miền Nam phải tiếp tục cuộc cách mạng dân tộc dân chủ nhân dân, thực hiện hoà bình, thống nhất nước nhà.','SGK12:viet-nam-tam-thoi-bi-chia-cat-hai-mien','2026-06-30 00:27:14'),(60867,'ho-chi-minh-chu-tich-tong-bi-thu-dang-lao-dong-1956',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Tháng 10 – 1956, Chủ tịch Hồ Chí Minh là Chủ tịch Đảng, kiêm Tổng Bí thư Đảng Lao động Việt Nam.','SGK12:ho-chi-minh-chu-tich-tong-bi-thu-dang-lao-dong-1956','2026-06-30 00:27:14'),(60868,'dai-loan-chiem-dong-dao-ba-binh-truong-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Đài Loan - Năm 1956, chiếm đóng đảo Ba Bình thuộc quần đảo Trường Sa.','SGK11:dai-loan-chiem-dong-dao-ba-binh-truong-sa','2026-06-30 00:27:14'),(60869,'philippin-tuyen-bo-quyen-khai-thac-lap-nghiep-truong-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Phi-líp-pin - Năm 1956, tuyên bố có quyền khai thác, lập nghiệp tại nhóm đảo Trường Sa.','SGK11:philippin-tuyen-bo-quyen-khai-thac-lap-nghiep-truong-sa','2026-06-30 00:27:14'),(60870,'viet-nam-danh-chiem-nua-phia-dong-hoang-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Việt Nam - Năm 1956: đánh chiếm nửa phía đông của quần đảo Hoàng Sa (nhóm An Vĩnh).','SGK11:viet-nam-danh-chiem-nua-phia-dong-hoang-sa','2026-06-30 00:27:14'),(60871,'hoi-nghi-ban-chap-hanh-trung-uong-lan-thu-15-dang-lao-dong-viet-nam',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Tháng 1 – 1959, Hội nghị Ban Chấp hành Trung ương lần thứ 15 của Đảng Lao động Việt Nam khẳng định: ngoài con đường sử dụng bạo lực cách mạng, nhân dân miền Nam không còn con đường nào khác. Nghị quyết đã thổi bùng lên phong trào Đồng khởi (1959 – 1960).','SGK12:hoi-nghi-ban-chap-hanh-trung-uong-lan-thu-15-dang-lao-dong-viet-nam','2026-06-30 00:27:14'),(60872,'hoi-nghi-ban-chap-hanh-trung-uong-lan-thu-15-dang-lao-dong-viet-nam',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Tháng 1 – 1959, giữa lúc cách mạng miền Nam gặp nhiều khó khăn, Chủ tịch Hồ Chí Minh chủ trì Hội nghị lần thứ 15 Ban Chấp hành Trung ương Đảng Lao động Việt Nam, xác định phương hướng cơ bản cho cách mạng miền Nam.','SGK12:hoi-nghi-ban-chap-hanh-trung-uong-lan-thu-15-dang-lao-dong-viet-nam','2026-06-30 00:27:14'),(60873,'dai-hoi-dai-bieu-toan-quoc-lan-thu-iii-cua-dang-lao-dong-viet-nam',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Chủ tịch Hồ Chí Minh chủ trì và chỉ đạo xây dựng Nghị quyết Đại hội đại biểu toàn quốc lần thứ III của Đảng Lao động Việt Nam (9 – 1960). Người nêu rõ: Đại hội này là đại hội xây dựng chủ nghĩa xã hội ở miền Bắc và đấu tranh thống nhất nước nhà.','SGK12:dai-hoi-dai-bieu-toan-quoc-lan-thu-iii-cua-dang-lao-dong-viet-nam','2026-06-30 00:27:14'),(60874,'dai-hoi-dai-bieu-toan-quoc-lan-thu-iii-dang-lao-dong-viet-nam',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Đại hội đại biểu toàn quốc lần thứ III Đảng Lao động Việt Nam (9 – 1960) được tổ chức tại Hà Nội. Đại hội đã xác định nhiệm vụ chiến lược của cách mạng cả nước, vai trò, vị trí của cách mạng từng miền và mối quan hệ giữa cách mạng hai miền.','SGK12:dai-hoi-dai-bieu-toan-quoc-lan-thu-iii-dang-lao-dong-viet-nam','2026-06-30 00:27:14'),(60875,'ho-chi-minh-tiep-tuc-duoc-bau-chu-tich-dang-lao-dong-1960',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Tại Đại hội lần thứ III của Đảng (9 – 1960), Chủ tịch Hồ Chí Minh tiếp tục được bầu làm Chủ tịch Đảng Lao động Việt Nam.','SGK12:ho-chi-minh-tiep-tuc-duoc-bau-chu-tich-dang-lao-dong-1960','2026-06-30 00:27:14'),(60876,'thanh-lap-mat-tran-dan-toc-giai-phong-mien-nam-viet-nam',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Thắng lợi của phong trào Đồng khởi đã giáng đòn nặng nề vào chính sách thực dân mới của Mỹ, làm lung lay chính quyền Ngô Đình Diệm. Thắng lợi này đồng thời đánh dấu bước phát triển nhảy vọt của cách mạng miền Nam, chuyển từ thế giữ gìn lực lượng sang thế tiến công, mở ra vùng giải phóng rộng lớn, đưa đến việc thành lập Mặt trận Dân tộc giải phóng miền Nam Việt Nam (20 – 12 – 1960), thúc đẩy lực lượng vũ trang cách mạng phát triển.','SGK12:thanh-lap-mat-tran-dan-toc-giai-phong-mien-nam-viet-nam','2026-06-30 00:27:15'),(60877,'thanh-lap-quan-giai-phong-mien-nam',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Để đáp ứng yêu cầu của cuộc kháng chiến, ngày 15 – 2 – 1961, các lực lượng vũ trang cách mạng thống nhất thành Quân Giải phóng miền Nam.','SGK12:thanh-lap-quan-giai-phong-mien-nam','2026-06-30 00:27:15'),(60878,'chu-tich-ho-chi-minh-tham-quan-cang-bai-chay-1961',11,'KNTT',NULL,'Bai 15',NULL,NULL,'Trong dịp tới thăm Bộ đội Hải quân tại Quân cảng Bãi Cháy (năm 1961), Chủ tịch Hồ Chí Minh đã căn dặn: “Ngày trước ta chỉ có đêm và rừng. Ngày nay ta có ngày, có trời, có biển. Bờ biển ta dài, tươi đẹp, ta phải biết giữ gìn lấy nó\".','SGK11:chu-tich-ho-chi-minh-tham-quan-cang-bai-chay-1961','2026-06-30 00:27:15'),(60879,'chien-thang-ap-bac',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Trên mặt trận quân sự, chiến thắng Ấp Bắc (Mỹ Tho, tháng 1 1963) đã mở ra khả năng đánh bại chiến thuật “trực thăng vận, thiết xa vận, chứng minh khả năng quân dân Việt Nam có thể đánh bại chiến lược “Chiến tranh đặc biệt” của Mỹ.','SGK12:chien-thang-ap-bac','2026-06-30 00:27:15'),(60880,'chien-tranh-pha-hoai-mien-bac-lan-thu-nhat',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Sau khi dựng lên sự kiện “Vịnh Bắc Bộ” (8 – 1964), Mỹ chính thức mở rộng chiến tranh bằng không quân và hải quân phá hoại miền Bắc lần thứ nhất. Quân dân miền Bắc kịp thời chuyển mọi hoạt động sang thời chiến, vừa chiến đấu chống chiến tranh phá hoại, vừa tiếp tục phát triển kinh tế – xã hội và thực hiện nhiệm vụ hậu phương lớn đối với tiền tuyến miền Nam.','SGK12:chien-tranh-pha-hoai-mien-bac-lan-thu-nhat','2026-06-30 00:27:15'),(60881,'chien-thang-van-tuong',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Thực hiện chiến lược “Chiến tranh cục bộ”, quân Mỹ vừa mới vào miền Nam đã cho mở ngay cuộc hành quân “tìm diệt” vào căn cứ của Quân Giải phóng ở Vạn Tường (Quảng Ngãi). Với ý chí “Quyết chiến quyết thắng giặc Mỹ xâm lược, quân dân miền Nam đã anh dũng chiến đấu và giành thắng lợi ở Vạn Tường (18 – 8 – 1965), mở ra khả năng đánh thắng Mỹ trong chiến lược “Chiến tranh cục bộ” về quân sự.','SGK12:chien-thang-van-tuong','2026-06-30 00:27:15'),(60882,'hoi-nghi-pa-ri-ve-viet-nam',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Trên bàn đàm phán tại Hội nghị Pa-ri, đại diện Chính phủ Việt Nam Dân chủ Cộng hoà và Chính phủ Cách mạng lâm thời Cộng hoà miền Nam Việt Nam lần lượt đưa ra các phương án yêu cầu Mỹ phải chấm dứt chiến tranh, lập lại hoà bình ở Việt Nam.','SGK12:hoi-nghi-pa-ri-ve-viet-nam','2026-06-30 00:27:15'),(60883,'tong-tien-cong-va-noi-day-xuan-mau-than-1968',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Bước vào đầu năm 1968 (Xuân Mậu Thân), quân dân ta mở cuộc Tổng tiến công và nổi dậy trên toàn miền Nam, trọng tâm là ở các đô thị. Cuộc Tổng tiến công và nổi dậy đã mở ra bước ngoặt của cuộc kháng chiến chống Mỹ, cứu nước: làm lung lay ý chí xâm lược của Mỹ, buộc Mỹ phải “phi Mỹ hoa chiến tranh xâm lược (tức thừa nhận thất bại của “Chiến tranh cục bộ), chấm dứt không điều kiện chiến tranh phá hoại miền Bắc, chấp nhận đàm phán ở Pa-ri để bàn về chấm dứt chiến tranh.','SGK12:tong-tien-cong-va-noi-day-xuan-mau-than-1968','2026-06-30 00:27:15'),(60884,'thanh-lap-chinh-phu-cach-mang-lam-thoi-cong-hoa-mien-nam-viet-nam',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Ngày 6-6-1969, Chính phủ cách mạng lâm thời Cộng hoà miền Nam Việt nam ra đời. Đây là chính phủ hợp phát của nhân dân miền Nam.','SGK12:thanh-lap-chinh-phu-cach-mang-lam-thoi-cong-hoa-mien-nam-viet-nam','2026-06-30 00:27:15'),(60885,'dap-tan-cuoc-hanh-quan-xam-luoc-vao-cam-pu-chia-1970',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Từ ngày 30 – 4 đến ngày 30-6-1970, với sự hỗ trợ của quân Cam-pu-chia, quân đội Việt Nam đã đập tan cuộc hành quân xâm lược của 10 vạn quân Mỹ và quân đội Sài Gòn.','SGK12:dap-tan-cuoc-hanh-quan-xam-luoc-vao-cam-pu-chia-1970','2026-06-30 00:27:15'),(60886,'hoi-nghi-cap-cao-ba-nuoc-viet-nam-lao-cam-pu-chia',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Tháng 4 – 1970, Hội nghị cấp cao ba nước Việt Nam - Lào - Cam-pu-chia được tổ chức, biểu thị quyết tâm chống Mỹ.','SGK12:hoi-nghi-cap-cao-ba-nuoc-viet-nam-lao-cam-pu-chia','2026-06-30 00:27:15'),(60887,'chien-dich-duong-9-nam-lao',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Trong hơn 1 tháng (từ tháng 2 đến tháng 3 – 1971), quân dân Việt Nam có sự phối hợp của quân đội Lào đã giành thắng lợi trong chiến dịch Đường 9 – Nam Lào, giữ vững hành lang chiến lược của cách mạng Đông Dương, trực tiếp mở ra thế tiến công mới cho cách mạng.','SGK12:chien-dich-duong-9-nam-lao','2026-06-30 00:27:15'),(60888,'philippin-chiem-dong-9-dao-truong-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Phi-líp-pin - Từ năm 1971 đến năm 1980, chiếm đóng 9 đảo thuộc quần đảo Trường Sa.','SGK11:philippin-chiem-dong-9-dao-truong-sa','2026-06-30 00:27:15'),(60889,'cuoc-tien-cong-chien-luoc-nam-1972',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Từ tháng 3 – 1972, quân đội Việt Nam mở cuộc Tiến công chiến lược vào Quảng Trị rồi phát triển rộng khắp chiến trường miền Nam, chọc thủng ba phòng tuyến của địch ở Quảng Trị, Tây Nguyên và Đông Nam Bộ. Cuộc Tiến công chiến lược năm 1972 đã buộc Mỹ phải thừa nhận thất bại của chiến lược “Việt Nam hoá chiến tranh\".','SGK12:cuoc-tien-cong-chien-luoc-nam-1972','2026-06-30 00:27:15'),(60890,'chien-tranh-pha-hoai-mien-bac-lan-thu-hai',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Với tư thế luôn sẵn sàng chiến đấu, quân dân miền Bắc đã chủ động, kịp thời giáng trả ngay từ trận đầu cuộc chiến tranh phá hoại lần thứ hai bằng không quân và hải quân của Mỹ (bắt đầu từ ngày 16-4-1972), đặc biệt đã đánh bại hoàn toàn cuộc tập kích chiến lược bằng máy bay B52 của Mỹ vào Hà Nội, Hải Phòng và một số thành phố trong 12 ngày đêm (từ 18 đến 29 – 12 – 1972).','SGK12:chien-tranh-pha-hoai-mien-bac-lan-thu-hai','2026-06-30 00:27:15'),(60891,'ki-ket-hiep-dinh-pa-ri-ve-cham-dut-chien-tranh-lap-lai-hoa-binh-o-viet-nam',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Ngày 27-1-1973, Hiệp định Pa-ri được kí kết với điều khoản quan trọng: Mỹ và các nước cam kết tôn trọng độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ Việt Nam.','SGK12:ki-ket-hiep-dinh-pa-ri-ve-cham-dut-chien-tranh-lap-lai-hoa-binh-o-viet-nam','2026-06-30 00:27:15'),(60892,'ki-ket-hiep-dinh-pa-ri-ve-cham-dut-chien-tranh-lap-lai-hoa-binh-o-viet-nam',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Thắng lợi này được coi như một trận “Điện Biên Phủ trên không”, buộc Mỹ phải trở lại bàn hội nghị và kí Hiệp định Pa-ri về chấm dứt chiến tranh, lập lại hoà bình ở Việt Nam (1973).','SGK12:ki-ket-hiep-dinh-pa-ri-ve-cham-dut-chien-tranh-lap-lai-hoa-binh-o-viet-nam','2026-06-30 00:27:15'),(60893,'hoi-nghi-ban-chap-hanh-trung-uong-dang-lan-thu-21',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Tháng 7 – 1973, Hội nghị Ban Chấp hành Trung ương Đảng lần thứ 21 nhấn mạnh: Trong bất cứ tình hình nào cũng phải tiếp tục con đường bạo lực cách mạng, phải nắm vững chiến lược tiến công, kiên quyết đấu tranh trên ba mặt trận: quân sự, chính trị, ngoại giao.','SGK12:hoi-nghi-ban-chap-hanh-trung-uong-dang-lan-thu-21','2026-06-30 00:27:15'),(60894,'quan-doi-sai-gon-that-bai-bao-ve-hoang-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Tháng 1 – 1974, quân đội Sài Gòn thất bại trong chiến đấu bảo vệ quần đảo Hoàng Sa trước cuộc tấn công của quân đội Trung Quốc.','SGK11:quan-doi-sai-gon-that-bai-bao-ve-hoang-sa','2026-06-30 00:27:15'),(60895,'trung-quoc-danh-chiem-toan-bo-hoang-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Trung Quốc - Tháng 1 – 1974: đánh chiếm toàn bộ quần đảo Hoàng Sa. Tháng 1 – 1974, quân đội Sài Gòn thất bại trong chiến đấu bảo vệ quần đảo Hoàng Sa trước cuộc tấn công của quân đội Trung Quốc.','SGK11:trung-quoc-danh-chiem-toan-bo-hoang-sa','2026-06-30 00:27:15'),(60896,'chien-dich-tay-nguyen-1975',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Chiến dịch Tây Nguyên diễn ra từ ngày 10 – 3, đến ngày 24 – 3 thì kết thúc thắng lợi.','SGK12:chien-dich-tay-nguyen-1975','2026-06-30 00:27:15'),(60897,'giai-phong-hue-va-thua-thien',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Ngày 26 – 3, thành phố Huế và toàn tỉnh Thừa Thiên được giải phóng.','SGK12:giai-phong-hue-va-thua-thien','2026-06-30 00:27:15'),(60898,'giai-phong-da-nang',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Đà Nẵng rơi vào thế cô lập và đến chiều 29 – 3 cũng được hoàn toàn giải phóng.','SGK12:giai-phong-da-nang','2026-06-30 00:27:15'),(60899,'tong-tien-cong-va-noi-day-xuan-1975',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Từ tháng 3 – 1975, quân dân miền Nam mở cuộc Tổng tiến công và nổi dậy Xuân 1975, trải qua ba chiến dịch lớn: chiến dịch Tây Nguyên, chiến dịch Huế – Đà Nẵng và chiến dịch giải phóng Sài Gòn – Gia Định (Chiến dịch Hồ Chí Minh).','SGK12:tong-tien-cong-va-noi-day-xuan-1975','2026-06-30 00:27:15'),(60900,'quan-giai-phong-mien-nam-viet-nam-tiep-quan-truong-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Từ ngày 13 đến ngày 28-4-1975, Quân giải phóng miền Nam Việt Nam đã tiếp quản các đảo và triển khai lực lượng thực thi chủ quyền đối với quần đảo Trường Sa.','SGK11:quan-giai-phong-mien-nam-viet-nam-tiep-quan-truong-sa','2026-06-30 00:27:15'),(60901,'chien-dich-giai-phong-sai-gon-gia-dinh-chien-dich-ho-chi-minh',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Sau khi tiêu diệt căn cứ phòng thủ Xuân Lộc và Phan Rang, 5 giờ chiều ngày 26 – 4, năm cánh quân cùng lúc tiến vào trung tâm thành phố, đánh chiếm các cơ quan đầu não của chính quyền Sài Gòn. 11 giờ 30 phút cùng ngày, lá cờ cách mạng tung bay trên nóc Dinh Độc Lập, báo hiệu sự toàn thắng của Chiến dịch Hồ Chí Minh lịch sử.','SGK12:chien-dich-giai-phong-sai-gon-gia-dinh-chien-dich-ho-chi-minh','2026-06-30 00:27:15'),(60902,'mit-tinh-chao-mung-uy-ban-quan-quan-sai-gon-1975',10,'KNTT',NULL,'Bai 14',NULL,NULL,'Nhân dân Thành phố Sài Gòn mít tinh chào mừng Uỷ ban Quân quản thành phố ra mắt ngày 7 – 5 – 1975.','SGK10:mit-tinh-chao-mung-uy-ban-quan-quan-sai-gon-1975','2026-06-30 00:27:15'),(60903,'quoc-hoi-khoa-vi-doi-ten-sai-gon-thanh-thanh-pho-ho-chi-minh',12,'KNTT',NULL,'Bai 17',NULL,NULL,'Sau khi đất nước thống nhất, năm 1976, Quốc hội khoá VI đã quyết định đổi tên thành phố Sài Gòn thành Thành phố Hồ Chí Minh. Trong nghị quyết về việc đặt tên, Quốc hội đã nêu rõ: “Xét rằng, nhân dân Thành phố Sài Gòn – Gia Định luôn luôn tỏ lòng kính yêu vô hạn đối với Chủ tịch Hồ Chí Minh và tha thiết với việc thành phố mang tên Người”.','SGK12:quoc-hoi-khoa-vi-doi-ten-sai-gon-thanh-thanh-pho-ho-chi-minh','2026-06-30 00:27:15'),(60904,'viet-nam-ban-hanh-tuyen-bo-vung-bien-them-luc-dia',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Ban hành văn bản pháp luật khẳng định chủ quyền: Tuyên bố về các vùng biển và thềm lục địa Việt Nam (5 – 1977).','SGK11:viet-nam-ban-hanh-tuyen-bo-vung-bien-them-luc-dia','2026-06-30 00:27:15'),(60905,'viet-nam-thanh-vien-lien-hop-quoc',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Ngày 20-9-1977, Việt Nam trở thành thành viên chính thức của Liên hợp quốc.','SGK12:viet-nam-thanh-vien-lien-hop-quoc','2026-06-30 00:27:16'),(60906,'philippin-ban-hanh-sac-lenh-1596-tuyen-bo-chu-quyen-truong-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Phi-líp-pin - Năm 1978, ban hành Sắc lệnh 1596 tuyên bố chủ quyền đối với hầu hết các đảo thuộc quần đảo Trường Sa.','SGK11:philippin-ban-hanh-sac-lenh-1596-tuyen-bo-chu-quyen-truong-sa','2026-06-30 00:27:16'),(60907,'viet-nam-gia-nhap-sev',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Năm 1978, Việt Nam gia nhập Hội đồng tương trợ kinh tế (SEV).','SGK12:viet-nam-gia-nhap-sev','2026-06-30 00:27:16'),(60908,'go-ro-bat-co-pham-tuan-bay-vu-tru',12,'KNTT',NULL,'Bai 14',NULL,NULL,'V. Go-rơ-bát cô (Liên Xô) và Phạm Tuân (Việt Nam) cùng bay vào vũ trụ (1980).','SGK12:go-ro-bat-co-pham-tuan-bay-vu-tru','2026-06-30 00:27:16'),(60909,'thanh-lap-huyen-hoang-sa-va-huyen-truong-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Năm 1982, huyện Hoàng Sa thuộc tỉnh Quảng Nam - Đà Nẵng (từ năm 1997 thuộc thành phố Đà Nẵng) và huyện Trường Sa thuộc tỉnh Khánh Hoà được thành lập. Trong huyện Trường Sa có các đơn vị hành chính nhỏ hơn như: thị trấn Trường Sa (bao gồm đảo Trường Sa Lớn và phụ cận); xã Song Tử Tây (đảo Song Tử Tây và phụ cận); xã Sinh Tồn (đảo Sinh Tồn và phụ cận).','SGK11:thanh-lap-huyen-hoang-sa-va-huyen-truong-sa','2026-06-30 00:27:16'),(60910,'bru-nay-tuyen-bo-ranh-gioi-them-luc-dia',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Bru-nây - Chưa chiếm giữ đảo nào nhưng đưa yêu sách chủ quyền lãnh thổ đối với quần đảo Trường Sa trong tuyên bố về ranh giới thềm lục địa 200 hải lí năm 1983 và về vùng đặc quyền kinh tế năm 1984.','SGK11:bru-nay-tuyen-bo-ranh-gioi-them-luc-dia','2026-06-30 00:27:16'),(60911,'bru-nay-tuyen-bo-vung-dac-quyen-kinh-te',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Bru-nây - Chưa chiếm giữ đảo nào nhưng đưa yêu sách chủ quyền lãnh thổ đối với quần đảo Trường Sa trong tuyên bố về ranh giới thềm lục địa 200 hải lí năm 1983 và về vùng đặc quyền kinh tế năm 1984.','SGK11:bru-nay-tuyen-bo-vung-dac-quyen-kinh-te','2026-06-30 00:27:16'),(60912,'dai-hoi-dai-bieu-toan-quoc-lan-thu-vi-cua-dang-cong-san-viet-nam',12,'KNTT',NULL,'Bai 10',NULL,NULL,'Đại hội đại biểu toàn quốc lần thứ VI của Đảng Cộng sản Việt Nam diễn ra vào tháng 12 năm 1986.','SGK12:dai-hoi-dai-bieu-toan-quoc-lan-thu-vi-cua-dang-cong-san-viet-nam','2026-06-30 00:27:16'),(60913,'cong-cuoc-doi-moi-o-viet-nam',12,'KNTT',NULL,'Bai 11',NULL,NULL,'Công cuộc đổi mới toàn diện đất nước từ năm 1986 đến nay đã đưa Việt Nam ra khỏi tình trạng khủng hoảng kinh tế - xã hội, đẩy mạnh công nghiệp hoá, hiện đại hoá cũng như hội nhập quốc tế mạnh mẽ, sâu rộng.','SGK12:cong-cuoc-doi-moi-o-viet-nam','2026-06-30 00:27:16'),(60914,'cong-cuoc-doi-moi-o-viet-nam',11,'KNTT',NULL,'Bai 4',NULL,NULL,'Công cuộc đổi mới được thực hiện từ năm 1986 và thu được những thành tựu to lớn bằng việc chuyển đổi thành công nền kinh tế kế hoạch hoá tập trung quan liêu, bao cấp sang nền kinh tế thị trường định hướng xã hội chủ nghĩa. Nền kinh tế phát triển liên tục với tốc độ tương đối cao (trung bình 7% mỗi năm), quy mô GDP mở rộng (đạt 342,7 tỉ USD năm 2020), thu nhập bình quân đầu người tăng khoảng 17 lần.','SGK11:cong-cuoc-doi-moi-o-viet-nam','2026-06-30 00:27:16'),(60915,'cong-cuoc-doi-moi-o-viet-nam',12,'KNTT',NULL,'Bai 3',NULL,NULL,'Từ năm 1986, Việt Nam bắt đầu công cuộc Đổi mới, xây dựng nền kinh tế thị trường định hướng xã hội chủ nghĩa, được xếp trong nhóm những nền kinh tế có tốc độ tăng trường cao nhất thế giới, đồng thời gắn kết phát triển kinh tế với tiến bộ và công bằng xã hội.','SGK12:cong-cuoc-doi-moi-o-viet-nam','2026-06-30 00:27:16'),(60916,'trung-quoc-danh-chiem-dao-gac-ma-len-dao-chu-thap-va-mot-so-dao-khac-truong-sa',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Trung Quốc - Từ năm 1987 đến tháng 4 – 1988: đánh chiếm đảo Gạc Ma, Len Đao, Chữ Thập và chiếm đóng trái phép một số đảo khác trên quần đảo Trường Sa.','SGK11:trung-quoc-danh-chiem-dao-gac-ma-len-dao-chu-thap-va-mot-so-dao-khac-truong-sa','2026-06-30 00:27:16'),(60917,'chien-si-hai-quan-nhan-dan-viet-nam-hi-sinh-bao-ve-gac-ma-co-lin-len-dao',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Tháng 3 – 1988, nhiều chiến sĩ hải quân Nhân dân Việt Nam đã hi sinh anh dũng khi chiến đấu bảo vệ chủ quyền tại các đảo Gạc Ma, Cô Lin, Len Đao trước cuộc tấn công của quân đội Trung Quốc.','SGK11:chien-si-hai-quan-nhan-dan-viet-nam-hi-sinh-bao-ve-gac-ma-co-lin-len-dao','2026-06-30 00:27:16'),(60918,'bai-bo-che-do-tem-phieu-o-viet-nam',12,'KNTT',NULL,'Bai 11',NULL,NULL,'Ngày 1-4-1989, chế độ tem phiếu hoàn toàn được bãi bỏ ở Việt Nam. Đây là mốc kết thúc việc phát hành tem phiếu dùng để mua các mặt hàng thiết yếu của đời sống do Nhà nước phân phối.','SGK12:bai-bo-che-do-tem-phieu-o-viet-nam','2026-06-30 00:27:16'),(60919,'dai-hoi-dai-bieu-toan-quoc-lan-thu-vii-cua-dang-cong-san-viet-nam',12,'KNTT',NULL,'Bai 10',NULL,NULL,'Đại hội đại biểu toàn quốc lần thứ VII của Đảng Cộng sản Việt Nam diễn ra vào năm 1991.','SGK12:dai-hoi-dai-bieu-toan-quoc-lan-thu-vii-cua-dang-cong-san-viet-nam','2026-06-30 00:27:16'),(60920,'viet-nam-binh-thuong-hoa-quan-he-trung-quoc',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Sau khi Hiệp định Pa-ri về Cam-pu-chia được kí kết (10 1991), Việt Nam đã bình thường hoá quan hệ với Trung Quốc (1991).','SGK12:viet-nam-binh-thuong-hoa-quan-he-trung-quoc','2026-06-30 00:27:16'),(60921,'xay-dung-va-dong-dien-duong-day-500kv-bac-nam-mach-1',12,'KNTT',NULL,'Bai 11',NULL,NULL,'Công trình đường dây 500 kV Bắc - Nam (mạch 1) được khởi công thiết kế và xây dựng chỉ trong hai năm (1992 - 1993) từ khi khởi công đến khi đóng điện thành công.','SGK12:xay-dung-va-dong-dien-duong-day-500kv-bac-nam-mach-1','2026-06-30 00:27:16'),(60922,'dai-loan-chiem-bai-can-ran-san-ho-ban-than',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Đài Loan - Năm 1995, chiếm bãi cạn rạn san hô Bàn Than.','SGK11:dai-loan-chiem-bai-can-ran-san-ho-ban-than','2026-06-30 00:27:16'),(60923,'trung-quoc-danh-chiem-da-vanh-khan',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Trung Quốc - Năm 1995: đánh chiếm đá Vành Khăn nằm về phía đông nam quần đảo Trường Sa.','SGK11:trung-quoc-danh-chiem-da-vanh-khan','2026-06-30 00:27:16'),(60924,'viet-nam-binh-thuong-hoa-quan-he-my',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Việt Nam đã bình thường hoá quan hệ với Mỹ (1995).','SGK12:viet-nam-binh-thuong-hoa-quan-he-my','2026-06-30 00:27:16'),(60925,'viet-nam-gia-nhap-asean',12,'KNTT',NULL,'Bai 4',NULL,NULL,'Việt Nam gia nhập ASEAN (1995).','SGK12:viet-nam-gia-nhap-asean','2026-06-30 00:27:16'),(60926,'viet-nam-gia-nhap-asean',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Việt Nam gia nhập ASEAN (1995).','SGK12:viet-nam-gia-nhap-asean','2026-06-30 00:27:16'),(60927,'dai-hoi-dai-bieu-toan-quoc-lan-thu-viii-cua-dang-cong-san-viet-nam',12,'KNTT',NULL,'Bai 10',NULL,NULL,'Đại hội đại biểu toàn quốc lần thứ VIII của Đảng Cộng sản Việt Nam diễn ra vào năm 1996.','SGK12:dai-hoi-dai-bieu-toan-quoc-lan-thu-viii-cua-dang-cong-san-viet-nam','2026-06-30 00:27:16'),(60928,'cam-pu-chia-gia-nhap-asean',12,'KNTT',NULL,'Bai 4',NULL,NULL,'Năm 1999, Cam-pu-chia gia nhập ASEAN, trở thành thành viên thứ 10.','SGK12:cam-pu-chia-gia-nhap-asean','2026-06-30 00:27:16'),(60929,'ki-tuyen-bo-ve-ung-xu-cua-cac-ben-o-bien-dong-doc',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Tuyên bố về Cách ứng xử của các bên ở Biển Đông (DOC) được các nước ASEAN và Trung Quốc kí ngày 4-11-2002 tại Thủ đô Phnôm Pênh, Cam-pu-chia.','SGK11:ki-tuyen-bo-ve-ung-xu-cua-cac-ben-o-bien-dong-doc','2026-06-30 00:27:16'),(60930,'bo-chinh-tri-ban-hanh-chi-thi-06-ct-tw-ve-cuoc-van-dong-hoc-tap-va-lam-theo-tam-guong-dao-duc-ho-chi-minh',12,'KNTT',NULL,'Bai 17',NULL,NULL,'Ngày 7-11-2006, Bộ Chính trị Đảng Cộng sản Việt Nam khoá X ban hành Chỉ thị 06-CT/TW về tổ chức Cuộc vận động “Học tập và làm theo tấm gương đạo đức Hồ Chí Minh”.','SGK12:bo-chinh-tri-ban-hanh-chi-thi-06-ct-tw-ve-cuoc-van-dong-hoc-tap-va-lam-theo-tam-guong-dao-duc-ho-chi-minh','2026-06-30 00:27:16'),(60931,'dai-hoi-dai-bieu-toan-quoc-lan-thu-x-cua-dang-cong-san-viet-nam',12,'KNTT',NULL,'Bai 10',NULL,NULL,'Đại hội đại biểu toàn quốc lần thứ X của Đảng Cộng sản Việt Nam diễn ra vào năm 2006.','SGK12:dai-hoi-dai-bieu-toan-quoc-lan-thu-x-cua-dang-cong-san-viet-nam','2026-06-30 00:27:16'),(60932,'viet-nam-thong-qua-luat-bien-viet-nam',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Thông qua Luật Biển Việt Nam năm 2012.','SGK11:viet-nam-thong-qua-luat-bien-viet-nam','2026-06-30 00:27:16'),(60933,'hien-phap-cong-hoa-xa-hoi-chu-nghia-viet-nam-2013',10,'KNTT',NULL,'Bai 14',NULL,NULL,'Điều 5, Hiến pháp nước Cộng hoà xã hội chủ nghĩa Việt Nam, năm 2013, có đoạn: “Nước Cộng hoà xã hội chủ nghĩa Việt Nam là quốc gia thống nhất của các dân tộc củng sinh sống trên đất nước Việt Nam. Các dân tộc bình đẳng, đoàn kết, tôn trọng và giúp nhau cùng phát triển; nghiêm cấm mọi hành vi kì thị, chia rẽ dân tộc”.','SGK10:hien-phap-cong-hoa-xa-hoi-chu-nghia-viet-nam-2013','2026-06-30 00:27:16'),(60934,'bo-chinh-tri-ban-hanh-chi-thi-05-ct-tw-ve-day-manh-hoc-tap-va-lam-theo-tu-tuong-dao-duc-phong-cach-ho-chi-minh',12,'KNTT',NULL,'Bai 17',NULL,NULL,'Ngày 15 – 5 – 2016, Bộ Chính trị ban hành Chỉ thị 05-CT/TW về “đẩy mạnh học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh. Đến nay, cuộc vận động đã và đang được lan toả đến các thế hệ cán bộ đảng viên và quần chúng nhân dân.','SGK12:bo-chinh-tri-ban-hanh-chi-thi-05-ct-tw-ve-day-manh-hoc-tap-va-lam-theo-tu-tuong-dao-duc-phong-cach-ho-chi-minh','2026-06-30 00:27:17'),(60935,'phe-duyet-chien-luoc-phat-trien-cong-nghiep-van-hoa-viet-nam',10,'KNTT',NULL,'Bai 4',NULL,NULL,'Chiến lược phát triển các ngành công nghiệp văn hoá đến năm 2020, tầm nhìn đến năm 2030 do Thủ tướng Chính phủ Việt Nam phê duyệt ngày 8 – 9 – 2016.','SGK10:phe-duyet-chien-luoc-phat-trien-cong-nghiep-van-hoa-viet-nam','2026-06-30 00:27:17'),(60936,'ro-bot-xophia-duoc-cap-quyen-cong-dan',10,'KNTT',NULL,'Bai 8',NULL,NULL,'Rô-bốt Xô-phi-a, tích hợp trí tuệ nhân tạo, đã được Chính phủ A-rập Xê-út cấp quyền Công dân vào ngày 25 - 10 - 2017.','SGK10:ro-bot-xophia-duoc-cap-quyen-cong-dan','2026-06-30 00:27:17'),(60937,'ban-hanh-nghi-quyet-36-nq-tw-ve-chien-luoc-phat-trien-kinh-te-bien',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Nghị quyết 36-NQ/TW của Ban Chấp hành Trung ương Đảng Cộng sản Việt Nam ngày 22 – 10 – 2018 về Chiến lược phát triển bền vững kinh tế biển Việt Nam đến năm 2030, tầm nhìn đến năm 2045.','SGK11:ban-hanh-nghi-quyet-36-nq-tw-ve-chien-luoc-phat-trien-kinh-te-bien','2026-06-30 00:27:17'),(60938,'nhan-dan-ung-ho-mien-trung-bao-so-9-2020',10,'KNTT',NULL,'Bai 14',NULL,NULL,'Nhân dân các dân tộc chung tay ủng hộ các tỉnh miền Trung bị thiệt hại sau cơn bão số 9 (tháng 10 – 2020).','SGK10:nhan-dan-ung-ho-mien-trung-bao-so-9-2020','2026-06-30 00:27:17'),(60939,'hoi-nghi-cap-cao-asean-37-ha-noi',12,'KNTT',NULL,'Bai 5',NULL,NULL,'Hội nghị Cấp cao ASEAN lần thứ 37 tại Hà Nội (2020) đã nhất trí thông qua việc xây dựng Tầm nhìn Cộng đồng ASEAN sau năm 2025.','SGK12:hoi-nghi-cap-cao-asean-37-ha-noi','2026-06-30 00:27:17'),(60940,'doan-si-quan-viet-nam-tham-gia-luc-luong-gin-giu-hoa-binh-lien-hop-quoc-tai-nam-xu-dang',12,'KNTT',NULL,'Bai 1',NULL,NULL,'Đoàn sĩ quan Việt Nam tham gia Lực lượng gìn giữ hoà bình Liên hợp quốc trong lễ xuất quân lên đường làm nhiệm vụ tại Nam Xu-đăng (2021).','SGK12:doan-si-quan-viet-nam-tham-gia-luc-luong-gin-giu-hoa-binh-lien-hop-quoc-tai-nam-xu-dang','2026-06-30 00:27:17'),(60941,'quan-he-viet-nam-my-doi-tac-chien-luoc-toan-dien',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Chuyến thăm của Tổng thống Mỹ đến Việt Nam đánh dấu quan hệ hợp tác giữa hai nước lên tầm đối tác chiến lược toàn diện (2023).','SGK12:quan-he-viet-nam-my-doi-tac-chien-luoc-toan-dien','2026-06-30 00:27:17'),(60942,'cac-chien-dich-tien-cong-quan-doi-viet-nam-1950-1953',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Quân đội Việt Nam liên tiếp mở những chiến dịch tiến công, tiếp tục giữ vững quyền chủ động trên chiến trường như: ba chiến dịch là Trần Hưng Đạo (Trung du), Hoàng Hoa Thám (Đường số 18), Quang Trung (Hà Nam Ninh) (từ cuối năm 1950 đến giữa năm 1951); sau đó là chiến dịch Hoà Bình (đông - xuân 1951-1952), chiến dịch Tây Bắc (thu - đông năm 1952), chiến dịch Thượng Lào (xuân – hè năm 1953).','SGK12:cac-chien-dich-tien-cong-quan-doi-viet-nam-1950-1953','2026-06-30 00:27:17'),(60943,'cac-chien-thang-quan-su-1964-1965',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Trong những năm 1964 – 1965, quân ta tiến công và thắng lợi ở Bình Giã (Bà Rịa – Vũng Tàu), An Lão (Bình Định), Ba Gia (Quảng Ngãi), Đồng Xoài (Bình Phước), làm phá sản hoàn toàn chiến lược “Chiến tranh đặc biệt” của Mỹ.','SGK12:cac-chien-thang-quan-su-1964-1965','2026-06-30 00:27:17'),(60944,'cai-cach-le-thanh-tong',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Cuộc cải cách của vua Lê Thánh Tông được tiến hành trong khoảng 30 năm trị vì đất nước, với nhiều chính sách, biện pháp cải cách có tác dụng thúc đẩy sự phát triển mọi mặt của đất nước.','SGK10:cai-cach-le-thanh-tong','2026-06-30 00:27:17'),(60945,'cai-cach-le-thanh-tong',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Cuộc cải cách của vua Lê Thánh Tông được tiến hành trong khoảng 30 năm trị vì đất nước, với nhiều chính sách, biện pháp cải cách có tác dụng thúc đẩy sự phát triển mọi mặt của đất nước.','SGK11:cai-cach-le-thanh-tong','2026-06-30 00:27:17'),(60946,'cai-cach-le-thanh-tong',11,'KNTT',NULL,'Bai 13',NULL,NULL,'Cuộc cải cách của vua Lê Thánh Tông được tiến hành trong khoảng 30 năm trị vì đất nước, với nhiều chính sách, biện pháp cải cách có tác dụng thúc đẩy sự phát triển mọi mặt của đất nước.','SGK11:cai-cach-le-thanh-tong','2026-06-30 00:27:17'),(60947,'cai-cach-ruong-dat-mien-bac',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Nhân dân miền Bắc hoàn thành cải cách ruộng đất, khôi phục kinh tế, hàn gắn vết thương chiến tranh và cải tạo quan hệ sản xuất, bước đầu phát triển kinh tế – xã hội.','SGK12:cai-cach-ruong-dat-mien-bac','2026-06-30 00:27:17'),(60948,'cai-cach-tran-thu-do',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Cải cách của Trần Thủ Độ diễn ra vào thế kỉ XIII.','SGK11:cai-cach-tran-thu-do','2026-06-30 00:27:17'),(60949,'cai-cach-trinh-cuong-dang-ngoai',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Cải cách của Trịnh Cương ở Đàng Ngoài diễn ra vào thế kỉ XVIII.','SGK11:cai-cach-trinh-cuong-dang-ngoai','2026-06-30 00:27:17'),(60950,'chien-luoc-vua-danh-vua-dam-va-van-dong-quoc-te-cong-nhan-mat-tran-dan-toc-giai-phong-mien-nam-viet-nam',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Cùng với những thắng lợi quân sự, Chính phủ Việt Nam Dân chủ Cộng hoà chủ động kết hợp “vừa đánh, vừa đàm, cung cấp tư liệu về cuộc chiến tranh phi nghĩa mà Mỹ tiến hành ở miền Nam Việt Nam, tranh thủ sự ủng hộ của nhân dân tiến bộ trên thế giới, đòi Mỹ chấm dứt chiến tranh; đồng thời, tích cực vận động quốc tế công nhận Mặt trận Dân tộc giải phóng miền Nam Việt Nam.','SGK12:chien-luoc-vua-danh-vua-dam-va-van-dong-quoc-te-cong-nhan-mat-tran-dan-toc-giai-phong-mien-nam-viet-nam','2026-06-30 00:27:17'),(60951,'chien-thang-duong-14-phuoc-long',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Cuối năm 1974, đầu năm 1975, quân dân miền Nam đã giành thắng lợi trong chiến dịch Đường 14 Phước Long. Chiến thắng này cùng những phản ứng của Mỹ và chính quyền Sài Gòn sau đó cho thấy rõ về sự lớn mạnh, khả năng thắng lớn của quân ta, sự suy yếu và bất lực của quân đội Sài Gòn, về khả năng can thiệp bằng quân sự trở lại của Mỹ là rất hạn chế.','SGK12:chien-thang-duong-14-phuoc-long','2026-06-30 00:27:17'),(60952,'chinh-quyen-phap-cai-cach-huong-chinh',11,'KNTT',NULL,'Bai 9',NULL,NULL,'Thời Pháp thuộc: Chính quyền thực dân Pháp thực hiện nhiều biện pháp cải cách nhằm tăng cường quản lí hành chính (như chính sách \"cải lương hương chính\") nhưng không thành công.','SGK11:chinh-quyen-phap-cai-cach-huong-chinh','2026-06-30 00:27:17'),(60953,'chu-nom-su-dung-rong-rai',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Trên cơ sở chữ Hán, chữ Nôm được người Việt sáng tạo và được sử dụng rộng rãi từ thế kỉ XIII.','SGK10:chu-nom-su-dung-rong-rai','2026-06-30 00:27:17'),(60954,'chu-quoc-ngu-xuat-hien',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Từ đầu thế kỉ XVI, cùng với sự du nhập của Công giáo, chữ Quốc ngữ đã xuất hiện và dần được hoàn thiện.','SGK10:chu-quoc-ngu-xuat-hien','2026-06-30 00:27:17'),(60955,'cuoc-tien-cong-chien-luoc-dong-xuan-1953-1954',12,'KNTT',NULL,'Bai 7',NULL,NULL,'Cuộc Tiến công chiến lược Đông - Xuân 1953 - 1954 của quân dân Việt Nam đã làm phá sản bước đầu Kế hoạch Na-va, đồng thời chuẩn bị về vật chất và tinh thần để mở chiến dịch Điện Biên Phủ.','SGK12:cuoc-tien-cong-chien-luoc-dong-xuan-1953-1954','2026-06-30 00:27:17'),(60956,'dau-tranh-chong-phong-kien-phuong-bac',10,'KNTT',NULL,'Bai 14',NULL,NULL,'Khối đại đoàn kết dân tộc ở Việt Nam ngày càng được củng cố qua cuộc đấu tranh bền bỉ trong hơn 1 000 năm chống lại sự thống trị, đồng hoá của các triều đại phong kiến phương Bắc, giành lại độc lập dân tộc.','SGK10:dau-tranh-chong-phong-kien-phuong-bac','2026-06-30 00:27:17'),(60957,'dinh-tien-le-dong-do-hoa-lu',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Triều Định và Tiền Lê đóng đô ở Hoa Lư (Ninh Bình); kinh tế và văn hoá dân tộc bước đầu phát triển.','SGK10:dinh-tien-le-dong-do-hoa-lu','2026-06-30 00:27:17'),(60958,'doi-do-ly-cong-uan',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Công cuộc dời đô của Lý Công Uẩn diễn ra vào thế kỉ XI.','SGK11:doi-do-ly-cong-uan','2026-06-30 00:27:17'),(60959,'doi-moi-dao-duy-tu-dang-trong',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Sự nghiệp đổi mới của Đào Duy Từ ở Đàng Trong diễn ra vào thế kỉ XVI.','SGK11:doi-moi-dao-duy-tu-dang-trong','2026-06-30 00:27:17'),(60960,'giai-doan-cuoi-chien-tranh-the-gioi-thu-hai',12,'KNTT',NULL,'Bai 1',NULL,NULL,'Giai đoạn cuối của Chiến tranh thế giới thứ hai, khi phe Đồng minh giành được những thắng lợi quan trọng trên các mặt trận.','SGK12:giai-doan-cuoi-chien-tranh-the-gioi-thu-hai','2026-06-30 00:27:17'),(60961,'giai-doan-cuoi-chien-tranh-the-gioi-thu-hai',12,'KNTT',NULL,'Bai 2',NULL,NULL,'Giai đoạn cuối của Chiến tranh thế giới thứ hai, khi phe Đồng minh giành được những thắng lợi quan trọng trên các mặt trận.','SGK12:giai-doan-cuoi-chien-tranh-the-gioi-thu-hai','2026-06-30 00:27:17'),(60962,'giai-doan-cuoi-chien-tranh-the-gioi-thu-hai',12,'KNTT',NULL,'Bai 6',NULL,NULL,'Giai đoạn cuối của Chiến tranh thế giới thứ hai, khi phe Đồng minh giành được những thắng lợi quan trọng trên các mặt trận.','SGK12:giai-doan-cuoi-chien-tranh-the-gioi-thu-hai','2026-06-30 00:27:18'),(60963,'giai-doan-day-manh-cong-nghiep-hoa-hien-dai-hoa-hoi-nhap-kinh-te-quoc-te-1996-2006',12,'KNTT',NULL,'Bai 10',NULL,NULL,'Giai đoạn đẩy mạnh công nghiệp hoá, hiện đại hoá, hội nhập kinh tế quốc tế của Việt Nam diễn ra từ năm 1996 đến năm 2006.','SGK12:giai-doan-day-manh-cong-nghiep-hoa-hien-dai-hoa-hoi-nhap-kinh-te-quoc-te-1996-2006','2026-06-30 00:27:18'),(60964,'giai-doan-khang-chien-chong-my-1954-1960',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Trong giai đoạn 1954-1960, miền Bắc hoàn thành cải cách ruộng đất, khôi phục kinh tế và cải tạo quan hệ sản xuất. Miền Nam đấu tranh chống Mỹ – chính quyền Ngô Đình Diệm, đòi thi hành Hiệp định Giơ-ne-vơ, bảo vệ hoà bình, giữ gìn và phát triển lực lượng cách mạng, tiến tới phong trào Đồng khởi.','SGK12:giai-doan-khang-chien-chong-my-1954-1960','2026-06-30 00:27:18'),(60965,'giai-doan-khang-chien-chong-my-1961-1965',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Trong giai đoạn 1961-1965, miền Bắc tiến hành kế hoạch Nhà nước 5 năm lần thứ nhất với trọng tâm xây dựng chủ nghĩa xã hội và làm nghĩa vụ hậu phương lớn. Miền Nam đẩy mạnh chiến đấu chống chiến lược “Chiến tranh đặc biệt” (1961-1965) do Mỹ và chính quyền Sài Gòn triển khai, giành nhiều thắng lợi quân sự tiêu biểu.','SGK12:giai-doan-khang-chien-chong-my-1961-1965','2026-06-30 00:27:18'),(60966,'giai-doan-khang-chien-chong-my-1965-1968',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Sau thất bại của chiến lược “Chiến tranh đặc biệt”, Mỹ chuyển sang thực hiện chiến lược “Chiến tranh cục bộ” (1965 – 1968) ở miền Nam và mở rộng chiến tranh phá hoại miền Bắc. Nhân dân hai miền Nam – Bắc trực tiếp chiến đấu chống Mỹ, với các thắng lợi tiêu biểu như Vạn Tường, đập tan phản công mùa khô và cuộc Tổng tiến công và nổi dậy Xuân Mậu Thân 1968.','SGK12:giai-doan-khang-chien-chong-my-1965-1968','2026-06-30 00:27:18'),(60967,'giai-doan-khang-chien-chong-my-1969-1973',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Sau thất bại của chiến lược “Chiến tranh cục bộ”, Mỹ chuyển sang chiến lược “Việt Nam hoá chiến tranh” (1969 – 1973) ở miền Nam và mở rộng chiến tranh phá hoại miền Bắc lần thứ hai. Quân dân hai miền đã giành được nhiều thắng lợi chiến lược, đỉnh cao là chiến thắng \'Điện Biên Phủ trên không\' buộc Mỹ phải kí Hiệp định Pa-ri.','SGK12:giai-doan-khang-chien-chong-my-1969-1973','2026-06-30 00:27:18'),(60968,'giai-doan-khang-chien-chong-my-1973-1975',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Sau khi Hiệp định Pa-ri năm 1973 được kí kết, miền Bắc khắc phục hậu quả chiến tranh, khôi phục và phát triển kinh tế – xã hội, ra sức chi viện cho miền Nam. Miền Nam kiên quyết đánh trả địch, chủ động mở những cuộc tiến công, đỉnh cao là cuộc Tổng tiến công và nổi dậy Xuân 1975, giải phóng hoàn toàn miền Nam.','SGK12:giai-doan-khang-chien-chong-my-1973-1975','2026-06-30 00:27:18'),(60969,'giai-doan-khoi-dau-cong-cuoc-doi-moi-1986-1995',12,'KNTT',NULL,'Bai 10',NULL,NULL,'Giai đoạn khởi đầu công cuộc Đổi mới ở Việt Nam diễn ra từ năm 1986 đến năm 1995.','SGK12:giai-doan-khoi-dau-cong-cuoc-doi-moi-1986-1995','2026-06-30 00:27:18'),(60970,'giai-doan-tiep-tuc-day-manh-cong-nghiep-hoa-hien-dai-hoa-hoi-nhap-quoc-te-sau-rong-2006-nay',12,'KNTT',NULL,'Bai 10',NULL,NULL,'Giai đoạn tiếp tục đẩy mạnh công nghiệp hoá, hiện đại hoá, hội nhập quốc tế sâu rộng của Việt Nam diễn ra từ năm 2006 đến nay.','SGK12:giai-doan-tiep-tuc-day-manh-cong-nghiep-hoa-hien-dai-hoa-hoi-nhap-quoc-te-sau-rong-2006-nay','2026-06-30 00:27:18'),(60971,'hinh-thanh-khoi-dai-doan-ket-van-lang-au-lac',10,'KNTT',NULL,'Bai 14',NULL,NULL,'Từ yêu cầu liên kết để trị thuỷ, làm thuỷ lợi phục vụ sản xuất nông nghiệp và tập hợp lực lượng đấu tranh chống giặc ngoại xâm, khối đoàn kết dân tộc ở Việt Nam đã hình thành từ rất sớm – từ thời dựng nước Văn Lang – Âu Lạc.','SGK10:hinh-thanh-khoi-dai-doan-ket-van-lang-au-lac','2026-06-30 00:27:18'),(60972,'hinh-thanh-phat-trien-van-minh-cham-pa',10,'KNTT',NULL,'Bai 11',NULL,NULL,'Nền văn minh Chăm-pa hình thành, tồn tại và phát triển (từ thế kỉ II đến thế kỉ XV) trên địa bàn các tỉnh miền Trung và một phần cao nguyên Trường Sơn Việt Nam ngày nay.','SGK10:hinh-thanh-phat-trien-van-minh-cham-pa','2026-06-30 00:27:18'),(60973,'hinh-thanh-phat-trien-van-minh-phu-nam',10,'KNTT',NULL,'Bai 11',NULL,NULL,'Vào khoảng đầu Công nguyên, Vương quốc Phù Nam đã được thành lập trên cơ sở tập hợp nhiều tộc người, nhiều tiểu quốc. Đứng đầu nhà nước là vua, có quyền lực cao nhất, cai trị bằng cả vương quyền và thần quyền; giúp việc cho vua là các quan lại trong hệ thống chính quyền với nhiều cấp bậc.','SGK10:hinh-thanh-phat-trien-van-minh-phu-nam','2026-06-30 00:27:18'),(60974,'hinh-thanh-phat-trien-van-minh-van-lang-au-lac',10,'KNTT',NULL,'Bai 11',NULL,NULL,'Văn minh Văn Lang – Âu Lạc (còn gọi là văn minh sông Hồng, văn minh Việt cổ, văn minh Đông Sơn) có nguồn gốc bản địa, chủ nhân là các cộng đồng người Việt cổ, được hình thành và phát triển từ đấu thiên niên kỉ I TCN đến vài thế kỉ đấu Công nguyên ở khu vực Bắc Bộ và Bắc Trung Bộ Việt Nam ngày nay.','SGK10:hinh-thanh-phat-trien-van-minh-van-lang-au-lac','2026-06-30 00:27:18'),(60975,'ho-chi-minh-keu-goi-nhuong-com-se-ao-tang-gia-san-xuat',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Về đối nội, để giải quyết nạn đói, nạn dốt và khó khăn về tài chính, Chủ tịch Hồ ChíMinh kêu gọi nhân dân cả nước “Nhường cơm sẻ áo” và “Tăng gia sản xuất, kí sắc lệnh thành lập Nha Bình dân học vụ và thành lập Quỹ Độc lập, gửi thư kêu gọi các tầng lớp nhân dân hưởng ứng Tuần lễ vàng ủng hộ Chính phủ.','SGK12:ho-chi-minh-keu-goi-nhuong-com-se-ao-tang-gia-san-xuat','2026-06-30 00:27:18'),(60976,'ho-chi-minh-ki-sac-lenh-thanh-lap-nha-binh-dan-hoc-vu-va-quy-doc-lap',12,'KNTT',NULL,'Bai 16',NULL,NULL,'Về đối nội, để giải quyết nạn đói, nạn dốt và khó khăn về tài chính, Chủ tịch Hồ ChíMinh kêu gọi nhân dân cả nước “Nhường cơm sẻ áo” và “Tăng gia sản xuất, kí sắc lệnh thành lập Nha Bình dân học vụ và thành lập Quỹ Độc lập, gửi thư kêu gọi các tầng lớp nhân dân hưởng ứng Tuần lễ vàng ủng hộ Chính phủ.','SGK12:ho-chi-minh-ki-sac-lenh-thanh-lap-nha-binh-dan-hoc-vu-va-quy-doc-lap','2026-06-30 00:27:18'),(60977,'ho-khuc-to-chuc-lai-lang-xa-the-ki-x',11,'KNTT',NULL,'Bai 9',NULL,NULL,'Thế kỉ X, Họ Khúc tổ chức lại bộ máy làng xã. Làng trở thành đơn vị hành chính cấp cơ sở, gọi là xã.','SGK11:ho-khuc-to-chuc-lai-lang-xa-the-ki-x','2026-06-30 00:27:18'),(60978,'ho-khuc-to-chuc-lai-lang-xa-the-ki-x',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Thế kỉ X, Họ Khúc tổ chức lại bộ máy làng xã. Làng trở thành đơn vị hành chính cấp cơ sở, gọi là xã.','SGK11:ho-khuc-to-chuc-lai-lang-xa-the-ki-x','2026-06-30 00:27:18'),(60979,'hoan-toan-giai-phong-mien-nam-viet-nam',11,'KNTT',NULL,'Bai 4',NULL,NULL,'Sau khi hoàn toàn giải phóng miền Nam (tháng 4-1975) và thực hiện thống nhất đất nước (năm 1976), cả nước Việt Nam tiến lên xây dựng chủ nghĩa xã hội.','SGK11:hoan-toan-giai-phong-mien-nam-viet-nam','2026-06-30 00:27:18'),(60980,'ke-hoach-nha-nuoc-5-nam-lan-thu-nhat-mien-bac',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Nhân dân miền Bắc tiến hành kế hoạch Nhà nước 5 năm lần thứ nhất (1961 - 1965) với trọng tâm là xây dựng chủ nghĩa xã hội. Nhiệm vụ cơ bản là ra sức phát triển công nghiệp, nông nghiệp, củng cố và tăng cường thành phần kinh tế quốc doanh, cải thiện đời sống vật chất và văn hoá của nhân dân,... Những thành tựu đạt được làm thay đổi bộ mặt xã hội miền Bắc. Miền Bắc còn làm nghĩa vụ hậu phương lớn chi viện cho tiền tuyến miền Nam.','SGK12:ke-hoach-nha-nuoc-5-nam-lan-thu-nhat-mien-bac','2026-06-30 00:27:18'),(60981,'khang-chien-thang-loi',10,'KNTT',NULL,'Bai 14',NULL,NULL,'Lực lượng đoàn kết đã giúp kháng chiến thắng lợi.','SGK10:khang-chien-thang-loi','2026-06-30 00:27:18'),(60982,'khoi-nghia-phung-hung',11,'KNTT',NULL,'Bai 8',NULL,NULL,'Cuối thế kỉ VIII, Phùng Hưng phát động khởi nghĩa ở Đường Lâm (Sơn Tây, Hà Nội). Nghĩa quân đánh chiếm phủ thành Tổng Bình, giành quyền tự chủ trong một thời gian ngắn. Năm 791, nhà Đường đem quân sang đàn áp và chiếm lại.','SGK11:khoi-nghia-phung-hung','2026-06-30 00:27:18'),(60983,'khung-hoang-cuoi-trieu-tran',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Cuối thế kỉ XIV, nhà Trần lâm vào cuộc khủng hoảng, ngày càng suy yếu. Tầng lớp quý tộc có xu hướng ăn chơi hưởng lạc, đất nước lâm vào khủng hoảng, nhiều cuộc khởi nghĩa của nông dân và nô tì nổ ra.','SGK11:khung-hoang-cuoi-trieu-tran','2026-06-30 00:27:18'),(60984,'lang-co-ten-nom-xuat-hien-som-thoi-ly-tran',11,'KNTT',NULL,'Bai 9',NULL,NULL,'Những làng có tên nôm thường là những làng xuất hiện sớm vào thời Lý – Trần.','SGK11:lang-co-ten-nom-xuat-hien-som-thoi-ly-tran','2026-06-30 00:27:18'),(60985,'lang-xa-hinh-thanh-thoi-van-lang-au-lac',11,'KNTT',NULL,'Bai 9',NULL,NULL,'Làng xã hình thành từ các công xã nông thôn (kẻ, chiếng, chạ), đứng đầu là Bố chính (già làng) trong thời Văn Lang - Âu Lạc.','SGK11:lang-xa-hinh-thanh-thoi-van-lang-au-lac','2026-06-30 00:27:18'),(60986,'le-loi-xay-thanh-luc-nien',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Vùng đất Nam Đàn (Nghệ An) là nơi lưu nhiều dấu tích lịch sử liên quan đến Lê Lợi xây thành Lục Niên (thế kỉ XV).','SGK12:le-loi-xay-thanh-luc-nien','2026-06-30 00:27:18'),(60987,'lien-hop-quoc-vien-tro-viet-nam-1977-1986',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Trong những năm 1977 – 1986, hệ thống phát triển Liên hợp quốc đã viện trợ không hoàn lại cho Việt Nam khoảng 527,9 triệu USD.','SGK12:lien-hop-quoc-vien-tro-viet-nam-1977-1986','2026-06-30 00:27:18'),(60988,'lien-xo-vien-tro-cho-viet-nam',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Trong những năm 1955 - 1975, Liên Xô viện trợ về kinh tế – kĩ thuật cho Việt Nam trị giá khoảng 2,1 tỉ rúp và nhiều vũ khí, phương tiện quân sự,... phục vụ cho công cuộc xây dựng chủ nghĩa xã hội ở miền Bắc và chi viện cho chiến trường miền Nam.','SGK12:lien-xo-vien-tro-cho-viet-nam','2026-06-30 00:27:18'),(60989,'mai-thuc-loan-khoi-nghia',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Vùng đất Nam Đàn (Nghệ An) là nơi lưu nhiều dấu tích lịch sử liên quan đến Mai Thúc Loan dựng cờ khởi nghĩa (đầu thế kỉ VIII).','SGK12:mai-thuc-loan-khoi-nghia','2026-06-30 00:27:18'),(60990,'mien-bac-viet-nam-giai-phong-xay-dung-cnxh',11,'KNTT',NULL,'Bai 4',NULL,NULL,'Cuộc kháng chiến chống thực dân Pháp thắng lợi năm 1954, miền Bắc Việt Nam được giải phóng và đi theo con đường xây dựng chủ nghĩa xã hội.','SGK11:mien-bac-viet-nam-giai-phong-xay-dung-cnxh','2026-06-30 00:27:19'),(60991,'nguoi-viet-che-tao-sung-than-co-thuyen-chien',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Từ cuối thế kỉ XIV, người Việt đã chế tạo được súng thần cơ, đóng loại thuyền chiến cỡ lớn; thế kỉ XVI – XVII, đúc được các loại đại bác, đóng thuyền chiến trang bị đại bác có vận dụng kĩ thuật của phương Tây.','SGK10:nguoi-viet-che-tao-sung-than-co-thuyen-chien','2026-06-30 00:27:19'),(60992,'nguyen-hue-dung-chan-chieu-mo-binh-si',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Vùng đất Nam Đàn (Nghệ An) là nơi lưu nhiều dấu tích lịch sử liên quan đến Nguyễn Huệ dừng chân chiêu mộ binh sĩ (cuối thế kỉ XVIII).','SGK12:nguyen-hue-dung-chan-chieu-mo-binh-si','2026-06-30 00:27:19'),(60993,'nha-duong-dat-don-vi-huong-xa-thoi-bac-thuoc',11,'KNTT',NULL,'Bai 9',NULL,NULL,'Đến thế kỉ VII, nhà Đường đặt đơn vị hương và xã nhưng trên thực tế chính quyền đô hộ không quản lí được làng xã.','SGK11:nha-duong-dat-don-vi-huong-xa-thoi-bac-thuoc','2026-06-30 00:27:19'),(60994,'nha-ly-su-dung-thi-cu-nho-hoc',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Nhà Lý là triều đại đầu tiên chính thức sử dụng chế độ thi cử Nho học để tuyển chọn quan lại.','SGK10:nha-ly-su-dung-thi-cu-nho-hoc','2026-06-30 00:27:19'),(60995,'nha-ly-to-chuc-khoa-thi-nho-hoc-dau-tien',10,'KNTT',NULL,'Bai 9',NULL,NULL,'Nhà Lý cho... tổ chức khoa thi Nho học đầu tiên để tuyển dụng quan lại.','SGK10:nha-ly-to-chuc-khoa-thi-nho-hoc-dau-tien','2026-06-30 00:27:19'),(60996,'nha-ly-xay-dung-van-mieu',10,'KNTT',NULL,'Bai 9',NULL,NULL,'Nhà Lý cho xây dựng Văn Miếu để thờ Khổng Tử (người sáng lập Nho giáo).','SGK10:nha-ly-xay-dung-van-mieu','2026-06-30 00:27:19'),(60997,'nha-minh-xam-luoc-dai-ngu',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Giữa lúc công cuộc cải cách đang thực hiện, các mâu thuẫn xã hội diễn biến phức tạp, nhà Minh đã tận dụng cơ hội tiến hành xâm lược Đại Ngu.','SGK11:nha-minh-xam-luoc-dai-ngu','2026-06-30 00:27:19'),(60998,'nha-nuoc-can-thiep-manh-lang-xa-thoi-le-so',11,'KNTT',NULL,'Bai 9',NULL,NULL,'Thời Lê sơ: Nhà nước can thiệp mạnh vào làng xã, tổ chức bộ máy quản lí làng xã. Triều đình buộc các làng xã ghi chép các tục lệ, tập quán thành hương ước. Việc lập mới các làng xã ngày càng được đẩy mạnh nhờ chính sách khai hoang, mở rộng lãnh thổ.','SGK11:nha-nuoc-can-thiep-manh-lang-xa-thoi-le-so','2026-06-30 00:27:19'),(60999,'nha-nuoc-can-thiep-manh-lang-xa-thoi-nguyen',11,'KNTT',NULL,'Bai 9',NULL,NULL,'Thời Nguyễn: Nhà nước can thiệp mạnh vào làng xã nhằm hạn chế quyền lực của cường hào, quan viên.','SGK11:nha-nuoc-can-thiep-manh-lang-xa-thoi-nguyen','2026-06-30 00:27:19'),(61000,'nha-nuoc-pho-mac-lang-xa-thoi-le-trung-hung',11,'KNTT',NULL,'Bai 9',NULL,NULL,'Thời Lê trung hưng: Nhà nước có xu hướng \"phó mặc\" làng xã cho bộ máy cường hào, quan viên.','SGK11:nha-nuoc-pho-mac-lang-xa-thoi-le-trung-hung','2026-06-30 00:27:19'),(61001,'nho-giao-du-nhap-viet-nam',10,'KNTT',NULL,'Bai 9',NULL,NULL,'Nho giáo (Trung Quốc) du nhập vào Việt Nam từ thời Bắc thuộc.','SGK10:nho-giao-du-nhap-viet-nam','2026-06-30 00:27:19'),(61002,'phap-xam-luoc-viet-nam',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Từ giữa thế kỉ XIX, thực dân Pháp xâm lược và từng bước áp đặt ách cai trị ở Việt Nam. Dưới chế độ thực dân, nền độc lập dân tộc và quyền tự do của đại bộ phận nhân dân bị tước đoạt.','SGK12:phap-xam-luoc-viet-nam','2026-06-30 00:27:19'),(61003,'phong-trao-dong-du',12,'KNTT',NULL,'Bai 12',NULL,NULL,'Phong trào Đông du là một phong trào yêu nước tiêu biểu vào đầu thế kỉ XX với mục đích đưa thanh niên Việt Nam sang Nhật Bản học tập, chuẩn bị lực lượng, chờ thời cơ giành lại độc lập cho nước nhà.','SGK12:phong-trao-dong-du','2026-06-30 00:27:19'),(61004,'phong-trao-dong-khoi',12,'KNTT',NULL,'Bai 8',NULL,NULL,'Phong trào Đồng khởi bắt đầu từ các cuộc nổi dậy của nhân dân Vĩnh Thạnh (Bình Định), Bắc Ái (Ninh Thuận) tháng 2 – 1959; Trà Bồng (Quảng Ngãi) tháng 8 – 1959, rồi lan khắp miền Nam, tiêu biểu là cuộc Đồng khởi ở Bến Tre tháng 1 – 1960.','SGK12:phong-trao-dong-khoi','2026-06-30 00:27:19'),(61005,'phong-trao-tay-son-bung-no',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Cuối thế kỉ XVIII, phong trào Tây Sơn bùng nổ và lan rộng, lật đổ các chính quyển phong kiến trong nước, đánh tan quân xâm lược Xiêm và Mãn Thanh, xoá bỏ tình trạng chia cắt đất nước, thành lập vương triều, tạo nền tảng cho sự thống nhất quốc gia.','SGK10:phong-trao-tay-son-bung-no','2026-06-30 00:27:19'),(61006,'phu-nam-tro-thanh-vuong-quoc-hung-manh',10,'KNTT',NULL,'Bai 11',NULL,NULL,'Trong khoảng hơn hai thế kỉ đầu sau khi thành lập, tổ chức nhà nước Phù Nam còn đơn giản. Từ thế kỉ III đến thế kỉ V, tổ chức nhà nước ngày càng được hoàn thiện. Phù Nam vươn lên trở thành vương quốc hùng mạnh, có ảnh hưởng rộng ra nhiều vùng đất ở khu vực Đông Nam Á.','SGK10:phu-nam-tro-thanh-vuong-quoc-hung-manh','2026-06-30 00:27:19'),(61007,'su-ra-doi-nha-nuoc-van-lang',10,'KNTT',NULL,'Bai 11',NULL,NULL,'Nhà nước Văn Lang xuất hiện cách ngày nay khoảng 2 700 năm và tồn tại đến năm 208 TCN; kinh đô là Phong Châu (Việt Trì, Phú Thọ ngày nay). Tổ chức nhà nước Văn Lang còn khá sơ khai.','SGK10:su-ra-doi-nha-nuoc-van-lang','2026-06-30 00:27:19'),(61008,'tan-cong-champa-dai-viet-cuoi-tk14',11,'KNTT',NULL,'Bai 12',NULL,NULL,'Trong khoảng 30 năm cuối thế kỉ XIV, Chăm-pa đã 16 lần tấn công Đại Việt. Nhiều lần nhà Trần đem quân chống cự nhưng cũng ít lần bị thất bại.','SGK11:tan-cong-champa-dai-viet-cuoi-tk14','2026-06-30 00:27:19'),(61009,'thanh-lap-cac-dang-cong-san-o-viet-nam-ma-lai-xiem-phi-lip-pin',11,'KNTT',NULL,'Bai 6',NULL,NULL,'Trong những năm 30 của thế kỉ XX, các đảng cộng sản được thành lập ở Việt Nam, Mã Lai, Xiêm và Phi-líp-pin, góp phần mở ra khuynh hướng vô sản trong cuộc đấu tranh giành độc lập dân tộc ở Đông Nam Á.','SGK11:thanh-lap-cac-dang-cong-san-o-viet-nam-ma-lai-xiem-phi-lip-pin','2026-06-30 00:27:19'),(61010,'thanh-lap-lang-xa-huyen-tien-hai-thai-binh',11,'KNTT',NULL,'Bai 9',NULL,NULL,'Làng xã thuộc huyện Tiền Hải (Thái Bình) được thành lập vào đầu thế kỉ XIX không có tên nôm.','SGK11:thanh-lap-lang-xa-huyen-tien-hai-thai-binh','2026-06-30 00:27:19'),(61011,'thanh-lap-quoc-su-quan-trieu-nguyen',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Triều Nguyễn thành lập Quốc sử quản, biên soạn nhiều công trình sử học, tiêu biểu như: Đại Nam thực lục, Khâm định Việt sử thông giám cương mục,...','SGK10:thanh-lap-quoc-su-quan-trieu-nguyen','2026-06-30 00:27:19'),(61012,'thanh-lap-va-hoat-dong-doi-dan-binh-hoang-sa-bac-hai',11,'KNTT',NULL,'Bai 16',NULL,NULL,'Hoạt động xác lập chủ quyền, quản lí liên tục mang tính nhà nước đối với quần đảo Hoàng Sa và quần đảo Trường Sa được khẳng định thông qua việc thành lập và hoạt động của các đội dân binh Hoàng Sa và Bắc Hải. Các đội dân binh này hoạt động trong suốt thời gian từ thế kỉ XVII đến đầu thế kỉ XIX, vừa làm nhiệm vụ kiểm soát, vừa khai thác tài nguyên ở các đảo thuộc hai quần đảo này. Dưới triều Nguyễn, hai đội Hoàng Sa và Bắc Hải còn phối hợp cùng thuỷ quân đi khảo sát, đo đạc để vẽ bản đồ, cắm cột mốc, dựng bia chủ quyền, xây dựng miếu thờ, đào giếng, trồng cây,... trên quần đảo Hoàng Sa và quần đảo Hoàng Sa.','SGK11:thanh-lap-va-hoat-dong-doi-dan-binh-hoang-sa-bac-hai','2026-06-30 00:27:19'),(61013,'thoi-tran-dat-chuc-xa-quan',11,'KNTT',NULL,'Bai 9',NULL,NULL,'Thời Trần: Đặt chức xã quan và các chức đứng đầu bộ máy quản lí cấp xã (đại tư xã, tiểu tư xã,..).','SGK11:thoi-tran-dat-chuc-xa-quan','2026-06-30 00:27:19'),(61014,'thuc-hien-thong-nhat-dat-nuoc-viet-nam',11,'KNTT',NULL,'Bai 4',NULL,NULL,'Sau khi hoàn toàn giải phóng miền Nam (tháng 4-1975) và thực hiện thống nhất đất nước (năm 1976), cả nước Việt Nam tiến lên xây dựng chủ nghĩa xã hội.','SGK11:thuc-hien-thong-nhat-dat-nuoc-viet-nam','2026-06-30 00:27:19'),(61015,'thuong-mai-a-au-phat-trien-tai-dai-viet',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Từ thế kỉ XVI, đặc biệt trong thế kỉ XVII, khi thương mại Á – Âu phát triển, các công ti như Công ti Đông Ấn Hà Lan, Công ti Đông Ấn Anh và thương nhân Trung Quốc, Nhật Bản, Đông Nam Á,... đã đến Đại Việt buôn bán nhộn nhịp ở khắp cả nước.','SGK10:thuong-mai-a-au-phat-trien-tai-dai-viet','2026-06-30 00:27:19'),(61016,'tin-nguong-tho-than-dong-co-cung-dinh',10,'KNTT',NULL,'Bai 12',NULL,NULL,'Tín ngưỡng thờ thần Đồng Cổ (thần Trống đồng) được đưa vào cung đình từ thời Lý, được triều đình bảo trợ và phát triển dưới hình thức một nghi lễ nhằm giữ đạo trung với vua, với quốc gia.','SGK10:tin-nguong-tho-than-dong-co-cung-dinh','2026-06-30 00:27:19'),(61017,'trang-an-duoc-ghi-danh-di-san-the-gioi',10,'KNTT',NULL,'Bai 3',NULL,NULL,'Quần thể danh thắng Tràng An (Ninh Bình) là Di sản thế giới hỗn hợp đầu tiên của Việt Nam. Để chuẩn bị hồ sơ khoa học thuyết minh về di sản trình UNESCO, nhiệm vụ nghiên cứu toàn diện về giá trị lịch sử – văn hoá, địa chất địa mạo, giá trị thẩm mĩ,... của danh thắng đã được triển khai. Nhờ đó, danh thắng Tràng An đã được ghi danh là Di sản văn hoá và thiên nhiên thế giới.','SGK10:trang-an-duoc-ghi-danh-di-san-the-gioi','2026-06-30 00:27:19'),(61018,'tuyen-duong-chi-vien-chien-luoc-tren-bien-mang-ten-chu-tich-ho-chi-minh',12,'KNTT',NULL,'Bai 17',NULL,NULL,'Trong cuộc kháng chiến chống Mỹ, cứu nước, tuyến đường chỉ viện chiến lược trên biển mang tên Chủ tịch Hồ Chí Minh là con đường huyền thoại, biểu tượng cho khát vọng độc lập, tự do và thống nhất Tổ quốc. Tuyến đường này đã kết nối hậu phương lớn miền Bắc với tiến tuyến lớn miền Nam, vận chuyển kịp thời, hiệu quả vũ khí và lực lượng, góp phần quan trọng vào Đại thắng Xuân năm 1975.','SGK12:tuyen-duong-chi-vien-chien-luoc-tren-bien-mang-ten-chu-tich-ho-chi-minh','2026-06-30 00:27:19'),(61019,'van-hoa-phung-nguyen',10,'KNTT',NULL,'Bai 11',NULL,NULL,'Văn hoá Phùng Nguyên (khoảng 4000 năm trước) là cội nguồn của văn minh Văn Lang – Âu Lạc.','SGK10:van-hoa-phung-nguyen','2026-06-30 00:27:20'),(61020,'van-hoa-sa-huynh',10,'KNTT',NULL,'Bai 11',NULL,NULL,'Khoảng thế kỉ V TCN, cư dân văn hoá Sa Huỳnh cư trú ở vùng duyên hải, lưu vực các con sông và sâu trong nội địa. Cơ cấu xã hội Sa Huỳnh là xã hội dạng lãnh địa hay liên minh cụm làng, đứng đầu là thủ lĩnh tối cao. Sự phát triển nội tại của những tổ chức xã hội này là cơ sở quan trọng cho sự hình thành của Nhà nước Chăm-pa sau này.','SGK10:van-hoa-sa-huynh','2026-06-30 00:27:20'),(61021,'van-hoa-tien-oc-eo',10,'KNTT',NULL,'Bai 11',NULL,NULL,'Văn minh Phù Nam có cội nguồn từ nền văn hoá lâu đời ở khu vực Nam Bộ – văn hoá tiền Óc Eo. Khoảng cuối thiên niên kỉ I TCN, sản xuất nông nghiệp, thủ công nghiệp và trao đổi hàng hoá ngày càng phát triển; cấu trúc làng nông - chài – thương nghiệp hình thành, chuẩn bị cho sự ra đời của các đô thị sơ khai ở một số vùng đất thuộc Nam Bộ.','SGK10:van-hoa-tien-oc-eo','2026-06-30 00:27:20'),(61022,'viet-nam-dam-phan-ranh-gioi-tren-bien',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Việt Nam đã đàm phán về ranh giới trên biển với Ma-lai-xi-a, In-đô-nê-xi-a, Phi-líp-pin và và Thái Lan, giải quyết các bất đồng bằng con đường đàm phán, thương lượng.','SGK12:viet-nam-dam-phan-ranh-gioi-tren-bien','2026-06-30 00:27:20'),(61023,'viet-nam-hoan-tat-muc-tieu-thien-nien-ki',12,'KNTT',NULL,'Bai 11',NULL,NULL,'Đến 2015, Việt Nam đã hoàn tất việc thực hiện các Mục tiêu Thiên niên kỉ (MDGs) của Liên hợp quốc như: xoá đói, giảm nghèo, đạt phổ cập giáo dục tiểu học, thúc đẩy bình đẳng giới và đạt nhiều tiến bộ trong chỉ tiêu về y tế.','SGK12:viet-nam-hoan-tat-muc-tieu-thien-nien-ki','2026-06-30 00:27:20'),(61024,'viet-nam-ki-ket-evfta',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Việt Nam kí kết Hiệp định Thương mại tự do Việt Nam - EU (EVFTA).','SGK12:viet-nam-ki-ket-evfta','2026-06-30 00:27:20'),(61025,'viet-nam-ki-ket-hiep-uoc-bien-gioi-trung-quoc',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Đối với Trung Quốc, Việt Nam kí kết các hiệp ước về biên giới trên đất liền và phân định vịnh Bắc Bộ, giải quyết những tranh chấp thông qua biện pháp hoà bình.','SGK12:viet-nam-ki-ket-hiep-uoc-bien-gioi-trung-quoc','2026-06-30 00:27:20'),(61026,'viet-nam-ki-ket-nghi-dinh-thu-ki-o-to',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Việt Nam tham gia đàm phán quốc tế về biến đổi khí hậu, kí kết Nghị định thư Ki-ô-tô, cam kết giảm lượng phát thải khí nhà kính.','SGK12:viet-nam-ki-ket-nghi-dinh-thu-ki-o-to','2026-06-30 00:27:20'),(61027,'viet-nam-ki-ket-rcep',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Việt Nam kí kết Hiệp định Đối tác kinh tế toàn diện Khu vực (RCEP).','SGK12:viet-nam-ki-ket-rcep','2026-06-30 00:27:20'),(61028,'viet-nam-lao-cam-pu-chia-chuyen-sang-kinh-te-thi-truong-va-cong-nghiep-hoa',11,'KNTT',NULL,'Bai 6',NULL,NULL,'Các nước Việt Nam, Lào, Cam-pu-chia từng bước chuyển sang nền kinh tế thị trường và tiến hành công nghiệp hóa từ cuối thập kỉ 80 – 90 của thế kỉ XX.','SGK11:viet-nam-lao-cam-pu-chia-chuyen-sang-kinh-te-thi-truong-va-cong-nghiep-hoa','2026-06-30 00:27:20'),(61029,'viet-nam-mo-co-quan-dai-dien-ngoai-giao-va-thong-tin-o-nuoc-ngoai',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Việt Nam mở các cơ quan đại diện ngoại giao tại một số nước châu Á và các cơ quan thông tin ở một số nước trên thế giới.','SGK12:viet-nam-mo-co-quan-dai-dien-ngoai-giao-va-thong-tin-o-nuoc-ngoai','2026-06-30 00:27:20'),(61030,'viet-nam-tham-gia-afta',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Việt Nam kí hiệp định tham gia Khu vực Mậu dịch tự do ASEAN (AFTA).','SGK12:viet-nam-tham-gia-afta','2026-06-30 00:27:20'),(61031,'viet-nam-thoan-thuan-bien-gioi-lao-cam-pu-chia',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Với Lào và Cam-pu-chia, Việt Nam đã đạt được nhiều thoả thuận trong phát triển đường biên giới hoà bình, hữu nghị.','SGK12:viet-nam-thoan-thuan-bien-gioi-lao-cam-pu-chia','2026-06-30 00:27:20'),(61032,'viet-nam-to-chuc-hoi-nghi-quoc-te-asean-asem-apec',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Việt Nam đã tổ chức thành công nhiều hội nghị quốc tế quan trọng thuộc ASEAN, ASEM và APEC.','SGK12:viet-nam-to-chuc-hoi-nghi-quoc-te-asean-asem-apec','2026-06-30 00:27:20'),(61033,'viet-nam-uy-vien-khong-thuong-truc-hoi-dong-bao-an-lhq',12,'KNTT',NULL,'Bai 14',NULL,NULL,'Việt Nam hai lần được bầu với số phiếu cao vào vị trí Uỷ viên không thường trực Hội đồng Bảo an Liên hợp quốc nhiệm kì 2008 – 2009 và 2020 - 2021.','SGK12:viet-nam-uy-vien-khong-thuong-truc-hoi-dong-bao-an-lhq','2026-06-30 00:27:20'),(61034,'vndcch-can-bang-quan-he-voi-lien-xo-trung-quoc-va-van-dong-vien-tro',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Việt Nam Dân chủ Cộng hoà khéo léo cân bằng quan hệ với Liên Xô, Trung Quốc; vận động các nước xã hội chủ nghĩa viện trợ cho công cuộc xây dựng chủ nghĩa xã hội ở miền Bắc, ủng hộ cuộc kháng chiến ở miền Nam.','SGK12:vndcch-can-bang-quan-he-voi-lien-xo-trung-quoc-va-van-dong-vien-tro','2026-06-30 00:27:20'),(61035,'vndcch-dau-tranh-doi-thi-hanh-hiep-dinh-gio-ne-vo',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Việt Nam Dân chủ Cộng hoà phối hợp với Uỷ ban Giám sát quốc tế về Hiệp định Giơ-ne-vơ yêu cầu chính quyền Sài Gòn mở hội nghị hiệp thương về việc tổ chức tổng tuyển cử thống nhất đất nước theo những điều khoản của hội nghị.','SGK12:vndcch-dau-tranh-doi-thi-hanh-hiep-dinh-gio-ne-vo','2026-06-30 00:27:20'),(61036,'vndcch-gap-go-dang-cong-san-phap-va-cac-to-chuc-quoc-te',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Chính phủ Việt Nam Dân chủ Cộng hoà gặp gỡ đại diện Đảng Cộng sản Pháp và nhiều tổ chức quốc tế, thành lập các hội hữu nghị và Uỷ ban Bảo vệ hoà bình thế giới.','SGK12:vndcch-gap-go-dang-cong-san-phap-va-cac-to-chuc-quoc-te','2026-06-30 00:27:20'),(61037,'vndcch-thiet-lap-quan-he-ngoai-giao-voi-lao-campuchia-va-ung-ho-phong-trao-giai-phong-dan-toc',12,'KNTT',NULL,'Bai 13',NULL,NULL,'Việt Nam Dân chủ Cộng hoà thiết lập quan hệ ngoại giao với Lào, xây dựng quan hệ láng giềng hữu nghị với Cam-pu-chia; ủng hộ cuộc đấu tranh chống chủ nghĩa thực dân của nhân dân các nước Á, Phi Mỹ La-tinh,... phát triển mối quan hệ liên minh chiến đấu chống các lực lượng yêu nước, kháng chiến của Lào, Cam-pu-chia.','SGK12:vndcch-thiet-lap-quan-he-ngoai-giao-voi-lao-campuchia-va-ung-ho-phong-trao-giai-phong-dan-toc','2026-06-30 00:27:20'),(61038,'vu-an-le-chi-vien',11,'KNTT',NULL,'Bai 13',NULL,NULL,'Sự lộng hành của một số quyền thần đã gây nên vụ án oan \'Lệ Chi Viên\' tru di tam tộc gia đình Nguyễn Trãi.','SGK11:vu-an-le-chi-vien','2026-06-30 00:27:20'),(61039,'vuong-thuc-mau-khoi-nghia-can-vuong',12,'KNTT',NULL,'Bai 15',NULL,NULL,'Vùng đất Nam Đàn (Nghệ An) là nơi lưu nhiều dấu tích lịch sử liên quan đến Vương Thúc Mậu khởi nghĩa hưởng ứng Dụ Cần vương (cuối thế kỉ XIX).','SGK12:vuong-thuc-mau-khoi-nghia-can-vuong','2026-06-30 00:27:20'),(61040,'xa-lan-dau-tien-xuat-hien',11,'KNTT',NULL,'Bai 9',NULL,NULL,'Xã lần đầu tiên xuất hiện vào đầu thế kỉ VII.','SGK11:xa-lan-dau-tien-xuat-hien','2026-06-30 00:27:20'),(61041,'xa-tro-thanh-ten-goi-pho-bien',11,'KNTT',NULL,'Bai 9',NULL,NULL,'Xã chính thức trở thành tên gọi phổ biến từ thế kỉ X, dùng để chỉ đơn vị hành chính cơ sở của nhà nước.','SGK11:xa-tro-thanh-ten-goi-pho-bien','2026-06-30 00:27:20');
/*!40000 ALTER TABLE `event_textbook_refs` ENABLE KEYS */;
