DROP TABLE IF EXISTS `event_relations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `event_relations` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `source_event_id` varchar(160) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `target_event_id` varchar(160) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `relation_type` enum('related','predecessor','successor','same_topic','same_location') COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  UNIQUE KEY `uk_event_relation` (`source_event_id`,`target_event_id`,`relation_type`),
  KEY `idx_relation_source_type` (`source_event_id`,`relation_type`,`sort_order`),
  KEY `idx_relation_target_type` (`target_event_id`,`relation_type`),
  CONSTRAINT `fk_event_relations_source` FOREIGN KEY (`source_event_id`) REFERENCES `historical_events` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_event_relations_target` FOREIGN KEY (`target_event_id`) REFERENCES `historical_events` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci AUTO_INCREMENT=30685;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `event_relations` WRITE;
/*!40000 ALTER TABLE `event_relations` DISABLE KEYS */;
/*!40000 ALTER TABLE `event_relations` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `data_import_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `data_import_runs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `source_name` varchar(255) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `source_path` varchar(1000) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `source_hash` char(64) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `import_type` enum('event_json','media','textbook_ref','rag_seed') COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `event_count` int NOT NULL DEFAULT '0',
  `created_count` int NOT NULL DEFAULT '0',
  `updated_count` int NOT NULL DEFAULT '0',
  `skipped_count` int NOT NULL DEFAULT '0',
  `failed_count` int NOT NULL DEFAULT '0',
